package com.github.orgonag.fbclan;

import com.github.orgonag.fbclan.drops.DropRules;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

// Key names are stable across versions so members' settings survive.
@ConfigGroup("finalboss")
public interface FinalBossConfig extends Config
{
    @ConfigSection(name = "Drop Logging", description = "Settings for drop logging", position = 0)
    String dropLoggingSection = "dropLogging";

    @ConfigSection(name = "Looking For Group", description = "Settings for the LFG party board", position = 1)
    String lfgSection = "lfg";

    @ConfigSection(name = "Discord Integration", description = "Settings for Discord webhook", position = 2)
    String discordSection = "discord";

    @ConfigSection(name = "Leaderboards", description = "Clan leaderboards settings", position = 3)
    String leaderboardsSection = "leaderboards";

    // ------------------------------------------------------------ drops

    @ConfigItem(
        keyName = "enableDropLogging",
        name = "Enable Drop Logging",
        description = "Log valuable drops to the clan database. On by default for verified clan members — disable to opt out.",
        section = dropLoggingSection,
        position = 0
    )
    default boolean enableDropLogging()
    {
        return true;
    }

    @Range(min = DropRules.MIN_THRESHOLD_GP)
    @ConfigItem(
        keyName = "dropThresholdGp",
        name = "Valuable drop threshold (GP)",
        description = "Any drop worth at least this much (GE price x quantity) is logged, rare or not — 1m minimum",
        section = dropLoggingSection,
        position = 1
    )
    default int dropThresholdGp()
    {
        return DropRules.MIN_THRESHOLD_GP;
    }

    @Range(min = DropRules.MIN_RARE_DENOMINATOR, max = 1_000_000)
    @ConfigItem(
        keyName = "rareDropThreshold",
        name = "Rare drop threshold (1 in X)",
        description = "Log drops whose drop rate is 1 in X or rarer, even below the valuable threshold. "
            + "250 = 1 in 250 or rarer (the minimum). Uses the OSRS Wiki drop table; "
            + "drops it doesn't cover only qualify by value or the clan's notable list.",
        section = dropLoggingSection,
        position = 2
    )
    default int rareDropThreshold()
    {
        return DropRules.MIN_RARE_DENOMINATOR;
    }

    @Range(min = 0)
    @ConfigItem(
        keyName = "rareDropMinValueGp",
        name = "Rare drop min value (GP)",
        description = "A rare drop must also be worth at least this much to be logged, so rare junk "
            + "stays out. Set to 0 to log every rare drop regardless of value (untradeables included).",
        section = dropLoggingSection,
        position = 3
    )
    default int rareDropMinValueGp()
    {
        return 100_000;
    }

    @ConfigItem(
        keyName = "enableDropScreenshots",
        name = "Screenshot Drops",
        description = "Save a picture of your whole client with each drop you log. Stored publicly: anyone with the link can view it.",
        section = dropLoggingSection,
        position = 4
    )
    default boolean enableDropScreenshots()
    {
        return false;
    }

    // ------------------------------------------------------------ lfg

    @ConfigItem(
        keyName = "enableLfg",
        name = "Enable LFG",
        description = "Enable the Looking For Group party board and the !lfg chat command",
        section = lfgSection,
        position = 0
    )
    default boolean enableLfg()
    {
        return true;
    }

    @ConfigItem(
        keyName = "lfgPartyNotifications",
        name = "Party chat notifications",
        description = "Post LFG party events to your chatbox: applicants to your party, "
            + "your application being accepted or declined, and parties you're in forming or being disbanded",
        section = lfgSection,
        position = 1
    )
    default boolean lfgPartyNotifications()
    {
        return true;
    }

    @ConfigItem(
        keyName = "lfgDesktopNotifications",
        name = "Party desktop notifications",
        description = "Also send a desktop notification for LFG party events (uses RuneLite's notification settings)",
        section = lfgSection,
        position = 2
    )
    default boolean lfgDesktopNotifications()
    {
        return false;
    }

    @ConfigItem(
        keyName = "lfgKcLookups",
        name = "Kill count lookups",
        description = "Look up kill counts on the public OSRS hiscores when an applicant's client didn't "
            + "send one, and to prefill your own on the apply form",
        section = lfgSection,
        position = 3
    )
    default boolean lfgKcLookups()
    {
        return true;
    }

    // ------------------------------------------------------------ discord

    @ConfigItem(
        keyName = "discordWebhookUrl",
        name = "Discord Webhook URL",
        description = "Discord webhook URL for drop notifications (leave empty to disable)",
        section = discordSection,
        position = 0
    )
    default String discordWebhookUrl()
    {
        return "";
    }

    // ------------------------------------------------------------ leaderboards

    @ConfigItem(
        keyName = "enablePbUpload",
        name = "Upload personal bests",
        description = "Send your boss personal-best times (RSN, boss name, time) to the clan's leaderboard database. "
            + "On by default — disable to opt out. Skipped on Leagues/Deadman/speedrun worlds.",
        section = leaderboardsSection,
        position = 0
    )
    default boolean enablePbUpload()
    {
        return true;
    }

    @ConfigItem(
        keyName = "enableStatsUpload",
        name = "Upload collection log & CA",
        description = "Send your collection log count and combat achievement points (with your RSN) "
            + "to the clan's dashboard. On by default — disable to opt out. "
            + "Skipped on Leagues/Deadman/speedrun worlds.",
        section = leaderboardsSection,
        position = 1
    )
    default boolean enableStatsUpload()
    {
        return true;
    }

    @ConfigItem(
        keyName = "enableChatBadges",
        name = "CA slayer helm chat icons",
        description = "Show the Tztok/Vampyric/Tzkal slayer helmet next to clan members' names in chat "
            + "for Elite/Master/Grandmaster combat achievement tiers",
        section = leaderboardsSection,
        position = 2
    )
    default boolean enableChatBadges()
    {
        return true;
    }
}

package com.github.orgonag.fbclan;

import com.github.orgonag.fbclan.clan.ClanContent;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.drops.DropLogger;
import com.github.orgonag.fbclan.drops.DropRates;
import com.github.orgonag.fbclan.drops.DropRules;
import com.github.orgonag.fbclan.lfg.Killcounts;
import com.github.orgonag.fbclan.lfg.LfgCommand;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import com.github.orgonag.fbclan.pbs.PersonalBests;
import com.github.orgonag.fbclan.stats.CaBadges;
import com.github.orgonag.fbclan.stats.MemberStats;
import com.github.orgonag.fbclan.ui.AnnouncementsTab;
import com.github.orgonag.fbclan.ui.DropLogTab;
import com.github.orgonag.fbclan.ui.PartiesTab;
import com.github.orgonag.fbclan.ui.Sidebar;
import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Clan plugin for the Final Boss OSRS clan (wiseoldman.net group 1055).
 *
 * External services: Wise Old Man (one read per login to verify
 * membership), the clan's Supabase database (drop log, LFG parties,
 * screenshots, personal bests, member stats, and the read-only curated
 * content), the OSRS hiscores via RuneLite's client (optional LFG kill
 * counts), and an optional user-supplied Discord webhook. Nothing about
 * the player leaves the client until the WOM check passes; each upload
 * can be switched off individually. See {@link FinalBossConfig}.
 */
@Slf4j
@PluginDescriptor(
    name = "Final Boss",
    description = "Clan tools for Final Boss — announcements, drop log, LFG, and PB leaderboards",
    tags = {"clan", "final boss", "drops", "lfg", "looking for group", "leaderboard", "personal best", "pb", "announcements"}
)
public class FinalBossPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private ScheduledExecutorService executor;
    @Inject private FinalBossConfig config;
    @Inject private Clan clan;
    @Inject private ClanContent content;
    @Inject private DropRates dropRates;
    @Inject private DropLogger drops;
    @Inject private PersonalBests pbs;
    @Inject private MemberStats stats;
    @Inject private CaBadges badges;
    @Inject private PartyBoard parties;
    @Inject private Killcounts killcounts;
    @Inject private LfgCommand lfgCommand;
    // Swing: built in startUp (on the EDT), not at injection time.
    private Sidebar sidebar;
    private AnnouncementsTab announcementsTab;
    private DropLogTab dropLogTab;
    private PartiesTab partiesTab;

    private NavigationButton navButton;
    private ScheduledFuture<?> dropRefresh;
    // CA icon tiers loaded this client session.
    private volatile boolean badgesLoaded;

    @Provides
    FinalBossConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(FinalBossConfig.class);
    }

    @Override
    protected void startUp()
    {
        sidebar = injector.getInstance(Sidebar.class);
        announcementsTab = injector.getInstance(AnnouncementsTab.class);
        dropLogTab = injector.getInstance(DropLogTab.class);
        partiesTab = injector.getInstance(PartiesTab.class);
        // Locked until this session's membership check passes (a re-enable starts over).
        sidebar.showLoggedOut();
        clan.activate();
        clan.setListener(this::onStatus);
        // Once per client session: the welcome line and the CA icon list.
        content.resetSession();
        badgesLoaded = false;

        // Startup fetches, all off the client thread.
        executor.submit(dropRates::load);
        executor.submit(this::loadContent);
        // Warms the cache and populates the tab before it's first opened.
        announcementsTab.refresh();

        navButton = NavigationButton.builder()
            .tooltip("Final Boss")
            .icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
            .priority(10)
            .panel(sidebar)
            .build();
        toolbar.addNavigation(navButton);

        // Enabled mid-session: no LOGGED_IN event will fire.
        clientThread.invokeLater(() -> {
            if (client.getGameState() == GameState.LOGGED_IN) clan.verifyAfter(0);
        });
    }

    @Override
    protected void shutDown()
    {
        clan.deactivate();
        stopPolling();
        SwingUtilities.invokeLater(sidebar::closeWindows);
        toolbar.removeNavigation(navButton);
    }

    private void onStatus(Clan.Status status)
    {
        long generation = clan.snapshot().getGeneration();
        SwingUtilities.invokeLater(() -> {
            if (clan.snapshot().getGeneration() != generation) return;
            sidebar.show(status);
            if (status == Clan.Status.MEMBER)
            {
                sidebar.refreshActiveTab();
            }
        });
        if (status != Clan.Status.MEMBER)
        {
            return;
        }
        startPolling();
        // Retries whatever the startup fetch missed.
        executor.submit(this::loadContent);
        // World-type and varp reads belong on the client thread.
        clientThread.invokeLater(() -> {
            pbs.sync();
            stats.maybeSubmit();
            executor.submit(drops::flush);
        });
    }

    private void loadContent()
    {
        content.loadMissing();
        content.maybeShowWelcome();
    }

    private void startPolling()
    {
        parties.start();
        // The feed refreshes whether or not this player uploads their own drops.
        if (dropRefresh == null)
        {
            dropRefresh = executor.scheduleAtFixedRate(() -> {
                try
                {
                    dropLogTab.refresh();
                }
                catch (Exception e)
                {
                    log.warn("Drop refresh error", e);
                }
            }, 60, 60, TimeUnit.SECONDS);
        }
        loadBadges();
    }

    // CA icon tiers: once per client session, and only while the icons are on.
    private void loadBadges()
    {
        if (config.enableChatBadges() && !badgesLoaded)
        {
            executor.submit(() -> {
                badgesLoaded = badges.refresh();
            });
        }
    }

    private void stopPolling()
    {
        parties.stop();
        SwingUtilities.invokeLater(partiesTab::reset);
        killcounts.clear();
        if (dropRefresh != null)
        {
            dropRefresh.cancel(true);
            dropRefresh = null;
        }
    }

    // ------------------------------------------------------------ events

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            if (!clan.isVerified())
            {
                // Let the login flow settle before reading the player name.
                clan.verifyAfter(3);
            }
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN && (clan.isVerified() || clan.rsn() != null))
        {
            clan.reset();
            stopPolling();
            SwingUtilities.invokeLater(() -> {
                sidebar.closeWindows();
                sidebar.showLoggedOut();
            });
        }
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        clan.reset();
        stopPolling();
        boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
        SwingUtilities.invokeLater(() -> {
            sidebar.closeWindows();
            if (loggedIn) sidebar.show(Clan.Status.VERIFYING);
            else sidebar.showLoggedOut();
        });
        if (loggedIn) clan.verifyAfter(1);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        // Only two settings start or stop something; the rest are read when
        // used. (Restarting on any change would wipe a half-filled LFG form.)
        if (!"finalboss".equals(event.getGroup())) return;
        if ("enableChatBadges".equals(event.getKey()))
        {
            if (clan.isVerified()) loadBadges();
        }
        else if ("enableLfg".equals(event.getKey()))
        {
            clientThread.invokeLater(() -> {
                stopPolling();
                if (clan.isVerified()) startPolling();
            });
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (event.getContainerId() == InventoryID.INV)
        {
            drops.onInventoryChanged(event.getItemContainer());
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        drops.onTick();
        // Retry waiting drop uploads about every 30 seconds.
        if (client.getTickCount() % 50 == 0)
        {
            executor.submit(drops::flush);
        }
        // PBs (from RuneLite's own records) and CL/CA stats: every 30 minutes.
        if (client.getTickCount() % 3000 == 0)
        {
            pbs.sync();
            stats.maybeSubmit();
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        if (event.getNpc().getName() != null) drops.onLoot(event.getNpc().getName(), event.getItems(), false);
    }

    // Loot with no NPC kill behind it: raid chests, Barrows, and the few
    // bosses whose reward-chest loot the Loot Tracker reports as an NPC
    // record without an NPC-kill event (Gauntlet, Whisperer, Araxxor,
    // Royal Titans). Requires the core Loot Tracker plugin (on by default).
    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        boolean chestNpc = event.getType() == LootRecordType.NPC && DropRules.CHEST_LOOT_NPCS.contains(event.getName());
        if (event.getType() == LootRecordType.EVENT || chestNpc)
        {
            drops.onLoot(event.getName(), event.getItems(), true);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        drops.onChatMessage(event);
        if (config.enableChatBadges())
        {
            badges.onChatMessage(event);
        }
        lfgCommand.onChatMessage(event);
    }
}

package com.github.orgonag.fbclan.clan;

import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

/**
 * Clan-curated, read-only content: announcements, the once-per-session
 * welcome message, and the notable-items list. All three live in
 * Supabase tables written solely by the clan's sheet-sync script; the
 * plugin only reads them. Fetches run on the executor and fail soft,
 * keeping the previous value.
 */
@Singleton
public class ClanContent
{
    @Value
    public static class Announcement
    {
        String date;  // YYYY-MM-DD, may be blank
        String title;
        String body;  // newlines preserved
    }

    private static final int MAX_TITLE = 200;
    private static final int MAX_BODY = 10_000;
    private static final int MAX_WELCOME = 200;
    private static final String WELCOME_COLOR = "a020f0";

    private final Supabase db;
    private final Clan clan;
    private final Client client;
    private final ClientThread clientThread;

    private volatile List<Announcement> announcements = Collections.emptyList();
    private volatile Set<String> notableItems = Collections.emptySet();
    private volatile String welcome = "";
    private volatile boolean welcomeShown;
    private volatile boolean notableLoaded;
    private volatile boolean welcomeLoaded;

    @Inject
    public ClanContent(Supabase db, Clan clan, Client client, ClientThread clientThread)
    {
        this.db = db;
        this.clan = clan;
        this.client = client;
        this.clientThread = clientThread;
    }

    public List<Announcement> announcements()
    {
        return announcements;
    }

    // Normalized item-name keys (see Names.itemKey).
    public Set<String> notableItems()
    {
        return notableItems;
    }

    public void resetSession()
    {
        welcomeShown = false;
        notableLoaded = false;
        welcomeLoaded = false;
    }

    // ------------------------------------------------------------ fetches

    // Fetch failures keep the previous value; an empty table clears it.
    public boolean refreshAnnouncements()
    {
        JsonArray rows = db.getOrNull("announcements", "select=posted_at,title,body&order=posted_at.desc,sort_order.asc");
        if (rows == null)
        {
            return false;
        }
        List<Announcement> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            JsonObject row = el.getAsJsonObject();
            String title = cap(Supabase.str(row, "title"), MAX_TITLE);
            String body = cap(Supabase.str(row, "body"), MAX_BODY);
            if (!title.isEmpty() || !body.isEmpty())
            {
                out.add(new Announcement(Supabase.str(row, "posted_at"), title, body));
            }
        }
        announcements = Collections.unmodifiableList(out);
        return true;
    }

    // Executor. Once per client session (both change rarely); a failed
    // fetch is tried again at the next call.
    public void loadMissing()
    {
        if (!notableLoaded) refreshNotableItems();
        if (!welcomeLoaded) refreshWelcome();
    }

    private void refreshNotableItems()
    {
        JsonArray rows = db.getOrNull("notable_items", "select=name");
        if (rows == null)
        {
            return;
        }
        notableLoaded = true;
        Set<String> names = new HashSet<>();
        for (JsonElement el : rows)
        {
            String key = Names.itemKey(Supabase.str(el.getAsJsonObject(), "name"));
            if (!key.isEmpty())
            {
                names.add(key);
            }
        }
        notableItems = Collections.unmodifiableSet(names);
    }

    private void refreshWelcome()
    {
        JsonArray rows = db.getOrNull("welcome_message", "select=message&id=eq.1");
        if (rows == null)
        {
            return;
        }
        welcomeLoaded = true;
        // Remote text printed into the chatbox: strip anything that could
        // read as chat markup, collapse whitespace, cap the length.
        String raw = rows.size() == 0 ? "" : Supabase.str(rows.get(0).getAsJsonObject(), "message");
        String clean = raw.replaceAll("<[^>]*>", "").replace("<", "").replace(">", "")
            .replaceAll("\\s+", " ").trim();
        welcome = cap(clean, MAX_WELCOME);
    }

    // ------------------------------------------------------------ welcome

    // Called after the startup fetch and after verification; whichever
    // lands last prints the line. Synchronized: both callers are executor
    // threads.
    public synchronized void maybeShowWelcome()
    {
        Session session = clan.snapshot();
        String message = welcome;
        if (!clan.isVerified() || welcomeShown || message.isEmpty())
        {
            return;
        }
        welcomeShown = true;
        clientThread.invokeLater(() -> {
            if (!clan.current(session))
            {
                welcomeShown = false; // logged out first; the next login prints it
                return true;
            }
            GameState gs = client.getGameState();
            if (gs == GameState.LOADING || gs == GameState.HOPPING || gs == GameState.CONNECTION_LOST)
            {
                return false; // transient — try again next tick
            }
            if (!clan.isVerified() || gs != GameState.LOGGED_IN)
            {
                welcomeShown = false; // true logout — re-attempt next login
                return true;
            }
            // postEvent=false keeps our own line out of the chat-event
            // pipeline (the pet matcher would otherwise see it).
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "<col=" + WELCOME_COLOR + ">[Final Boss] " + message + "</col>", null, false);
            return true;
        });
    }

    private static String cap(String s, int max)
    {
        return s.length() > max ? s.substring(0, max) : s;
    }
}

package com.github.orgonag.fbclan.core;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.Value;
import lombok.AllArgsConstructor;

/** Separates HTTP delivery from the server's domain outcome. */
@Value
@AllArgsConstructor
public class ApiResult
{
    int httpStatus;
    JsonElement body;
    String error;
    String contentRange;
    public ApiResult(int status, JsonElement body, String error) { this(status, body, error, null); }
    public long totalRows()
    {
        try { return contentRange == null ? -1 : Long.parseLong(contentRange.substring(contentRange.lastIndexOf('/') + 1)); }
        catch (RuntimeException e) { return -1; }
    }

    public boolean successful()
    {
        if (httpStatus < 200 || httpStatus >= 300 || error != null) return false;
        return body == null || !body.isJsonObject() || !body.getAsJsonObject().has("status")
            || "ok".equals(Supabase.str(body.getAsJsonObject(), "status"));
    }
    public boolean retryable() { return httpStatus == 0 || httpStatus == 429 || httpStatus >= 500; }
    // The server read the request and said no (bad input, or a non-ok
    // status); anything else may work later.
    public boolean refused() { return httpStatus == 400 || (httpStatus >= 200 && httpStatus < 300 && error == null && !successful()); }
    public String message()
    {
        if (error != null) return error;
        if (body != null && body.isJsonObject()) {
            JsonObject o = body.getAsJsonObject();
            String text = Supabase.str(o, "message");
            if (!text.isEmpty()) return text;
        }
        return "Request failed (HTTP " + httpStatus + ")";
    }
}

package com.github.orgonag.fbclan.core;

import com.google.gson.*;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.EnumSet;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import okhttp3.*;

/** Session generations prevent old asynchronous verification from authorizing a new login. */
@Slf4j
@Singleton
public class Clan
{
    public static final int WOM_GROUP_ID = 1055;
    public enum Status { VERIFYING, MEMBER, NOT_MEMBER, ERROR }
    public interface Listener { void onStatus(Status status); }
    private final Client client;
    private final ClientThread clientThread;
    private final ScheduledExecutorService executor;
    private final OkHttpClient http;
    private final ConfigManager configManager;
    private final AtomicLong generations = new AtomicLong();
    private volatile Session session = new Session(0, null, null, false);
    private volatile boolean enabled;
    private volatile Listener listener = s -> {};
    private volatile Future<?> delayed;
    private volatile Call verificationCall;
    private volatile boolean verifying;
    // This login already has a yes or no; only the panel's Retry asks
    // again. (An error is left open, so the next area load tries once more.)
    private volatile boolean resolved;

    @Inject
    public Clan(Client client, ClientThread clientThread, ScheduledExecutorService executor,
                OkHttpClient http, ConfigManager configManager)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.executor = executor;
        this.http = http.newBuilder().callTimeout(20, TimeUnit.SECONDS).build();
        this.configManager = configManager;
    }
    public void setListener(Listener listener) { this.listener = listener; }
    public Session snapshot() { return session; }
    public boolean current(Session captured) {
        return enabled && captured != null && captured.canUpload()
            && captured.getGeneration() == session.getGeneration() && session.canUpload();
    }
    public String rsn() { return session.getRsn(); }
    public boolean isVerified() { return session.isVerified(); }
    public boolean canUpload() { return enabled && session.canUpload(); }
    public synchronized void activate() { enabled = true; reset(); }
    public synchronized void deactivate() { enabled = false; reset(); listener = s -> {}; }
    public synchronized void reset()
    {
        session = new Session(generations.incrementAndGet(), null, null, false);
        verifying = false;
        resolved = false;
        Future<?> task = delayed;
        if (task != null) task.cancel(false);
        Call call = verificationCall;
        if (call != null) call.cancel();
    }
    public void verifyAfter(long delaySeconds)
    {
        long generation = session.getGeneration();
        Future<?> old = delayed;
        if (old != null) old.cancel(false);
        delayed = executor.schedule(() -> clientThread.invokeLater(() -> {
            if (!enabled || generation != session.getGeneration() || client.getGameState() == GameState.LOGIN_SCREEN) return;
            if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null
                || client.getLocalPlayer().getName() == null || configManager.getRSProfileKey() == null)
            {
                verifyAfter(1);
                return;
            }
            synchronized (this)
            {
                if (!enabled || generation != session.getGeneration()) return;
                String name = client.getLocalPlayer().getName();
                String profile = configManager.getRSProfileKey();
                if (session.getRsn() != null && (!Names.same(session.getRsn(), name) || !profile.equals(session.getProfile()))) reset();
                if (session.isVerified() || resolved) return;
                session = new Session(session.getGeneration(), name, profile, false);
                verify();
            }
        }), delaySeconds, TimeUnit.SECONDS);
    }
    public void verify()
    {
        clientThread.invokeLater(() -> {
            Session captured = session;
            if (!enabled || captured.getRsn() == null || verifying) return;
            verifying = true;
            listener.onStatus(Status.VERIFYING);
            executor.submit(() -> {
                Status answer;
                try { answer = inGroup(captured.getRsn()) ? Status.MEMBER : Status.NOT_MEMBER; }
                catch (Exception e) { log.debug("Membership verification unavailable", e); answer = Status.ERROR; }
                Status result = answer;
                clientThread.invokeLater(() -> {
                    synchronized (this)
                    {
                        if (!enabled || captured.getGeneration() != session.getGeneration()) return;
                        verifying = false;
                        resolved = result != Status.ERROR;
                        session = new Session(captured.getGeneration(), captured.getRsn(), captured.getProfile(), result == Status.MEMBER);
                        listener.onStatus(result);
                    }
                });
            });
        });
    }
    public boolean onStandardWorld()
    {
        EnumSet<WorldType> types = client.getWorldType();
        return !types.contains(WorldType.SEASONAL)
            && !types.contains(WorldType.DEADMAN)
            && !types.contains(WorldType.TOURNAMENT_WORLD)
            && !types.contains(WorldType.BETA_WORLD)
            && !types.contains(WorldType.QUEST_SPEEDRUNNING)
            && !types.contains(WorldType.NOSAVE_MODE)
            && !types.contains(WorldType.FRESH_START_WORLD)
            && !types.contains(WorldType.PVP_ARENA);
    }

    private boolean inGroup(String name) throws IOException
    {
        String url = "https://api.wiseoldman.net/v2/players/"
            + URLEncoder.encode(name, StandardCharsets.UTF_8).replace("+", "%20") + "/groups?limit=50";
        Request request = new Request.Builder().url(url).header("User-Agent", "FinalBoss-RuneLite-Plugin").build();
        Call call = http.newCall(request);
        verificationCall = call;
        try (Response response = call.execute())
        {
            // Wise Old Man has never seen this name: not in any group.
            if (response.code() == 404) return false;
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("WOM API returned " + response.code());
            }
            JsonArray groups = new JsonParser().parse(response.body().string()).getAsJsonArray();
            for (JsonElement el : groups)
            {
                JsonObject group = el.getAsJsonObject().getAsJsonObject("group");
                if (group != null && group.get("id").getAsInt() == WOM_GROUP_ID)
                {
                    return true;
                }
            }
            return false;
        }
    }
}

package com.github.orgonag.fbclan.core;

import java.util.Locale;

/**
 * Text helpers shared by every feature: RSN comparison (in-game names
 * arrive with non-breaking spaces and mixed case) and a sanitizer for
 * user-typed text headed to the database.
 */
public final class Names
{
    private Names()
    {
    }

    public static String normalize(String name)
    {
        return name == null ? "" : name.replace('\u00A0', ' ').trim().toLowerCase(Locale.ROOT);
    }

    public static boolean same(String a, String b)
    {
        return normalize(a).equals(normalize(b));
    }

    // Strips control characters, trims, caps; null for blank input.
    public static String sanitize(String text, int maxLength)
    {
        if (text == null)
        {
            return null;
        }
        String cleaned = text.replaceAll("\\p{Cntrl}", " ").trim();
        if (cleaned.isEmpty())
        {
            return null;
        }
        return cleaned.length() > maxLength ? cleaned.substring(0, maxLength).trim() : cleaned;
    }

    // Case/whitespace-insensitive item-name key (notable list matching).
    public static String itemKey(String itemName)
    {
        return itemName == null ? "" : itemName.trim().toLowerCase(Locale.ROOT);
    }
}

