/**
 * The drop pipeline. An item is logged when it is <b>valuable</b> (GE
 * value at or above the threshold), <b>rare</b> (1 in X or rarer from
 * this source AND worth the rare minimum), on the clan's <b>notable</b>
 * list, or a <b>pet</b>. It then optionally grabs an annotated
 * screenshot and fans out to the clan drop log and the user's Discord
 * webhook. Also serves the drop-log tab's recent rows.
 */
@Slf4j
@Singleton
public class DropLogger
{
    private static final String BUCKET = "drop-screenshots";
    private static final String COLUMNS = "rsn,npc_name,item_name,item_id,ge_value,quantity,created_at,occurred_at,screenshot_url,rarity";
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final Pattern SCREENSHOT_FILE = Pattern.compile("(?:[A-Za-z0-9_-]{1,12}/)?[A-Za-z0-9_-]{1,64}\\.png");

    private final DropOutbox outbox = new DropOutbox(RuneLite.RUNELITE_DIR.toPath().resolve("finalboss-outbox"));
    private final AtomicBoolean flushing = new AtomicBoolean();
    private final AtomicBoolean framePending = new AtomicBoolean();
    private final LootDeduplicator deduplicator = new LootDeduplicator();
    private final Client client;
    private final FinalBossConfig config;
    private final Clan clan;
    private final ClanContent content;
    private final DropRates rates;
    private final Supabase db;
    private final ItemManager itemManager;
    private final DrawManager drawManager;
    private final PartyService partyService;
    private final ScheduledExecutorService executor;
    private final okhttp3.OkHttpClient http;
    // Pet attribution state; client thread only.
    private String lastSource;
    private int lastSourceTick = Integer.MIN_VALUE / 2;
    private String petMessage;
    private int petTick = -1;
    private long petLogin;
    private String petSource;
    private int petItem;
    private int newItemId;
    private int newItemTick = -1;
    private Map<Integer, Integer> inventoryCounts = Collections.emptyMap();

    @Inject
    public DropLogger(Client client, FinalBossConfig config, Clan clan, ClanContent content, DropRates rates,
                      Supabase db, ItemManager itemManager, DrawManager drawManager, PartyService partyService,
                      ScheduledExecutorService executor, okhttp3.OkHttpClient http)
    {
        this.client = client;
        this.config = config;
        this.clan = clan;
        this.content = content;
        this.rates = rates;
        this.db = db;
        this.itemManager = itemManager;
        this.drawManager = drawManager;
        this.partyService = partyService;
        this.executor = executor;
        this.http = http.newBuilder().callTimeout(20, TimeUnit.SECONDS).build();
    }

    // A file in the plugin's own screenshot bucket: "<uuid>.png", or the
    // older "<player>/<time>_<item>.png". The drop viewer opens nothing else.
    public static boolean isScreenshot(String url)
    {
        String prefix = Supabase.publicUrl(BUCKET, "");
        return url != null && url.startsWith(prefix) && SCREENSHOT_FILE.matcher(url.substring(prefix.length())).matches();
    }

    // ------------------------------------------------------------ inputs

    // `source` is what the Loot Tracker reported (NPC, raid, chest); it
    // doubles as the key into the rate table. Client thread.
    // `tracker`: reported by the Loot Tracker rather than an NPC kill.
    public void onLoot(String source, Collection<ItemStack> items, boolean tracker)
    {
        String rsn = clan.rsn();
        if (!clan.canUpload() || !config.enableDropLogging())
        {
            return;
        }
        long threshold = DropRules.threshold(config.dropThresholdGp());
        int rareDenominator = config.rareDropThreshold();
        long rareMin = Math.max(0, config.rareDropMinValueGp());
        Set<String> notable = content.notableItems();
        String display = DropRules.displaySource(source);
        lastSource = display;
        lastSourceTick = client.getTickCount();
        if (petTick >= 0 && petSource == null && lastSourceTick - petTick <= 1) petSource = display;

        List<Drop> drops = new ArrayList<>();
        for (ItemStack stack : items)
        {
            int id = stack.getId();
            int qty = stack.getQuantity();
            if (qty <= 0) continue;
            long value = (long) itemManager.getItemPrice(id) * qty;
            String name = itemManager.getItemComposition(id).getName();
            OptionalDouble rarity = rates.rarity(source, id, qty);
            if (!rarity.isPresent() && !display.equals(source))
            {
                rarity = rates.rarity(display, id, qty);
            }
            boolean blocked = DropRules.neverLogged(name);
            boolean valuable = !blocked && DropRules.valuable(value, threshold);
            boolean rare = !blocked && DropRules.rare(rarity, rareDenominator) && value >= rareMin;
            boolean isNotable = notable.contains(Names.itemKey(name));
            if (valuable || rare || isNotable)
            {
                drops.add(new Drop(name, id, value, qty, rarity.isPresent() ? rarity.getAsDouble() : null));
            }
        }
        if (!drops.isEmpty())
        {
            // Suppress duplicate delivery of the same loot collection within one game tick.
            int tick = client.getTickCount();
            String key = clan.snapshot().getGeneration() + ":" + display + ":" + drops.toString();
            if (deduplicator.accept(tick, key, tracker)) dispatch(rsn, display, drops);
        }
    }

    // Pets only announce themselves in chat. Untradeable, so they bypass
    // the value rules. The message, the loot, the follower and a backpack
    // item can arrive in any order, so a pet is settled two ticks after
    // its message (onTick). Its source is the loot within a tick of the
    // message, its item the one untradeable that appeared within a tick
    // of it: whichever came first, taken when it arrives. Client thread.
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE || !DropRules.isPetMessage(event.getMessage())) return;
        petMessage = event.getMessage();
        petTick = client.getTickCount();
        petLogin = clan.snapshot().getGeneration();
        petSource = petTick - lastSourceTick <= 1 ? lastSource : null;
        petItem = petTick - newItemTick <= 1 ? newItemId : 0;
    }

    // Notes an untradeable item that just appeared: a backpack pet. Client thread.
    public void onInventoryChanged(ItemContainer inventory)
    {
        Map<Integer, Integer> now = new HashMap<>();
        for (Item item : inventory.getItems())
        {
            if (item.getId() > 0) now.merge(item.getId(), item.getQuantity(), Integer::sum);
        }
        int added = 0;
        for (Map.Entry<Integer, Integer> e : now.entrySet())
        {
            if (e.getValue() > inventoryCounts.getOrDefault(e.getKey(), 0)
                && !itemManager.getItemComposition(e.getKey()).isTradeable())
            {
                // Two at once: no telling which is the pet.
                added = added == 0 ? e.getKey() : -1;
            }
        }
        inventoryCounts = now;
        if (added == 0) return;
        newItemId = added;
        newItemTick = client.getTickCount();
        if (petTick >= 0 && petItem == 0 && newItemTick - petTick <= 1) petItem = added;
    }

    // Settles a waiting pet. The name comes from the new follower, or for
    // a backpack pet from its item (else it is logged unnamed). Client thread.
    public void onTick()
    {
        if (petTick < 0 || client.getTickCount() - petTick < 2) return;
        String message = petMessage;
        petTick = -1;
        // Still the login that got the message.
        if (!clan.canUpload() || !config.enableDropLogging() || clan.snapshot().getGeneration() != petLogin) return;
        String source = petSource != null ? petSource : "Pet drop";
        String name = "Pet";
        int itemId = 0;
        if (DropRules.isDuplicatePet(message))
        {
            name = "Pet (duplicate)";
        }
        else if (DropRules.isFollowerPet(message))
        {
            NPC follower = client.getFollower();
            if (follower != null && follower.getName() != null) name = "Pet (" + follower.getName() + ")";
        }
        else if (petItem > 0)
        {
            itemId = petItem;
            name = "Pet (" + itemManager.getItemComposition(itemId).getName() + ")";
        }
        dispatch(clan.rsn(), source, Collections.singletonList(new Drop(name, itemId, 0, 1, null)));
    }

    // ------------------------------------------------------------ reads

    // Explicit column list so a future column can't silently ship to
    // every viewer. Executor.
    public JsonArray recent(int limit)
    {
        JsonArray rows = db.getOrNull("drops", "select=" + COLUMNS + "&order=created_at.desc,id.desc&limit=" + Math.max(1, Math.min(200, limit)));
        if (rows == null) throw new IllegalStateException("Could not refresh drops. Showing the last loaded list.");
        for (JsonElement el : rows)
        {
            JsonObject row = el.getAsJsonObject();
            String path = Supabase.str(row, "screenshot_url");
            if (path.matches("[0-9a-f-]{36}\\.png")) row.addProperty("screenshot_url", Supabase.publicUrl(BUCKET, path));
        }
        return rows;
    }

    // ------------------------------------------------------------ pipeline

    private void dispatch(String rsn, String source, List<Drop> drops)
    {
        Session session = clan.snapshot();
        String worldType = clan.onStandardWorld() ? "standard" : "special";
        String occurred = Instant.now().toString();
        List<JsonObject> rows = new ArrayList<>();
        for (Drop d : drops)
        {
            JsonObject row = new JsonObject();
            row.addProperty("event_id", UUID.randomUUID().toString());
            row.addProperty("rsn", rsn); row.addProperty("npc_name", source);
            row.addProperty("item_name", d.name); row.addProperty("item_id", d.itemId);
            row.addProperty("ge_value", d.value); row.addProperty("quantity", d.quantity);
            row.addProperty("world_type", worldType); row.addProperty("occurred_at", occurred);
            if (d.rarity != null && d.rarity > 0 && d.rarity <= 1) row.addProperty("rarity", d.rarity);
            rows.add(row);
        }
        executor.submit(() -> {
            // Saved even if the player has since logged out; flush sends it at their next login.
            for (JsonObject row : rows)
            {
                try { outbox.add(session, row); }
                catch (IOException e) { log.warn("Could not persist a drop for retry", e); }
            }
            flush();
        });
        // Screenshots are optional enrichment; no rendered frame is needed to save a drop.
        if (!config.enableDropScreenshots() || !framePending.compareAndSet(false, true)) return;
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        List<String> party = partyNames();
        drawManager.requestNextFrameListener(frame -> {
            framePending.set(false);
            if (System.nanoTime() > deadline || !clan.current(session) || !config.enableDropLogging() || !config.enableDropScreenshots()) return;
            BufferedImage copy = new BufferedImage(frame.getWidth(null), frame.getHeight(null), BufferedImage.TYPE_INT_RGB);
            Graphics2D graphics = copy.createGraphics();
            try { graphics.drawImage(frame, 0, 0, null); } finally { graphics.dispose(); }
            executor.submit(() -> {
                if (!clan.current(session) || !config.enableDropLogging() || !config.enableDropScreenshots()) return;
                String path = uploadScreenshot(copy, party);
                if (path == null) return;
                for (JsonObject row : rows)
                {
                    if (!clan.current(session) || !config.enableDropLogging() || !config.enableDropScreenshots()) return;
                    JsonObject payload = new JsonObject(); payload.add("p_row", row);
                    if (!db.rpc("fb_submit_drop", payload)) continue;
                    JsonObject attachment = new JsonObject();
                    attachment.addProperty("p_event", Supabase.str(row, "event_id"));
                    attachment.addProperty("p_path", path);
                    db.rpc("fb_attach_screenshot", attachment);
                }
            });
        });
    }

    /** Worker only; retry all pending drops for this verified profile. */
    public void flush()
    {
        Session session = clan.snapshot();
        if (!clan.current(session) || !config.enableDropLogging() || !flushing.compareAndSet(false, true)) return;
        try
        {
            int unexplained = 0;
            for (JsonObject row : outbox.pending(session))
            {
                if (!clan.current(session) || !config.enableDropLogging()) break;
                JsonObject payload = new JsonObject(); payload.add("p_row", row);
                ApiResult result = db.rpcResult("fb_submit_drop", payload);
                if (!result.successful())
                {
                    // Only a refusal sets a drop aside. Offline or a server fault: everything waits.
                    // Anything else stays queued, and a few of those in a row end this attempt.
                    if (result.retryable() || (!result.refused() && ++unexplained >= 3)) break;
                    if (!result.refused()) continue;
                    outbox.reject(Supabase.str(row, "event_id"));
                    log.warn("Drop rejected by database; saved locally for inspection: {}", result.message());
                    continue;
                }
                outbox.remove(Supabase.str(row, "event_id"));
                // Webhooks are deliberately best effort, independent of the durable clan record.
                if (clan.current(session) && config.enableDropLogging()) discord(Supabase.str(row, "rsn"), Supabase.str(row, "npc_name"),
                    new Drop(Supabase.str(row, "item_name"), row.get("item_id").getAsInt(), row.get("ge_value").getAsLong(), row.get("quantity").getAsInt(),
                        Supabase.has(row, "rarity") ? row.get("rarity").getAsDouble() : null));
            }
        }
        catch (IOException | RuntimeException e) { log.warn("Drop retry failed", e); }
        finally { flushing.set(false); }
    }

    private void discord(String rsn, String source, Drop d)
    {
        String url = config.discordWebhookUrl();
        if (url == null || url.isEmpty())
        {
            return;
        }
        if (!url.startsWith("https://discord.com/api/webhooks/") && !url.startsWith("https://discordapp.com/api/webhooks/"))
        {
            log.warn("Discord webhook URL is not a Discord webhook, skipping");
            return;
        }
        String value = d.value > 0 ? " (" + DropRules.formatGp(d.value) + " GP)" : "";
        String rate = d.rarity != null && d.rarity > 0 ? " [" + DropRules.formatRarity(d.rarity) + "]" : "";
        JsonObject embed = new JsonObject();
        embed.addProperty("title", rsn + " received a drop!");
        embed.addProperty("description", d.name + value + rate + " from " + source);
        embed.addProperty("color", 0xFFD700);
        JsonArray embeds = new JsonArray();
        embeds.add(embed);
        JsonObject payload = new JsonObject();
        payload.add("embeds", embeds);
        Request request = new Request.Builder().url(url).post(RequestBody.create(JSON, payload.toString())).build();
        try (Response response = http.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                log.warn("Discord webhook failed: {}", response.code());
            }
        }
        catch (IOException e)
        {
            log.warn("Discord webhook error", e);
        }
    }

    // ------------------------------------------------------------ screenshots

    // `image` is this drop's own copy of the frame; the party line is drawn onto it.
    private String uploadScreenshot(BufferedImage image, List<String> party)
    {
        try
        {
            Graphics2D g = image.createGraphics();
            if (!party.isEmpty())
            {
                String line = "Party members: " + String.join(", ", party);
                g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
                FontMetrics fm = g.getFontMetrics();
                g.setColor(new Color(0, 0, 0, 160));
                g.fillRect(6, 8, fm.stringWidth(line) + 8, fm.getHeight() + 4);
                g.setColor(Color.WHITE);
                g.drawString(line, 10, 10 + fm.getAscent());
            }
            g.dispose();
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            ImageIO.write(image, "png", out);
            String path = UUID.randomUUID() + ".png";
            return db.upload(BUCKET, path, out.toByteArray(), "image/png") == null ? null : path;
        }
        catch (IOException | RuntimeException e)
        {
            log.warn("Failed to upload drop screenshot", e);
            return null;
        }
    }

    // Names of the local RuneLite party, already visible to everyone in
    // it; no party identifiers leave the client.
    private List<String> partyNames()
    {
        List<String> names = new ArrayList<>();
        if (partyService.isInParty())
        {
            for (PartyMember m : partyService.getMembers())
            {
                if (m.getDisplayName() != null && !m.getDisplayName().isEmpty())
                {
                    names.add(m.getDisplayName());
                }
            }
        }
        return names;
    }

    @Value
    private static class Drop
    {
        String name;
        int itemId;
        long value;
        int quantity;
        Double rarity;
    }
}

package com.github.orgonag.fbclan.drops;

import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.stream.Stream;

/** Disk I/O only on workers. One atomic file per event; no credentials stored. */
public final class DropOutbox
{
    private final Path directory;
    public DropOutbox(Path directory) { this.directory = directory; }
    public synchronized void add(Session session, JsonObject row) throws IOException
    {
        Files.createDirectories(directory);
        try (Stream<Path> files = Files.list(directory))
        {
            if (files.filter(p -> p.toString().endsWith(".json")).count() >= 1000)
                throw new IOException("Drop outbox is full (1000 events)");
        }
        JsonObject record = new JsonObject();
        record.addProperty("profile", session.getProfile());
        record.addProperty("endpoint", Supabase.projectUrl());
        record.add("row", row);
        Path target = directory.resolve(Supabase.str(row, "event_id") + ".json");
        Path temporary = Files.createTempFile(directory, "event-", ".tmp");
        try
        {
            Files.write(temporary, record.toString().getBytes(StandardCharsets.UTF_8));
            try { Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException e) { Files.move(temporary, target); }
        }
        finally { Files.deleteIfExists(temporary); }
    }
    public synchronized List<JsonObject> pending(Session session) throws IOException
    {
        List<JsonObject> out = new ArrayList<>();
        if (!Files.isDirectory(directory)) return out;
        try (DirectoryStream<Path> files = Files.newDirectoryStream(directory, "*.json"))
        {
            for (Path file : files)
            {
                try
                {
                    JsonObject record = new JsonParser().parse(Files.readString(file)).getAsJsonObject();
                    JsonObject row = record.getAsJsonObject("row");
                    // Matched on the RuneLite profile (the account), not the name: a
                    // drop saved before a rename still sends, under the name it was earned on.
                    if (session.getProfile().equals(Supabase.str(record, "profile"))
                        && Supabase.projectUrl().equals(Supabase.str(record, "endpoint")) && row.has("event_id")) out.add(row);
                }
                catch (CharacterCodingException | RuntimeException e)
                {
                    // Not a drop record: set it aside so it can't block the rest.
                    try { Files.move(file, file.resolveSibling(file.getFileName() + ".invalid"), StandardCopyOption.REPLACE_EXISTING); }
                    catch (IOException ignored) { }
                }
                catch (IOException e)
                {
                    // Couldn't read it this time (locked?): leave it for the next retry.
                }
            }
        }
        return out;
    }
    public synchronized void reject(String id) throws IOException
    {
        Path file = directory.resolve(UUID.fromString(id) + ".json");
        Files.move(file, file.resolveSibling(file.getFileName() + ".rejected"), StandardCopyOption.REPLACE_EXISTING);
    }
    public synchronized void remove(String id) throws IOException
    {
        Files.deleteIfExists(directory.resolve(UUID.fromString(id) + ".json"));
    }
}

package com.github.orgonag.fbclan.drops;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * "How rare is item X from source Y?" Backed by the bundled npc_drops.json:
 * the OSRS Wiki's monster drop tables (CC BY-NC-SA 3.0), parsed by
 * Flipping Utilities' parsed-osrs and compacted by the Dink plugin
 * (BSD-2-Clause, (c) Jake Barter). Lookup logic mirrors Dink's. A small
 * in-code supplement covers reward chests the wiki table lacks.
 *
 * Loaded once on the executor (~700 KB); lookups before that report
 * "unknown" rather than blocking.
 */
@Slf4j
@Singleton
public class DropRates
{
    private static final String RESOURCE = "/com/github/orgonag/fbclan/npc_drops.json";

    private final ItemManager itemManager;
    private final Gson gson;
    private volatile Map<String, Collection<Drop>> bySource = Collections.emptyMap();

    @Inject
    public DropRates(ItemManager itemManager, Gson gson)
    {
        this.itemManager = itemManager;
        this.gson = gson; // Plugin Hub forbids fresh Gson instances; use the client's
    }

    public void load()
    {
        if (!bySource.isEmpty())
        {
            return; // already parsed this client session
        }
        Map<String, List<RawDrop>> raw;
        try (InputStream is = DropRates.class.getResourceAsStream(RESOURCE);
             Reader reader = new BufferedReader(new InputStreamReader(
                 Objects.requireNonNull(is, "missing " + RESOURCE), StandardCharsets.UTF_8)))
        {
            raw = gson.fromJson(reader, new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        }
        catch (Exception e)
        {
            log.error("Failed to read drop rate table", e);
            return;
        }
        Map<String, Collection<Drop>> table = new HashMap<>(raw.size() * 2);
        raw.forEach((source, drops) -> {
            List<Drop> out = new ArrayList<>();
            for (RawDrop r : drops)
            {
                out.addAll(r.expand());
            }
            table.put(source, out);
        });
        // Reward chests: rates from the OSRS Wiki's Gauntlet reward pages.
        // Item ids: enhanced crystal weapon seed, crystal armour seed,
        // crystal weapon seed.
        table.put(DropRules.GAUNTLET, Arrays.asList(
            new Drop(25859, 1, 1, 1.0 / 2000), new Drop(23956, 1, 1, 1.0 / 120), new Drop(4207, 1, 1, 1.0 / 120)));
        table.put(DropRules.CORRUPTED_GAUNTLET, Arrays.asList(
            new Drop(25859, 1, 1, 1.0 / 400), new Drop(23956, 1, 1, 1.0 / 50), new Drop(4207, 1, 1, 1.0 / 50)));
        bySource = table;
        log.info("Loaded drop rates for {} sources", table.size());
    }

    // Probability (0..1) that one kill/completion of `source` yields this
    // item stack, or empty when unknown. Noted items resolve to the
    // unnoted id; charged/ornamented variants match by shared name.
    public OptionalDouble rarity(String source, int itemId, int quantity)
    {
        Collection<Drop> drops = bySource.get(source);
        if (drops == null || drops.isEmpty())
        {
            return OptionalDouble.empty();
        }
        ItemComposition comp = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = comp != null && comp.getNote() != -1 ? comp.getLinkedNoteId() : itemId;
        String itemName = comp != null ? comp.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
            ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)));

        double total = 0;
        boolean any = false;
        for (Drop d : drops)
        {
            if (quantity < d.minQuantity || quantity > d.maxQuantity)
            {
                continue;
            }
            boolean match = d.itemId == itemId
                || (variants.contains(d.itemId)
                    && itemName.equals(itemManager.getItemComposition(d.itemId).getMembersName()));
            if (match)
            {
                total += d.probability;
                any = true;
            }
        }
        return any ? OptionalDouble.of(total) : OptionalDouble.empty();
    }

    @Value
    private static class Drop
    {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    // One line of npc_drops.json: item id, denominator (1/d per roll),
    // optional roll count, and a fixed quantity or a min..max range.
    private static class RawDrop
    {
        @SerializedName("i") int itemId;
        @SerializedName("r") Integer rolls;
        @SerializedName("d") double denominator;
        @SerializedName("q") Integer quantity;
        @SerializedName("m") Integer quantMin;
        @SerializedName("n") Integer quantMax;

        // Multi-roll tables become one entry per possible success count,
        // each with the binomial probability of exactly that many hits.
        Collection<Drop> expand()
        {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : (quantity != null ? quantity : 1);
            int max = quantMax != null ? quantMax : (quantity != null ? quantity : 1);
            double p = denominator > 0 ? 1 / denominator : 0;
            if (rounds <= 1)
            {
                return Collections.singletonList(new Drop(itemId, min, max, p));
            }
            List<Drop> out = new ArrayList<>(rounds);
            for (int k = 1; k <= rounds; k++)
            {
                out.add(new Drop(itemId, min * k, max * k, binomial(p, rounds, k)));
            }
            return out;
        }

        private static double binomial(double p, int n, int k)
        {
            double coeff = 1;
            for (int i = 1; i <= k; i++)
            {
                coeff = coeff * (n - k + i) / i;
            }
            return coeff * Math.pow(p, k) * Math.pow(1 - p, n - k);
        }
    }
}

package com.github.orgonag.fbclan.drops;

import java.text.NumberFormat;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.OptionalDouble;
import java.util.Set;

/** What counts as a loggable drop. Pure rules; no I/O. */
public final class DropRules
{
    // Floors so nobody floods the shared log: GP value, and the rarity
    // rule never reaches commoner than 1 in 250.
    public static final int MIN_THRESHOLD_GP = 1_000_000;
    public static final int MIN_RARE_DENOMINATOR = 250;

    // Chat lines the game prints for a pet (pets never appear in loot
    // events); the same set the core Screenshot plugin matches.
    private static final String PET_FOLLOWER = "You have a funny feeling like you're being followed";
    private static final String PET_BACKPACK = "You feel something weird sneaking into your backpack";
    private static final String PET_DUPLICATE = "You have a funny feeling like you would have been followed";

    // Loot the core Loot Tracker reports as an NPC record with no NPC-kill
    // event (it comes from a reward chest): picked up from the tracker's
    // own event instead. Same list Dink keeps.
    public static final String GAUNTLET_BOSS = "Crystalline Hunllef";
    public static final String CORRUPTED_GAUNTLET_BOSS = "Corrupted Hunllef";
    public static final String GAUNTLET = "The Gauntlet";
    public static final String CORRUPTED_GAUNTLET = "The Corrupted Gauntlet";
    public static final Set<String> CHEST_LOOT_NPCS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        GAUNTLET_BOSS, CORRUPTED_GAUNTLET_BOSS, "The Whisperer", "Araxxor",
        "Branda the Fire Queen", "Eldric the Ice King")));

    private DropRules()
    {
    }

    public static long threshold(long configuredGp)
    {
        return Math.max(configuredGp, MIN_THRESHOLD_GP);
    }

    public static boolean valuable(long totalValue, long thresholdGp)
    {
        return totalValue >= thresholdGp;
    }

    // 1 in `denominator` or rarer (never below the 1/250 floor, even for
    // settings saved before it existed); unknown never qualifies.
    public static boolean rare(OptionalDouble rarity, int denominator)
    {
        return rarity.isPresent() && rarity.getAsDouble() <= 1.0 / Math.max(MIN_RARE_DENOMINATOR, denominator);
    }

    // Never logged by the automatic rules regardless of value or rate:
    // clue scrolls, long/curved bones, champion scrolls, and keys. The
    // clan's notable list is an explicit choice and bypasses this.
    public static boolean neverLogged(String itemName)
    {
        if (itemName == null)
        {
            return false;
        }
        String n = itemName.toLowerCase(Locale.ROOT).trim();
        return n.startsWith("clue scroll")
            || n.equals("long bone")
            || n.equals("curved bone")
            || n.endsWith("champion scroll")
            || n.endsWith(" key")
            || n.endsWith(" half of key")
            || n.contains(" key (");
    }

    // The Gauntlet's loot is logged under the activity, not the boss.
    public static String displaySource(String lootSource)
    {
        if (GAUNTLET_BOSS.equals(lootSource))
        {
            return GAUNTLET;
        }
        if (CORRUPTED_GAUNTLET_BOSS.equals(lootSource))
        {
            return CORRUPTED_GAUNTLET;
        }
        return lootSource;
    }

    public static boolean isPetMessage(String message)
    {
        return message != null
            && (message.contains(PET_FOLLOWER) || message.contains(PET_BACKPACK) || message.contains(PET_DUPLICATE));
    }

    // The only variant where the new pet is readable off getFollower().
    public static boolean isFollowerPet(String message)
    {
        return message != null && message.contains(PET_FOLLOWER);
    }

    public static boolean isDuplicatePet(String message)
    {
        return message != null && message.contains(PET_DUPLICATE);
    }

    public static String formatGp(long value)
    {
        return NumberFormat.getIntegerInstance(Locale.US).format(value);
    }

    // "1/512", rounded to the nearest whole denominator.
    public static String formatRarity(double probability)
    {
        return probability <= 0 ? "" : "1/" + Math.round(1 / probability);
    }
}

package com.github.orgonag.fbclan.drops;
import java.util.HashMap;
import java.util.Map;

/** Match overlapping event channels without collapsing two identical NPC kills. Client thread only. */
public final class LootDeduplicator
{
    private int tick = -1;
    private final Map<String,int[]> counts = new HashMap<>();
    public boolean accept(int currentTick, String fingerprint, boolean tracker)
    {
        if (tick != currentTick) { counts.clear(); tick = currentTick; }
        int[] seen = counts.computeIfAbsent(fingerprint, key -> new int[2]);
        int own = tracker ? 1 : 0;
        return ++seen[own] > seen[1-own];
    }
}

