    // Minigames
    BA("Barbarian Assault", Category.MINIGAMES, 5, 5, null, 10551),
    ZALCANO("Zalcano", Category.MINIGAMES, 1, 30, null, 23953),
    VOLCANIC_MINE("Volcanic Mine", Category.MINIGAMES, 1, 30, null, 21622),
    CASTLE_WARS("Castle Wars", Category.MINIGAMES, 1, 50, null, 4067),
    GOTR("Guardians of the Rift", Category.MINIGAMES, 1, 30, null, 26822),
    WINTERTODT("Wintertodt", Category.MINIGAMES, 1, 30, null, 20708),

    // Catch-alls for anything without a dedicated entry
    GROUP_BOSS("Group Boss", Category.GENERAL, 1, 100, null, 13576),
    MINIGAME("Minigame", Category.GENERAL, 1, 100, null, 3853),
    PVP("PvP", Category.GENERAL, 1, 100, null, 964),
    SKILLING("Skilling", Category.GENERAL, 1, 100, null, 11850),
    CHILLING("Chilling", Category.GENERAL, 1, 100, null, 1978);

    @Getter
    public enum Category
    {
        RAIDS("Raids"), GOD_WARS("God Wars"), BOSSES("Bosses"), MINIGAMES("Minigames"), GENERAL("General");

        private final String displayName;

        Category(String displayName)
        {
            this.displayName = displayName;
        }
    }

    private final String displayName;
    private final Category category;
    private final int minPartySize;
    private final int maxPartySize;
    // "CM" / "HM" / "Expert", or null when there's no harder variant.
    private final String hardModeLabel;
    // A representative item sprite from RuneLite's item cache.
    private final int iconItemId;

    Activity(String displayName, Category category, int minPartySize, int maxPartySize, String hardModeLabel, int iconItemId)
    {
        this.displayName = displayName;
        this.category = category;
        this.minPartySize = minPartySize;
        this.maxPartySize = maxPartySize;
        this.hardModeLabel = hardModeLabel;
        this.iconItemId = iconItemId;
    }

    public String key()
    {
        return name();
    }

    public boolean isRaid()
    {
        return category == Category.RAIDS;
    }

    // ToA's difficulty is an invocation level rather than a toggle.
    public boolean usesInvocation()
    {
        return this == TOA;
    }

    public boolean hasHardMode()
    {
        return hardModeLabel != null && !usesInvocation();
    }

    public boolean hasRoles()
    {
        return this == TOB || this == COX || this == BA;
    }

    // Starting party size for quick posts and the host window.
    public int defaultPartySize()
    {
        int preferred;
        switch (this)
        {
            case TOB: preferred = 4; break;
            case COX: case TOA: preferred = 3; break;
            case BA: preferred = 5; break;
            case YAMA: case ROYAL_TITANS: preferred = 2; break;
            default: preferred = 4; break;
        }
        int min = Math.max(Party.MIN_CAPACITY, minPartySize);
        return Math.max(min, Math.min(Math.max(min, maxPartySize), preferred));
    }

    // True when a kill count exists a host can set a minimum for.
    public boolean hasKillcount()
    {
        return !hiscoreSkills().isEmpty();
    }

    // Community abbreviation for card titles and chat lines.
    public String shortName()
    {
        switch (this)
        {
            case COX: case TOB: case TOA: case NEX: case DKS: case BA: case GOTR:
                return name();
            case KREEARRA: return "Arma";
            case GRAARDOR: return "Bandos";
            case KRIL: return "Zammy";
            case ZILYANA: return "Sara";
            case NIGHTMARE: return "Nightmare";
            case ROYAL_TITANS: return "Titans";
            case HUEYCOATL: return "Huey";
            case VOLCANIC_MINE: return "VM";
            case CASTLE_WARS: return "CW";
            case WINTERTODT: return "WT";
            default: return displayName;
        }
    }

    // "CM", "HMT", "ToA (300)", else the short name.
    public String partyTitle(boolean hardMode, int invocation)
    {
        if (usesInvocation())
        {
            return invocation > 0 ? "ToA (" + invocation + ")" : "ToA";
        }
        if (hardMode && hasHardMode())
        {
            return this == TOB ? "HMT" : this == COX ? "CoX CM" : shortName() + " " + hardModeLabel;
        }
        return shortName();
    }

    // Hiscore entries the activity's kill count spans (three for DKs).
    public List<HiscoreSkill> hiscoreSkills()
    {
        switch (this)
        {
            case COX: return Collections.singletonList(HiscoreSkill.CHAMBERS_OF_XERIC);
            case TOB: return Collections.singletonList(HiscoreSkill.THEATRE_OF_BLOOD);
            case TOA: return Collections.singletonList(HiscoreSkill.TOMBS_OF_AMASCUT);
            case KREEARRA: return Collections.singletonList(HiscoreSkill.KREEARRA);
            case GRAARDOR: return Collections.singletonList(HiscoreSkill.GENERAL_GRAARDOR);
            case KRIL: return Collections.singletonList(HiscoreSkill.KRIL_TSUTSAROTH);
            case ZILYANA: return Collections.singletonList(HiscoreSkill.COMMANDER_ZILYANA);
            case NEX: return Collections.singletonList(HiscoreSkill.NEX);
            case NIGHTMARE: return Collections.singletonList(HiscoreSkill.NIGHTMARE);
            case CORP: return Collections.singletonList(HiscoreSkill.CORPOREAL_BEAST);
            case DKS: return Arrays.asList(HiscoreSkill.DAGANNOTH_PRIME, HiscoreSkill.DAGANNOTH_REX, HiscoreSkill.DAGANNOTH_SUPREME);
            case HUEYCOATL: return Collections.singletonList(HiscoreSkill.THE_HUEYCOATL);
            case YAMA: return Collections.singletonList(HiscoreSkill.YAMA);
            case ROYAL_TITANS: return Collections.singletonList(HiscoreSkill.THE_ROYAL_TITANS);
            case ZALCANO: return Collections.singletonList(HiscoreSkill.ZALCANO);
            case GOTR: return Collections.singletonList(HiscoreSkill.RIFTS_CLOSED);
            case WINTERTODT: return Collections.singletonList(HiscoreSkill.WINTERTODT);
            default: return Collections.emptyList();
        }
    }

    public HiscoreSkill hardModeHiscoreSkill()
    {
        switch (this)
        {
            case COX: return HiscoreSkill.CHAMBERS_OF_XERIC_CHALLENGE_MODE;
            case TOB: return HiscoreSkill.THEATRE_OF_BLOOD_HARD_MODE;
            case TOA: return HiscoreSkill.TOMBS_OF_AMASCUT_EXPERT;
            default: return null;
        }
    }

    // Boss names as the core Chat Commands plugin stores kill counts
    // (lower-cased on read). Alternatives where the wording is uncertain.
    public List<String> localKillcountKeys(boolean hardMode)
    {
        switch (this)
        {
            case COX: return Collections.singletonList(hardMode ? "Chambers of Xeric Challenge Mode" : "Chambers of Xeric");
            case TOB: return Collections.singletonList(hardMode ? "Theatre of Blood Hard Mode" : "Theatre of Blood");
            case TOA: return Collections.singletonList(hardMode ? "Tombs of Amascut Expert Mode" : "Tombs of Amascut");
            case KREEARRA: return Collections.singletonList("Kree'arra");
            case GRAARDOR: return Collections.singletonList("General Graardor");
            case KRIL: return Collections.singletonList("K'ril Tsutsaroth");
            case ZILYANA: return Collections.singletonList("Commander Zilyana");
            case NEX: return Collections.singletonList("Nex");
            case NIGHTMARE: return Arrays.asList("Nightmare", "The Nightmare");
            case CORP: return Collections.singletonList("Corporeal Beast");
            case DKS: return Arrays.asList("Dagannoth Prime", "Dagannoth Rex", "Dagannoth Supreme");
            case HUEYCOATL: return Arrays.asList("The Hueycoatl", "Hueycoatl");
            case YAMA: return Collections.singletonList("Yama");
            case ROYAL_TITANS: return Arrays.asList("The Royal Titans", "Royal Titans");
            case ZALCANO: return Collections.singletonList("Zalcano");
            case GOTR: return Collections.singletonList("Guardians of the Rift");
            case WINTERTODT: return Collections.singletonList("Wintertodt");
            default: return Collections.emptyList();
        }
    }

    public static Activity fromKey(String key)
    {
        try
        {
            return key == null ? null : valueOf(key);
        }
        catch (IllegalArgumentException e)
        {
            return null;
        }
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * A party that filled up: a self-contained snapshot (one
 * lfg_formed_parties row) with no links to the live tables, which are
 * deleted when it's written. Kept server-side for 7 days as history.
 */
@Value
public class FormedParty
{
    @Value
    public static class Member
    {
        String rsn;
        Role role;
        boolean addedByHost;
    }

    String id;
    String partyId;   // the live party it came from
    String hostRsn;
    Activity activity;
    boolean hardMode;
    int invocation;
    int capacity;
    Integer world;
    List<Member> members;  // host first
    Instant formedAt;
    Instant scheduledFor;  // null = was an ASAP party

    public String title()
    {
        return activity.partyTitle(hardMode, invocation);
    }

    public boolean isHostedBy(String rsn)
    {
        return rsn != null && Names.same(hostRsn, rsn);
    }

    public boolean includes(String rsn)
    {
        return rsn != null && members.stream().anyMatch(m -> Names.same(m.getRsn(), rsn));
    }

    // "Shok (Melee), Bud (Ranged), Pal"
    public String roster()
    {
        StringBuilder sb = new StringBuilder();
        for (Member m : members)
        {
            sb.append(sb.length() > 0 ? ", " : "").append(m.getRsn());
            if (m.getRole() != null)
            {
                sb.append(" (").append(m.getRole().getDisplayName()).append(')');
            }
        }
        return sb.toString();
    }

    public static FormedParty fromRow(JsonObject row)
    {
        Activity activity = Activity.fromKey(Supabase.str(row, "activity"));
        if (activity == null || Supabase.str(row, "id").isEmpty() || Supabase.str(row, "host_rsn").isEmpty())
        {
            return null;
        }
        List<Member> members = new ArrayList<>();
        if (Supabase.has(row, "members") && row.get("members").isJsonArray())
        {
            for (JsonElement el : row.getAsJsonArray("members"))
            {
                if (!el.isJsonObject())
                {
                    continue;
                }
                JsonObject o = el.getAsJsonObject();
                String rsn = Supabase.str(o, "rsn");
                if (!rsn.isEmpty())
                {
                    members.add(new Member(rsn, Role.fromKey(Supabase.str(o, "role")), Supabase.bool(o, "added_by_host")));
                }
            }
        }
        return new FormedParty(Supabase.str(row, "id"),
            Supabase.has(row, "party_id") ? Supabase.str(row, "party_id") : null,
            Supabase.str(row, "host_rsn"), activity, Supabase.bool(row, "hard_mode"),
            Supabase.intOr(row, "invocation", 0), Supabase.intOr(row, "capacity", Math.max(1, members.size())),
            Supabase.intOrNull(row, "world"), members, Supabase.instant(row, "formed_at", Instant.now()),
            Supabase.instant(row, "scheduled_for", null));
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.Names;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.hiscore.HiscoreClient;
import net.runelite.client.hiscore.HiscoreEndpoint;
import net.runelite.client.hiscore.HiscoreResult;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.Skill;

/**
 * Kill counts for parties. Two sources: the local player's own counts
 * as recorded by the core Chat Commands plugin (instant, only for this
 * account), and the public OSRS hiscores via RuneLite's hiscore client
 * (any player, cached 30 min, failures retried after a minute).
 */
@Singleton
public class Killcounts
{
    private static final long OK_TTL_MS = 30 * 60_000L;
    private static final long FAIL_TTL_MS = 60_000L;
    private static final long TIMEOUT_MS = 15_000L;

    /** A hiscore answer; -1 = unranked/unknown. */
    @Value
    public static class Hiscore
    {
        int kc;
        int hardKc;
        boolean unavailable;
        long fetchedAt;

        public boolean known(boolean hard)
        {
            return !unavailable && (hard ? hardKc : kc) >= 0;
        }

        public int kc(boolean hard)
        {
            return hard ? hardKc : kc;
        }

        boolean stale()
        {
            return System.currentTimeMillis() - fetchedAt > (unavailable ? FAIL_TTL_MS : OK_TTL_MS);
        }
    }

    private static final int MAX_ENTRIES = 250;

    private final ConfigManager configManager;
    private final HiscoreClient hiscores;
    // One entry per (player, activity) a host has browsed; bounded LRU.
    private final Map<String, CompletableFuture<Hiscore>> cache = new LinkedHashMap<String, CompletableFuture<Hiscore>>(32, 0.75f, true)
    {
        @Override
        protected boolean removeEldestEntry(Map.Entry<String, CompletableFuture<Hiscore>> eldest)
        {
            return size() > MAX_ENTRIES;
        }
    };

    @Inject
    public Killcounts(ConfigManager configManager, HiscoreClient hiscores)
    {
        this.configManager = configManager;
        this.hiscores = hiscores;
    }

    // The local account's count from RuneLite config, or null. DKs sum
    // the three kings.
    public Integer local(Activity activity, boolean hard)
    {
        if (configManager.getRSProfileKey() == null)
        {
            return null;
        }
        Integer total = null;
        for (String key : activity.localKillcountKeys(hard))
        {
            Integer kc;
            try
            {
                kc = configManager.getRSProfileConfiguration("killcount", key.toLowerCase(Locale.ROOT), int.class);
            }
            catch (RuntimeException e)
            {
                kc = null;
            }
            if (kc == null)
            {
                continue;
            }
            if (activity != Activity.DKS)
            {
                return kc;
            }
            total = (total == null ? 0 : total) + kc;
        }
        return total;
    }

    // Logout: nothing browsed is relevant to the next session.
    public synchronized void clear()
    {
        cache.clear();
    }

    // Cached hiscore answer, or null when none is known yet.
    public synchronized Hiscore cached(String rsn, Activity activity)
    {
        if (rsn == null || activity == null)
        {
            return null;
        }
        CompletableFuture<Hiscore> f = cache.get(key(rsn, activity));
        Hiscore h = f == null ? null : f.getNow(null);
        return h == null || h.stale() ? null : h;
    }

    // Starts a lookup unless one is fresh or in flight; `onDone` always
    // runs once an answer exists — on the hiscore client's thread, so
    // callers hop to the EDT themselves.
    public synchronized void lookup(String rsn, Activity activity, Runnable onDone)
    {
        if (rsn == null || activity == null)
        {
            return;
        }
        String key = key(rsn, activity);
        CompletableFuture<Hiscore> f = cache.get(key);
        if (f != null && (!f.isDone() || !f.getNow(null).stale()))
        {
            // The existing lookup already has a completion callback. Repeated renders must not register hundreds more.
            if (f.isDone()) onDone.run();
            return;
        }
        List<HiscoreSkill> skills = activity.hiscoreSkills();
        if (skills.isEmpty())
        {
            // No hiscore entry for this activity: a known "unranked".
            cache.put(key, CompletableFuture.completedFuture(new Hiscore(-1, -1, false, System.currentTimeMillis())));
            onDone.run();
            return;
        }
        CompletableFuture<Hiscore> next;
        try
        {
            next = hiscores.lookupAsync(rsn, HiscoreEndpoint.NORMAL)
                .orTimeout(TIMEOUT_MS, TimeUnit.MILLISECONDS)
                .handle((result, ex) -> {
                    if (ex != null)
                    {
                        return new Hiscore(-1, -1, true, System.currentTimeMillis());
                    }
                    if (result == null)
                    {
                        // Not on the hiscores: a real answer, not worth asking again every minute.
                        return new Hiscore(-1, -1, false, System.currentTimeMillis());
                    }
                    try
                    {
                        HiscoreSkill hard = activity.hardModeHiscoreSkill();
                        return new Hiscore(sum(result, skills), hard == null ? -1 : level(result, hard), false,
                            System.currentTimeMillis());
                    }
                    catch (RuntimeException e)
                    {
                        return new Hiscore(-1, -1, true, System.currentTimeMillis());
                    }
                });
        }
        catch (RuntimeException e)
        {
            next = CompletableFuture.completedFuture(new Hiscore(-1, -1, true, System.currentTimeMillis()));
        }
        cache.put(key, next);
        next.thenRun(onDone);
    }

    private static int sum(HiscoreResult result, List<HiscoreSkill> skills)
    {
        int total = -1;
        for (HiscoreSkill s : skills)
        {
            int kc = level(result, s);
            if (kc >= 0)
            {
                total = Math.max(total, 0) + kc;
            }
        }
        return total;
    }

    private static int level(HiscoreResult result, HiscoreSkill skill)
    {
        Skill s = result.getSkill(skill);
        return s == null ? -1 : s.getLevel();
    }

    private static String key(String rsn, Activity activity)
    {
        return Names.normalize(rsn) + "|" + activity.key();
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Session;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

/**
 * The "!lfg" chat command, for the local player's own messages only
 * (other players' commands are ignored; the typed message still posts
 * normally). "!lfg" or "!lfg parties" prints the open parties;
 * "!lfg tob 4" posts an ASAP party with default details, the same as the
 * panel's Post now. Applying and managing stay in the panel.
 */
@Singleton
public class LfgCommand
{
    private static final String USAGE = "!lfg lists parties · !lfg <activity> [size] posts an ASAP party, e.g. !lfg tob 4";
    private static final Pattern TIME = Pattern.compile("\\d{1,2}:\\d{2}|\\d{1,2}(am|pm)|am|pm|tomorrow|today|tonight");

    /** What an alias posts: the activity, hard mode, and ToA invocation. */
    private static final class Alias
    {
        final Activity activity;
        final boolean hard;
        final int invocation;

        Alias(Activity activity, boolean hard, int invocation)
        {
            this.activity = activity;
            this.hard = hard;
            this.invocation = invocation;
        }
    }

    private static final Map<String, Alias> ALIASES = new HashMap<>();

    static
    {
        alias(Activity.TOB, false, 0, "tob", "theatre", "theatreofblood");
        alias(Activity.TOB, true, 0, "hmt", "hmtob", "tobhm", "hardmodetob");
        alias(Activity.COX, false, 0, "cox", "raids", "chambers", "xeric", "chambersofxeric");
        alias(Activity.COX, true, 0, "cm", "coxcm", "cmcox", "challengemode");
        alias(Activity.TOA, false, 150, "toa", "tombs", "tombsofamascut");
        alias(Activity.TOA, false, 300, "expert", "etoa", "experttoa", "toaexpert");
        alias(Activity.NEX, false, 0, "nex");
        alias(Activity.KREEARRA, false, 0, "arma", "kree", "armadyl", "kreearra");
        alias(Activity.GRAARDOR, false, 0, "bandos", "graardor");
        alias(Activity.KRIL, false, 0, "zammy", "kril", "zamorak");
        alias(Activity.ZILYANA, false, 0, "sara", "zily", "saradomin", "zilyana");
        alias(Activity.NIGHTMARE, false, 0, "nm", "nightmare");
        alias(Activity.CORP, false, 0, "corp", "corporealbeast");
        alias(Activity.DKS, false, 0, "dks", "dagannothkings");
        alias(Activity.HUEYCOATL, false, 0, "huey", "hueycoatl");
        alias(Activity.YAMA, false, 0, "yama");
        alias(Activity.ROYAL_TITANS, false, 0, "titans", "rt", "royaltitans");
        alias(Activity.BA, false, 0, "ba", "barbarianassault");
        alias(Activity.ZALCANO, false, 0, "zalc", "zalcano");
        alias(Activity.VOLCANIC_MINE, false, 0, "vm", "volc", "volcanicmine");
        alias(Activity.CASTLE_WARS, false, 0, "cw", "castlewars");
        alias(Activity.GOTR, false, 0, "gotr", "rift", "guardiansoftherift");
        alias(Activity.WINTERTODT, false, 0, "wt", "todt", "wintertodt");
        alias(Activity.GROUP_BOSS, false, 0, "boss", "groupboss");
        alias(Activity.MINIGAME, false, 0, "mg", "minigame");
        alias(Activity.PVP, false, 0, "pvp", "pk");
        alias(Activity.SKILLING, false, 0, "skill", "skilling");
        alias(Activity.CHILLING, false, 0, "chill", "chilling");
    }

    private static void alias(Activity activity, boolean hard, int invocation, String... names)
    {
        for (String n : names)
        {
            ALIASES.put(n, new Alias(activity, hard, invocation));
        }
    }
    private static final Set<ChatMessageType> LOCAL_AUTHOR = EnumSet.of(
        ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.PRIVATECHATOUT);

    private final Client client;
    private final ClientThread clientThread;
    private final FinalBossConfig config;
    private final Clan clan;
    private final PartyApi api;
    private final PartyBoard board;
    private final ScheduledExecutorService executor;

    @Inject
    public LfgCommand(Client client, ClientThread clientThread, FinalBossConfig config, Clan clan, PartyApi api,
                      PartyBoard board, ScheduledExecutorService executor)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.clan = clan;
        this.api = api;
        this.board = board;
        this.executor = executor;
    }

    // Client thread.
    public void onChatMessage(ChatMessage event)
    {
        if (!config.enableLfg() || !clan.canUpload() || !LOCAL_AUTHOR.contains(event.getType()))
        {
            return;
        }
        // PRIVATECHATOUT's name is the recipient; the author is us by definition.
        if (event.getType() != ChatMessageType.PRIVATECHATOUT
            && (event.getName() == null || !Names.same(Text.removeTags(event.getName()), clan.rsn())))
        {
            return;
        }
        String text = Text.removeTags(event.getMessage()).trim();
        if (!text.toLowerCase(Locale.ROOT).startsWith("!lfg"))
        {
            return;
        }
        String rest = text.substring(4);
        if (!rest.isEmpty() && !Character.isWhitespace(rest.charAt(0)))
        {
            return; // "!lfgsomething" is a different command
        }
        String keyword = rest.trim().split("\\s+", 2)[0].toLowerCase(Locale.ROOT);
        if (keyword.isEmpty() || keyword.equals("parties") || keyword.equals("party"))
        {
            Session session = clan.snapshot();
            executor.submit(() -> {
                if (!clan.current(session) || !config.enableLfg()) return;
                PartyApi.Snapshot snapshot = api.fetch();
                List<Party> parties = snapshot == null ? null : snapshot.getParties();
                String reply = parties == null ? "Couldn't reach the party board — try again." : summarize(parties);
                clientThread.invokeLater(() -> {
                    if (clan.current(session) && config.enableLfg() && client.getGameState() == GameState.LOGGED_IN)
                    {
                        print(reply);
                    }
                });
            });
        }
        else if (keyword.equals("help") || keyword.equals("?"))
        {
            print(USAGE);
        }
        else
        {
            post(rest.trim().toLowerCase(Locale.ROOT));
        }
    }

    // "!lfg tob 4": activity words, then an optional size as the last word. Client thread.
    private void post(String args)
    {
        List<String> words = new ArrayList<>(Arrays.asList(args.split("\\s+")));
        for (String w : words)
        {
            if (TIME.matcher(w).matches())
            {
                print("[LFG] Start times are set in the Final Boss panel; chat posts are ASAP.");
                return;
            }
        }
        Integer size = null;
        if (words.size() > 1 && words.get(words.size() - 1).matches("\\d{1,3}"))
        {
            size = Integer.parseInt(words.remove(words.size() - 1));
        }
        String key = String.join("", words).replaceAll("[^a-z0-9]", "");
        Alias alias = ALIASES.get(key);
        if (alias == null)
        {
            for (Activity a : Activity.values())
            {
                if (a.name().toLowerCase(Locale.ROOT).replace("_", "").equals(key)
                    || a.getDisplayName().toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "").equals(key))
                {
                    alias = new Alias(a, false, a.usesInvocation() ? 150 : 0);
                }
            }
        }
        if (alias == null)
        {
            String typed = Text.removeTags(args);
            print("[LFG] Unknown activity \"" + (typed.length() > 20 ? typed.substring(0, 20) : typed)
                + "\". Try tob, hmt, cox, cm, toa, nex, bandos... (!lfg help)");
            return;
        }
        Activity activity = alias.activity;
        int min = Math.max(Party.MIN_CAPACITY, activity.getMinPartySize());
        int max = Math.max(min, activity.getMaxPartySize());
        int capacity = size == null ? activity.defaultPartySize() : size;
        if (capacity < min || capacity > max)
        {
            print("[LFG] " + activity.shortName() + (min == max ? " needs exactly " + min : " party size must be " + min + "-" + max) + ".");
            return;
        }
        if (!board.running())
        {
            print("[LFG] The party board isn't ready yet. Try again in a moment.");
            return;
        }
        Party asap = board.mineAsap();
        if (asap != null)
        {
            print("[LFG] You already have an ASAP party (" + asap.title() + " " + asap.memberCount() + "/" + asap.getCapacity()
                + "). Cancel it in the panel first.");
            return;
        }
        String rsn = clan.rsn();
        int world = client.getWorld();
        Party party = Party.quick(rsn, activity, alias.hard, alias.invocation, capacity, world > 0 ? world : null);
        Session session = clan.snapshot();
        // run() does the network write on the executor and reports back here.
        board.run(() -> api.save(party), "Couldn't reach the party board — try again.", failure -> clientThread.invokeLater(() -> {
            if (!clan.current(session) || client.getGameState() != GameState.LOGGED_IN) return;
            print(failure == null
                ? "[LFG] Posted " + party.title() + " 1/" + capacity + " (ASAP" + (world > 0 ? ", W" + world : "") + "). Manage it in the Final Boss panel."
                : "[LFG] " + failure);
        }));
    }

    // "Parties: HMT - Host 3/5 W420 - needs Melee, North freeze | ..."
    static String summarize(List<Party> parties)
    {
        if (parties.isEmpty())
        {
            return "No parties are being hosted right now.";
        }
        StringBuilder sb = new StringBuilder("Parties: ");
        boolean first = true;
        for (Party p : parties)
        {
            if (sb.length() > 600) { sb.append(" | More in the panel."); break; }
            sb.append(first ? "" : " | ").append(p.title())
                .append(p.isScheduled() ? " @ " + PartyBoard.when(p.getScheduledFor()) : "").append(" - ").append(p.getHostRsn())
                .append(' ').append(p.memberCount()).append('/').append(p.getCapacity());
            first = false;
            if (p.getWorld() != null)
            {
                sb.append(" W").append(p.getWorld());
            }
            if (p.isFull())
            {
                sb.append(" (full)");
            }
            else
            {
                String needs = p.needs();
                if (!needs.isEmpty())
                {
                    sb.append(" - needs ").append(needs);
                }
            }
        }
        return sb.toString();
    }

    private void print(String message)
    {
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }
}

package com.github.orgonag.fbclan.lfg;

import lombok.Getter;

/** How a party splits drops. Stored by enum name; unknown reads as UNSPECIFIED. */
@Getter
public enum LootRule
{
    UNSPECIFIED("Loot: any"), FFA("FFA"), SPLIT("Split");

    private final String displayName;

    LootRule(String displayName)
    {
        this.displayName = displayName;
    }

    public static LootRule fromKey(String key)
    {
        for (LootRule rule : values())
        {
            if (key != null && rule.name().equalsIgnoreCase(key.trim()))
            {
                return rule;
            }
        }
        return UNSPECIFIED;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Value;

/**
 * A hosted party (one lfg_parties row) with its embedded applicants.
 * Immutable: the board rebuilds from each fetch. Membership is the host
 * plus accepted applicants.
 */
@Value
@Builder(toBuilder = true)
public class Party
{
    public static final int MAX_DESCRIPTION = 120;
    public static final int MIN_CAPACITY = 2;
    public static final int MAX_CAPACITY = 100;
    public static final int MAX_INVOCATION = 600;
    // A post lives 7 days from creation; a full scheduled post forms GRACE after its start.
    public static final Duration LIFETIME = Duration.ofHours(168);
    public static final Duration GRACE = Duration.ofHours(2);

    public enum Status
    {
        PENDING, ACCEPTED, DECLINED;

        static Status fromKey(String key)
        {
            try
            {
                return key == null ? PENDING : valueOf(key.trim().toUpperCase());
            }
            catch (IllegalArgumentException e)
            {
                return PENDING;
            }
        }
    }

    // Where an applicant's kill count came from: their own client's
    // record, a hiscore lookup, or typed by hand.
    public enum KcSource
    {
        LOCAL, HISCORES, MANUAL;

        static KcSource fromKey(String key)
        {
            try
            {
                return key == null ? null : valueOf(key.trim().toUpperCase());
            }
            catch (IllegalArgumentException e)
            {
                return null;
            }
        }
    }

    /** One lfg_applicants row. */
    @Value
    public static class Applicant
    {
        String rsn;
        Role role;      // null for role-less activities
        boolean learner;
        Status status;
        Instant createdAt;
        Integer kc;     // null = unknown
        KcSource kcSource;
        boolean addedByHost;

        public boolean isAccepted()
        {
            return status == Status.ACCEPTED;
        }

        public boolean isPending()
        {
            return status == Status.PENDING;
        }

        static Applicant fromRow(JsonObject row)
        {
            String rsn = Supabase.str(row, "rsn");
            return rsn.isEmpty() ? null : new Applicant(rsn, Role.fromKey(Supabase.str(row, "role")),
                Supabase.bool(row, "learner"), Status.fromKey(Supabase.str(row, "status")),
                Supabase.instant(row, "created_at", Instant.EPOCH), Supabase.intOrNull(row, "kc"),
                KcSource.fromKey(Supabase.str(row, "kc_source")), Supabase.bool(row, "added_by_host"));
        }
    }

    String id;          // null until created server-side
    long version;
    String hostRsn;
    Activity activity;
    boolean hardMode;
    int invocation;     // ToA only; 0 otherwise
    int capacity;
    String description;
    Integer world;
    int minKc;          // 0 = none
    LootRule lootRule;
    List<Role> requiredRoles;
    Role hostRole;
    boolean learner;
    boolean teacher;
    Instant createdAt;
    Instant scheduledFor;   // null = ASAP
    List<Applicant> applicants;

    // The template behind `!lfg tob 4`: every optional detail left at its
    // default, the host on "any role".
    public static Party quick(String hostRsn, Activity activity, boolean hard, int invocation, int capacity, Integer world)
    {
        boolean h = hard && activity.hasHardMode();
        return Party.builder()
            .hostRsn(hostRsn)
            .activity(activity)
            .hardMode(h)
            .invocation(activity.usesInvocation() ? invocation : 0)
            .capacity(capacity)
            .world(world)
            .lootRule(LootRule.UNSPECIFIED)
            .requiredRoles(Role.required(activity, h, capacity, Collections.emptyMap()))
            .hostRole(Role.any(activity, h))
            .createdAt(Instant.now())
            .applicants(Collections.emptyList())
            .build();
    }

    public String title()
    {
        return activity.partyTitle(hardMode, invocation);
    }

    public boolean isScheduled()
    {
        return scheduledFor != null;
    }

    // When the server drops an unfilled post.
    public Instant expiresAt()
    {
        return createdAt.plus(LIFETIME);
    }

    // CM / HMT, or a ToA at expert-level invocation.
    public boolean isHard()
    {
        return hardMode || (activity.usesInvocation() && invocation >= 300);
    }

    public List<Applicant> accepted()
    {
        List<Applicant> out = new ArrayList<>();
        for (Applicant a : applicants)
        {
            if (a.isAccepted())
            {
                out.add(a);
            }
        }
        return out;
    }

    public List<Applicant> pending()
    {
        List<Applicant> out = new ArrayList<>();
        for (Applicant a : applicants)
        {
            if (a.isPending())
            {
                out.add(a);
            }
        }
        return out;
    }

    public int memberCount()
    {
        return 1 + accepted().size();
    }

    public boolean isFull()
    {
        return memberCount() >= capacity;
    }

    public boolean isHostedBy(String rsn)
    {
        return rsn != null && Names.same(hostRsn, rsn);
    }

    public Applicant applicantFor(String rsn)
    {
        for (Applicant a : applicants)
        {
            if (rsn != null && Names.same(a.getRsn(), rsn))
            {
                return a;
            }
        }
        return null;
    }

    public List<Role> openRoles()
    {
        if (!activity.hasRoles())
        {
            return Collections.emptyList();
        }
        List<Role> taken = new ArrayList<>();
        taken.add(hostRole);
        for (Applicant a : accepted())
        {
            taken.add(a.getRole());
        }
        return Role.open(activity, requiredRoles, taken);
    }

    // What the party still needs: "Ranged, South freeze", or "3 of Melee,
    // Ranged, ..." while an "any role" member hasn't settled on a seat.
    public String needs()
    {
        List<Role> open = openRoles();
        int free = capacity - memberCount();
        return (free > 0 && open.size() > free ? free + " of " : "") + Role.summarize(open);
    }

    // The create/edit payload. The server owns id, host and timestamps.
    public JsonObject toJson()
    {
        JsonObject d = new JsonObject();
        d.addProperty("activity", activity.key());
        d.addProperty("hard_mode", hardMode);
        d.addProperty("invocation", invocation);
        d.addProperty("capacity", capacity);
        Supabase.put(d, "description", Names.sanitize(description, MAX_DESCRIPTION));
        Supabase.put(d, "world", world);
        d.addProperty("min_kc", Math.max(0, minKc));
        d.addProperty("loot_rule", (lootRule == null ? LootRule.UNSPECIFIED : lootRule).name());
        Supabase.put(d, "required_roles", Role.encode(requiredRoles));
        Supabase.put(d, "host_role", hostRole == null ? null : hostRole.key());
        d.addProperty("learner", learner);
        d.addProperty("teacher", teacher);
        // Always sent (JSON null = ASAP) so an edit can switch back.
        Supabase.put(d, "scheduled_for", scheduledFor == null ? null : scheduledFor.toString());
        return d;
    }

    // Tolerates missing optional columns; null when unusable.
    public static Party fromRow(JsonObject row)
    {
        Activity activity = Activity.fromKey(Supabase.str(row, "activity"));
        if (activity == null || Supabase.str(row, "id").isEmpty() || Supabase.str(row, "host_rsn").isEmpty())
        {
            return null;
        }
        List<Applicant> applicants = new ArrayList<>();
        if (Supabase.has(row, "lfg_applicants") && row.get("lfg_applicants").isJsonArray())
        {
            for (JsonElement el : row.getAsJsonArray("lfg_applicants"))
            {
                Applicant a = el.isJsonObject() ? Applicant.fromRow(el.getAsJsonObject()) : null;
                if (a != null)
                {
                    applicants.add(a);
                }
            }
            applicants.sort((a, b) -> a.getCreatedAt().compareTo(b.getCreatedAt()));
        }
        return Party.builder()
            .id(Supabase.str(row, "id"))
            .version(Supabase.longOr(row, "version", 1))
            .hostRsn(Supabase.str(row, "host_rsn"))
            .activity(activity)
            .hardMode(Supabase.bool(row, "hard_mode"))
            .invocation(Supabase.intOr(row, "invocation", 0))
            .capacity(Math.max(1, Supabase.intOr(row, "capacity", activity.getMaxPartySize())))
            // Scheduling servers tag `description` with the start time for old
            // clients and send the real text as `note`.
            .description(row.has("note") ? (Supabase.has(row, "note") ? Supabase.str(row, "note") : null)
                : Supabase.has(row, "description") ? Supabase.str(row, "description") : null)
            .scheduledFor(Supabase.instant(row, "scheduled_for", null))
            .world(Supabase.intOrNull(row, "world"))
            .minKc(Supabase.intOr(row, "min_kc", 0))
            .lootRule(LootRule.fromKey(Supabase.str(row, "loot_rule")))
            .requiredRoles(Role.decode(Supabase.str(row, "required_roles")))
            .hostRole(Role.fromKey(Supabase.str(row, "host_role")))
            .learner(Supabase.bool(row, "learner"))
            .teacher(Supabase.bool(row, "teacher"))
            .createdAt(Supabase.instant(row, "created_at", Instant.now()))
            .applicants(Collections.unmodifiableList(applicants))
            .build();
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.ApiResult;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.function.BooleanSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/** The fb_board / fb_lfg API (protocol 3, schema 5). Each logical write has one retry identity. */
@Singleton
public class PartyApi
{
    @Value public static class Snapshot { List<Party> parties; List<FormedParty> formed; }
    public static final Snapshot EMPTY = new Snapshot(Collections.emptyList(), Collections.emptyList());
    private final Supabase db;
    private final Clan clan;
    private final ThreadLocal<Session> actor = new ThreadLocal<>();
    // The server's reason for the last refused command on this thread, else null.
    private final ThreadLocal<String> refusal = new ThreadLocal<>();
    private volatile Snapshot snapshot = EMPTY;

    @Inject
    public PartyApi(Supabase db, Clan clan)
    {
        this.db = db;
        this.clan = clan;
    }

    public boolean inSession(Session session, BooleanSupplier action)
    {
        actor.set(session);
        refusal.remove();
        try { return clan.current(session) && action.getAsBoolean(); }
        finally { actor.remove(); }
    }

    // Executor. Null when the board can't be read or parsed.
    public Snapshot fetch()
    {
        ApiResult response = db.rpcResult("fb_board", new JsonObject());
        if (!response.successful() || response.getBody() == null || !response.getBody().isJsonObject()) return null;
        JsonObject body = response.getBody().getAsJsonObject();
        if (Supabase.intOr(body, "protocol", 0) != 3) return null;
        List<Party> parties = new ArrayList<>();
        List<FormedParty> formed = new ArrayList<>();
        try
        {
            for (JsonElement el : body.getAsJsonArray("parties"))
            {
                // A row this version can't read (a newer activity) is skipped, not fatal.
                Party p = Party.fromRow(el.getAsJsonObject());
                if (p != null) parties.add(p);
            }
            for (JsonElement el : body.getAsJsonArray("formed"))
            {
                FormedParty f = FormedParty.fromRow(el.getAsJsonObject());
                if (f != null) formed.add(f);
            }
        }
        catch (RuntimeException e) { return null; }
        return new Snapshot(Collections.unmodifiableList(parties), Collections.unmodifiableList(formed));
    }

    // Executor: why the server refused the last command run on this thread
    // ("You already have an ASAP party"), or null when it never answered.
    public String refusal()
    {
        return refusal.get();
    }

    public void publish(Snapshot value)
    {
        snapshot = value;
    }

    public boolean save(Party party)
    {
        JsonObject d = party.toJson();
        if (party.getId() != null) d.addProperty("id", party.getId());
        return command(party.getId() == null ? "create" : "edit", d, party.getId() == null ? null : party.getVersion());
    }

    public boolean disband(String id)
    {
        return command("disband", data(id));
    }

    public boolean apply(String id, Role role, boolean learner, Integer kc, Party.KcSource source)
    {
        JsonObject d = data(id);
        Supabase.put(d, "role", role == null ? null : role.key());
        d.addProperty("learner", learner);
        Supabase.put(d, "kc", kc);
        Supabase.put(d, "kc_source", source == null ? null : source.name());
        return command("apply", d);
    }

    // The host removing someone is a kick; anyone else is leaving.
    public boolean withdraw(String id, String rsn)
    {
        Party p = find(id);
        Session s = actor.get() == null ? clan.snapshot() : actor.get();
        JsonObject d = data(id);
        d.addProperty("rsn", rsn);
        return command(p != null && p.isHostedBy(s.getRsn()) ? "kick" : "leave", d);
    }

    public boolean setStatus(String id, String rsn, Party.Status status)
    {
        JsonObject d = data(id);
        d.addProperty("rsn", rsn);
        return command(status == Party.Status.ACCEPTED ? "accept" : "decline", d);
    }

    public boolean addMember(String id, String rsn, Role role)
    {
        // Someone who already applied is accepted instead (the server would
        // refuse a second row for them with a database error).
        Party p = find(id);
        Party.Applicant existing = p == null ? null : p.applicantFor(rsn);
        if (existing != null && existing.isPending()) return setStatus(id, rsn, Party.Status.ACCEPTED);
        if (existing != null)
        {
            refusal.set(existing.isAccepted() ? "They're already in this party." : "You declined them earlier. Ask them to apply again.");
            return false;
        }
        JsonObject d = data(id);
        d.addProperty("rsn", rsn);
        Supabase.put(d, "role", role == null ? null : role.key());
        boolean added = command("add", d);
        // They applied (or were declined) since the last refresh.
        if (!added && refusal.get() != null && refusal.get().startsWith("duplicate key"))
        {
            refusal.set("They have just applied. Accept them from the list above.");
        }
        return added;
    }

    public boolean deleteFormed(String id)
    {
        return command("remove_formed", data(id));
    }

    // ------------------------------------------------------------ plumbing

    private Party find(String id)
    {
        for (Party p : snapshot.parties) if (p.getId().equals(id)) return p;
        return null;
    }

    private static JsonObject data(String id)
    {
        JsonObject d = new JsonObject();
        d.addProperty("id", id);
        return d;
    }

    // Only an edit carries the party's version (so it can't overwrite a
    // newer one). Everything else is re-checked by the server under its
    // lock; a version there would refuse the action whenever anyone else
    // touched the party since the last poll.
    private boolean command(String action, JsonObject d)
    {
        return command(action, d, null);
    }

    private boolean command(String action, JsonObject data, Long expected)
    {
        Session session = actor.get() == null ? clan.snapshot() : actor.get();
        if (!clan.current(session)) return false;
        JsonObject args = new JsonObject();
        args.addProperty("p_action", action);
        args.addProperty("p_actor", session.getRsn());
        args.add("p_data", data);
        args.addProperty("p_operation", UUID.randomUUID().toString());
        if (expected != null) args.addProperty("p_expected", expected);
        refusal.remove();
        for (int attempt = 0; attempt < 2 && clan.current(session); attempt++)
        {
            ApiResult result = db.rpcResult("fb_lfg", args);
            if (result.successful()) return true;
            // A domain refusal (HTTP 200 with a non-ok status) carries a
            // readable reason; transport errors don't.
            if (result.getHttpStatus() >= 200 && result.getHttpStatus() < 300 && result.getError() == null) refusal.set(result.message());
            if (!result.retryable()) return false;
        }
        return false;
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Session;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;

/**
 * The live state behind the LFG tab: the 30-second poll, the cached
 * snapshot, every write, and the diff between consecutive polls that
 * becomes chat/desktop notifications. The tab only renders what this holds.
 */
@Slf4j
@Singleton
public class PartyBoard
{
    // ASAP first (newest first), then scheduled by start time, then
    // scheduled posts whose start (plus grace) has passed.
    public static final Comparator<Party> ORDER = (a, b) -> {
        int byGroup = Integer.compare(group(a), group(b));
        if (byGroup != 0) return byGroup;
        int byStart = a.isScheduled() ? a.getScheduledFor().compareTo(b.getScheduledFor()) : 0;
        return byStart != 0 ? byStart : b.getCreatedAt().compareTo(a.getCreatedAt());
    };
    private static final DateTimeFormatter DAY_TIME = DateTimeFormatter.ofPattern("EEE HH:mm", Locale.ENGLISH);

    public interface Listener
    {
        // Executor thread; the tab hops to the EDT.
        void onChanged();
    }

    private final Client client;
    private final ClientThread clientThread;
    private final FinalBossConfig config;
    private final Clan clan;
    private final PartyApi api;
    private final Notifier notifier;
    private final ScheduledExecutorService executor;

    private volatile List<Party> parties = Collections.emptyList();
    private volatile List<FormedParty> formed = Collections.emptyList();
    private volatile Set<String> online = Collections.emptySet();
    private volatile int world;
    private volatile Listener listener = () -> {};
    private volatile boolean enabled;
    private volatile long epoch;
    private volatile String refreshError;
    private ScheduledFuture<?> poll;
    private final AtomicBoolean refreshing = new AtomicBoolean();
    private final AtomicBoolean writing = new AtomicBoolean();

    // Diff state; guarded by `this`.
    private Map<String, Party> previous = Collections.emptyMap();
    private Set<String> previousFormed = Collections.emptySet();
    private boolean primed;
    private final Set<String> selfLeft = new HashSet<>();
    // Scheduled parties already announced as starting soon / unfilled.
    private final Set<String> startingSoon = new HashSet<>();
    private final Set<String> unfilled = new HashSet<>();

    @Inject
    public PartyBoard(Client client, ClientThread clientThread, FinalBossConfig config, Clan clan, PartyApi api,
                      Notifier notifier, ScheduledExecutorService executor)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.clan = clan;
        this.api = api;
        this.notifier = notifier;
        this.executor = executor;
    }

    // ------------------------------------------------------------ reads

    public void setListener(Listener listener)
    {
        this.listener = listener;
    }

    public List<Party> parties()
    {
        return parties;
    }

    public List<FormedParty> formed()
    {
        return formed;
    }

    // Normalized names of clan members currently in the clan channel.
    public Set<String> online()
    {
        return online;
    }

    public int world()
    {
        return world;
    }

    public String refreshError()
    {
        return refreshError;
    }

    public boolean isBusy()
    {
        return writing.get();
    }

    // True while the board is polling (verified, LFG on).
    public boolean running()
    {
        return enabled;
    }

    // Every post this player hosts, in ORDER.
    public List<Party> mine()
    {
        String rsn = clan.rsn();
        List<Party> out = new ArrayList<>();
        for (Party p : parties)
        {
            if (p.isHostedBy(rsn)) out.add(p);
        }
        out.sort(ORDER);
        return out;
    }

    // This player's ASAP post, else null.
    public Party mineAsap()
    {
        for (Party p : mine())
        {
            if (!p.isScheduled()) return p;
        }
        return null;
    }

    public int mineScheduled()
    {
        int n = 0;
        for (Party p : mine())
        {
            if (p.isScheduled()) n++;
        }
        return n;
    }

    // "ASAP", or the start in the player's time zone: "Sat 20:00".
    public static String when(Instant at)
    {
        return at == null ? "ASAP" : DAY_TIME.withZone(ZoneId.systemDefault()).format(at);
    }

    private static int group(Party p)
    {
        if (!p.isScheduled()) return 0;
        return Instant.now().isAfter(p.getScheduledFor().plus(Party.GRACE)) ? 2 : 1;
    }

    // ------------------------------------------------------------ lifecycle

    public synchronized void start()
    {
        if (!config.enableLfg() || poll != null) return;
        enabled = true;
        poll = executor.scheduleAtFixedRate(() -> {
            try
            {
                refresh();
            }
            catch (Exception e)
            {
                log.warn("LFG poll error", e);
            }
        }, 0, 30, TimeUnit.SECONDS);
    }

    public synchronized void stop()
    {
        enabled = false;
        epoch++;
        online = Collections.emptySet();
        world = 0;
        refreshError = null;
        api.publish(PartyApi.EMPTY);
        if (poll != null)
        {
            poll.cancel(true);
            poll = null;
        }
        previous = Collections.emptyMap();
        previousFormed = Collections.emptySet();
        primed = false;
        selfLeft.clear();
        startingSoon.clear();
        unfilled.clear();
        parties = Collections.emptyList();
        formed = Collections.emptyList();
    }

    // Called before the local player leaves/cancels, so the next diff
    // doesn't announce their own action back at them.
    public synchronized void expectSelfLeave(String partyId)
    {
        if (partyId != null) selfLeft.add(partyId);
    }

    // ------------------------------------------------------------ poll and writes

    // Executor. A failed fetch leaves the snapshot alone: an outage must
    // never read as "every party was cancelled".
    public void refresh()
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (!enabled || !config.enableLfg() || !clan.current(session) || !refreshing.compareAndSet(false, true)) return;
        try
        {
            clientThread.invokeLater(() -> { if (enabled && capturedEpoch == epoch && clan.current(session)) readClient(); });
            PartyApi.Snapshot fetched = api.fetch();
            if (fetched == null)
            {
                if (enabled && capturedEpoch == epoch && clan.current(session))
                {
                    refreshError = "Board unavailable. Showing the last loaded parties.";
                    listener.onChanged();
                }
                return;
            }
            synchronized (this)
            {
                if (!enabled || capturedEpoch != epoch || !clan.current(session)) return;
                refreshError = null;
                api.publish(fetched);
                parties = fetched.getParties();
                formed = fetched.getFormed();
                notify(parties, formed, session.getRsn());
            }
            if (enabled && capturedEpoch == epoch && clan.current(session)) listener.onChanged();
        }
        finally
        {
            refreshing.set(false);
        }
    }

    // One write at a time, on the executor. `onError` gets null on success,
    // else the server's reason ("Party is full") or `failure`.
    public void run(BooleanSupplier action, String failure, Consumer<String> onError)
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (!enabled || !config.enableLfg() || !clan.current(session) || !writing.compareAndSet(false, true))
        {
            onError.accept("Wait for the current action, or reconnect and refresh.");
            return;
        }
        listener.onChanged();
        executor.submit(() -> {
            boolean ok = false;
            String reason = null;
            try
            {
                if (enabled && capturedEpoch == epoch && config.enableLfg()) ok = api.inSession(session, action);
                reason = api.refusal();
            }
            catch (RuntimeException e)
            {
                log.warn("LFG action failed", e);
            }
            finally
            {
                writing.set(false);
            }
            if (enabled && capturedEpoch == epoch && clan.current(session))
            {
                onError.accept(ok ? null : reason != null ? reason : failure);
                refresh();
                listener.onChanged();
            }
        });
    }

    // Client thread: who is in the clan channel, and the current world.
    private void readClient()
    {
        Set<String> names = new HashSet<>();
        ClanChannel cc = client.getClanChannel();
        if (cc != null)
        {
            for (ClanChannelMember m : cc.getMembers())
            {
                if (m.getName() != null) names.add(Names.normalize(m.getName()));
            }
        }
        boolean changed = !online.equals(names) || world != client.getWorld();
        online = Collections.unmodifiableSet(names);
        world = client.getWorld();
        if (changed) listener.onChanged();
    }

    // ------------------------------------------------------------ notifications

    private void notify(List<Party> now, List<FormedParty> formedNow, String rsn)
    {
        if (rsn == null) return;
        Map<String, Party> nowById = new HashMap<>();
        for (Party p : now)
        {
            nowById.put(p.getId(), p);
        }
        Set<String> formedIds = new HashSet<>();
        Map<String, FormedParty> formedFrom = new HashMap<>();
        for (FormedParty f : formedNow)
        {
            formedIds.add(f.getId());
            if (f.getPartyId() != null) formedFrom.put(f.getPartyId(), f);
        }
        List<String> messages = new ArrayList<>();
        synchronized (this)
        {
            if (primed)
            {
                diff(previous, nowById, rsn, formedFrom, messages);
                reminders(now, rsn, messages);
                for (FormedParty f : formedNow)
                {
                    if (!previousFormed.contains(f.getId()) && f.includes(rsn))
                    {
                        messages.add((f.isHostedBy(rsn) ? "Your" : f.getHostRsn() + "'s") + " " + f.title()
                            + " party has formed" + world(f.getWorld()) + ": " + f.roster() + ".");
                    }
                }
            }
            else
            {
                // First poll after login: remember what already qualifies so
                // reminders aren't replayed on every login.
                reminders(now, rsn, new ArrayList<>());
            }
            previous = nowById;
            previousFormed = formedIds;
            primed = true;
        }
        messages.forEach(this::deliver);
    }

    private void diff(Map<String, Party> prev, Map<String, Party> now, String rsn, Map<String, FormedParty> formedFrom, List<String> out)
    {
        for (Party p : now.values())
        {
            Party before = prev.get(p.getId());
            if (p.isHostedBy(rsn))
            {
                for (Party.Applicant a : p.pending())
                {
                    // New, or back after being declined.
                    Party.Applicant was = before == null ? null : before.applicantFor(a.getRsn());
                    if (was == null || was.getStatus() == Party.Status.DECLINED)
                    {
                        out.add(a.getRsn() + " applied to your " + p.title() + " party"
                            + (a.getRole() == null ? "" : " as " + a.getRole().getDisplayName())
                            + (a.isLearner() ? " (learner)" : "") + ".");
                    }
                }
                continue;
            }
            Party.Applicant mine = p.applicantFor(rsn);
            Party.Applicant mineBefore = before == null ? null : before.applicantFor(rsn);
            if (mine != null && mine.getStatus() != Party.Status.DECLINED && before != null
                && !Objects.equals(before.getScheduledFor(), p.getScheduledFor()))
            {
                out.add(p.getHostRsn() + " moved their " + p.title() + " party to " + when(p.getScheduledFor()) + ".");
            }
            if (mine != null && mine.isAccepted() && (mineBefore == null || !mineBefore.isAccepted()))
            {
                out.add((mine.isAddedByHost() ? p.getHostRsn() + " added you to their " : "You've been accepted to " + p.getHostRsn() + "'s ")
                    + p.title() + " party" + world(p.getWorld()) + ".");
            }
            else if (mine != null && mineBefore != null && mine.getStatus() == Party.Status.DECLINED && mineBefore.getStatus() != Party.Status.DECLINED)
            {
                out.add(p.getHostRsn() + " declined your " + p.title() + " application.");
            }
            // Only a seated member is "removed"; a pending application also
            // disappears quietly when the player joins another ASAP party.
            else if (mine == null && mineBefore != null && !selfLeft.remove(p.getId()) && mineBefore.isAccepted())
            {
                out.add("You were removed from " + p.getHostRsn() + "'s " + p.title() + " party.");
            }
        }
        // Parties that vanished. Members of one that formed hear it from the
        // formed list; everyone else involved is told here.
        for (Party before : prev.values())
        {
            if (now.containsKey(before.getId())) continue;
            FormedParty formedAs = formedFrom.get(before.getId());
            boolean formed = formedAs != null;
            boolean expired = !Instant.now().isBefore(before.expiresAt());
            if (before.isHostedBy(rsn))
            {
                if (!formed && expired) out.add("Your " + before.title() + " post expired after 7 days without filling.");
                continue;
            }
            Party.Applicant mineBefore = before.applicantFor(rsn);
            if (mineBefore == null || mineBefore.getStatus() == Party.Status.DECLINED || selfLeft.remove(before.getId())) continue;
            if (!formed)
            {
                out.add(before.getHostRsn() + "'s " + before.title() + " party " + (expired ? "expired." : "was cancelled."));
            }
            else if (!formedAs.includes(rsn))
            {
                out.add(before.getHostRsn() + "'s " + before.title() + " party filled without you.");
            }
        }
        selfLeft.clear();
    }

    // Scheduled parties: "starts in N min" to the host and accepted
    // members, and one "didn't fill" to the host once the time passes.
    private void reminders(List<Party> now, String rsn, List<String> out)
    {
        Instant t = Instant.now();
        for (Party p : now)
        {
            if (!p.isScheduled()) continue;
            boolean host = p.isHostedBy(rsn);
            Party.Applicant mine = p.applicantFor(rsn);
            boolean in = host || (mine != null && mine.isAccepted());
            long minutes = Duration.between(t, p.getScheduledFor()).toMinutes();
            // Keyed by the start time too, so a moved party reminds again.
            String key = p.getId() + "@" + p.getScheduledFor();
            if (in && minutes >= 0 && minutes <= 15 && startingSoon.add(key))
            {
                out.add((host ? "Your " : p.getHostRsn() + "'s ") + p.title() + " party starts in " + Math.max(1, minutes) + " min"
                    + world(p.getWorld()) + ".");
            }
            if (host && t.isAfter(p.getScheduledFor()) && !p.isFull() && unfilled.add(key))
            {
                out.add("Your " + p.title() + " party didn't fill by its start time. Edit the time or cancel it.");
            }
        }
    }

    private static String world(Integer world)
    {
        return world == null ? "" : " (World " + world + ")";
    }

    private void deliver(String message)
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (config.lfgPartyNotifications())
        {
            clientThread.invokeLater(() -> {
                if (!enabled || capturedEpoch != epoch || !clan.current(session)) return true;
                GameState state = client.getGameState();
                // Mid-teleport or hop: hold the line until the chatbox is back.
                if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.CONNECTION_LOST) return false;
                if (state == GameState.LOGGED_IN) client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[LFG] " + message, null);
                return true;
            });
        }
        if (config.lfgDesktopNotifications())
        {
            notifier.notify("Final Boss LFG: " + message);
        }
    }
}

package com.github.orgonag.fbclan.lfg;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * A seat a player can fill in a role-based activity, plus the
 * composition rules. Each difficulty mode owns its own role set so a
 * pick in one mode never matches a party of another. The *_FILL values
 * are wildcards: a real flexible seat in CoX, "any role" on an
 * application for ToB and BA.
 *
 * <ul>
 * <li>ToB / HMT: composition is fixed by size (3 = Melee/Ranged/Freeze;
 *     4 splits North/South; 5 runs two Melee).</li>
 * <li>CoX / CM: the host sets a count per role, Fill takes the rest.</li>
 * <li>BA: one of each base role, and a spare seat that may double one.</li>
 * </ul>
 * Stored in the database by enum name.
 */
@Getter
public enum Role
{
    TOB_MELEE("Melee"), TOB_RANGED("Ranged"), TOB_FRZ("Freeze"), TOB_NFRZ("North freeze"), TOB_SFRZ("South freeze"), TOB_FILL("Any"),
    TOB_HM_MELEE("Melee"), TOB_HM_RANGED("Ranged"), TOB_HM_FRZ("Freeze"), TOB_HM_NFRZ("North freeze"), TOB_HM_SFRZ("South freeze"), TOB_HM_FILL("Any"),
    COX_MELEE("Melee"), COX_MAGE("Mage"), COX_RUNNER("Runner"), COX_FILL("Fill"),
    COX_CM_VENG("Veng"), COX_CM_ANCIENT("Ancient"), COX_CM_NORMAL("Normal spells"), COX_CM_FILL("Fill"),
    BA_ATTACKER("Attacker"), BA_DEFENDER("Defender"), BA_COLLECTOR("Collector"), BA_HEALER("Healer"), BA_FILL("Any");

    private static final Set<Role> TOB_FREEZE = EnumSet.of(TOB_FRZ, TOB_NFRZ, TOB_SFRZ);
    private static final Set<Role> TOB_HM_FREEZE = EnumSet.of(TOB_HM_FRZ, TOB_HM_NFRZ, TOB_HM_SFRZ);
    private static final Set<Role> FILLS = EnumSet.of(TOB_FILL, TOB_HM_FILL, COX_FILL, COX_CM_FILL, BA_FILL);
    // BA: one of each base role, and a spare seat that may double one.
    private static final List<Role> BA_SEATS = Arrays.asList(BA_ATTACKER, BA_DEFENDER, BA_COLLECTOR, BA_HEALER, BA_FILL);

    private final String displayName;

    Role(String displayName)
    {
        this.displayName = displayName;
    }

    public String key()
    {
        return name();
    }

    public boolean isFill()
    {
        return FILLS.contains(this);
    }

    // Can a player who picked this role take a seat advertised as `needed`?
    public boolean canFill(Role needed)
    {
        if (needed == null)
        {
            return false;
        }
        if (!family().equals(needed.family())) return false;
        if (this == needed || isFill() || needed.isFill())
        {
            return true;
        }
        return (this == TOB_FRZ && TOB_FREEZE.contains(needed))
            || (this == TOB_HM_FRZ && TOB_HM_FREEZE.contains(needed));
    }

    private String family()
    {
        String key = name();
        if (key.startsWith("TOB_HM_")) return "TOB_HM";
        if (key.startsWith("COX_CM_")) return "COX_CM";
        return key.substring(0, key.indexOf('_'));
    }

    public static Role fromKey(String key)
    {
        try
        {
            return key == null ? null : valueOf(key);
        }
        catch (IllegalArgumentException e)
        {
            return null;
        }
    }

    @Override
    public String toString()
    {
        return displayName;
    }

    // ------------------------------------------------------------ composition

    // Every role a player can be in this activity/mode, in display order.
    public static List<Role> playable(Activity activity, boolean hardMode)
    {
        switch (activity)
        {
            case TOB:
                return hardMode
                    ? Arrays.asList(TOB_HM_MELEE, TOB_HM_RANGED, TOB_HM_FRZ, TOB_HM_NFRZ, TOB_HM_SFRZ)
                    : Arrays.asList(TOB_MELEE, TOB_RANGED, TOB_FRZ, TOB_NFRZ, TOB_SFRZ);
            case COX:
                return hardMode
                    ? Arrays.asList(COX_CM_VENG, COX_CM_ANCIENT, COX_CM_NORMAL, COX_CM_FILL)
                    : Arrays.asList(COX_MELEE, COX_MAGE, COX_RUNNER, COX_FILL);
            case BA:
                return Arrays.asList(BA_ATTACKER, BA_DEFENDER, BA_COLLECTOR, BA_HEALER);
            default:
                return Collections.emptyList();
        }
    }

    public static Role any(Activity activity, boolean hardMode)
    {
        switch (activity)
        {
            case TOB: return hardMode ? TOB_HM_FILL : TOB_FILL;
            case COX: return hardMode ? COX_CM_FILL : COX_FILL;
            case BA: return BA_FILL;
            default: return null;
        }
    }

    public static List<Role> tobComposition(int size, boolean hard)
    {
        List<Role> comp = new ArrayList<>();
        int melee = size >= 5 ? 2 : size >= 2 ? 1 : 0;
        int ranged = size >= 3 ? 1 : 0;
        int freezers = Math.max(0, size - melee - ranged);
        for (int i = 0; i < melee; i++)
        {
            comp.add(hard ? TOB_HM_MELEE : TOB_MELEE);
        }
        for (int i = 0; i < ranged; i++)
        {
            comp.add(hard ? TOB_HM_RANGED : TOB_RANGED);
        }
        if (freezers == 1)
        {
            comp.add(hard ? TOB_HM_FRZ : TOB_FRZ);
            return comp;
        }
        for (int i = 0; i < (freezers + 1) / 2; i++)
        {
            comp.add(hard ? TOB_HM_NFRZ : TOB_NFRZ);
        }
        for (int i = 0; i < freezers / 2; i++)
        {
            comp.add(hard ? TOB_HM_SFRZ : TOB_SFRZ);
        }
        return comp;
    }

    // The composition to store for a new party: ToB's fixed layout, the
    // host's CoX counts padded with Fill, or nothing.
    public static List<Role> required(Activity activity, boolean hard, int capacity, Map<Role, Integer> coxCounts)
    {
        if (activity == Activity.TOB)
        {
            return tobComposition(capacity, hard);
        }
        if (activity != Activity.COX)
        {
            return Collections.emptyList();
        }
        List<Role> roles = new ArrayList<>();
        for (Role role : playable(activity, hard))
        {
            int n = role.isFill() || coxCounts == null ? 0 : Math.max(0, coxCounts.getOrDefault(role, 0));
            if (roles.size() + n > capacity) throw new IllegalArgumentException("Role counts exceed party capacity");
            for (int i = 0; i < n; i++)
            {
                roles.add(role);
            }
        }
        while (roles.size() < capacity)
        {
            roles.add(any(activity, hard));
        }
        return roles;
    }

    // Seats nobody has claimed yet, given the composition and the roles
    // already taken (host + accepted members). Specific roles are seated
    // first: their own seat, else an interchangeable one (ToB freezes),
    // else a Fill seat. "Any" members go last: they take a Fill seat if
    // one is left, otherwise they float and end up with whatever remains
    // - so the list can be longer than the number of free places. The
    // server (fb_private.unclaimed) seats people the same way.
    public static List<Role> open(Activity activity, List<Role> required, List<Role> taken)
    {
        List<Role> open = new ArrayList<>(activity == Activity.BA ? BA_SEATS : required == null ? Collections.<Role>emptyList() : required);
        for (Role t : taken)
        {
            if (t == null) return Collections.emptyList();
            if (t.isFill()) continue;
            int seat = seat(open, t);
            if (seat < 0) return Collections.emptyList();
            open.remove(seat);
        }
        for (Role t : taken)
        {
            if (t.isFill()) open.remove(t);
        }
        return open;
    }

    private static int seat(List<Role> open, Role wanted)
    {
        int seat = open.indexOf(wanted);
        // Not its own seat: an interchangeable one first, a Fill seat last.
        for (boolean fill : new boolean[] {false, true})
        {
            for (int i = 0; seat < 0 && i < open.size(); i++)
            {
                if (open.get(i).isFill() == fill && wanted.canFill(open.get(i))) seat = i;
            }
        }
        return seat;
    }

    // Distinct roles a player could apply as, plus the mode's wildcard.
    public static List<Role> applyOptions(Activity activity, boolean hard, List<Role> open)
    {
        List<Role> options = new ArrayList<>();
        if (open.isEmpty())
        {
            return options;
        }
        for (Role role : playable(activity, hard))
        {
            if (!role.isFill() && open.stream().anyMatch(role::canFill))
            {
                options.add(role);
            }
        }
        Role any = any(activity, hard);
        if (any != null)
        {
            options.add(any);
        }
        return options;
    }

    // "Melee, Melee, N freeze" -> "2x Melee, North freeze".
    public static String summarize(List<Role> roles)
    {
        Map<Role, Integer> counts = new EnumMap<>(Role.class);
        List<Role> order = new ArrayList<>();
        for (Role r : roles)
        {
            if (counts.merge(r, 1, Integer::sum) == 1)
            {
                order.add(r);
            }
        }
        StringBuilder sb = new StringBuilder();
        for (Role r : order)
        {
            if (sb.length() > 0)
            {
                sb.append(", ");
            }
            int n = counts.get(r);
            sb.append(n > 1 ? n + "x " : "").append(r.displayName);
        }
        return sb.toString();
    }

    // required_roles column: comma-separated keys.
    public static String encode(List<Role> roles)
    {
        if (roles == null || roles.isEmpty())
        {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (Role r : roles)
        {
            sb.append(sb.length() > 0 ? "," : "").append(r.key());
        }
        return sb.toString();
    }

    // Unknown keys (a newer client) are dropped, not fatal.
    public static List<Role> decode(String encoded)
    {
        List<Role> roles = new ArrayList<>();
        if (encoded != null)
        {
            for (String part : encoded.split(","))
            {
                Role r = fromKey(part.trim());
                if (r != null)
                {
                    roles.add(r);
                }
            }
        }
        return roles;
    }
}

package com.github.orgonag.fbclan.pbs;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Read side of the PB leaderboard: the pb_leaderboard view (top 3 per
 * boss, server-ranked) and recent_clan_bests (live-sourced current #1s,
 * newest first). Each fetch fails soft independently, keeping last data.
 */
@Singleton
public class Leaderboards
{
    @Value
    public static class Entry
    {
        String rsn;
        String bossKey;
        double seconds;
        String achievedAt; // ISO timestamp, may be blank
    }

    private final Supabase db;
    private volatile List<Entry> board = Collections.emptyList();
    private volatile List<Entry> recent = Collections.emptyList();

    @Inject
    public Leaderboards(Supabase db)
    {
        this.db = db;
    }

    public List<Entry> board()
    {
        return board;
    }

    public List<Entry> recent()
    {
        return recent;
    }

    // Executor. A failed fetch keeps the previous board.
    public boolean refresh()
    {
        boolean complete = true;
        JsonArray rows = db.getOrNull("pb_leaderboard", "select=rsn,boss_key,seconds,achieved_at&order=boss_key.asc,rank.asc,rsn.asc");
        if (rows != null)
        {
            board = parse(rows);
        }
        else complete = false;
        rows = db.getOrNull("recent_clan_bests", "select=rsn,boss_key,seconds,achieved_at&order=achieved_at.desc");
        if (rows != null)
        {
            recent = parse(rows);
        }
        else complete = false;
        return complete;
    }

    private static List<Entry> parse(JsonArray rows)
    {
        List<Entry> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            String rsn = Supabase.str(row, "rsn");
            String boss = Supabase.str(row, "boss_key");
            if (rsn.isEmpty() || boss.isEmpty() || !Supabase.has(row, "seconds"))
            {
                continue;
            }
            double seconds = Supabase.doubleOr(row, "seconds", -1);
            if (seconds <= 0 || seconds >= 86400) continue;
            out.add(new Entry(rsn, boss, seconds, Supabase.str(row, "achieved_at")));
        }
        return Collections.unmodifiableList(out);
    }
}

package com.github.orgonag.fbclan.pbs;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Display helpers for PB boss keys (as RuneLite's Chat Commands stores them) and times. */
public final class PbFormat
{
    private static final Pattern TEAM_SUFFIX = Pattern.compile(" (solo|\\d+(?:\\+|-\\d+)? players?)$");
    private static final String[][] RAID_ABBREVIATIONS = {
        {"chambers of xeric challenge mode", "CM"},
        {"chambers of xeric", "COX"},
        {"theatre of blood hard mode", "HMT"},
        {"theatre of blood", "TOB"},
        {"tombs of amascut expert mode", "TOA Expert"},
        {"tombs of amascut", "TOA"},
    };

    private PbFormat()
    {
    }

    // Port of core's secondsToTimeString: whole seconds without ".00".
    public static String seconds(double seconds)
    {
        int hours = (int) (Math.floor(seconds) / 3600);
        int minutes = (int) (Math.floor(seconds / 60) % 60);
        seconds = seconds % 60;
        String prefix = hours > 0 ? String.format(Locale.ROOT, "%d:%02d:", hours, minutes) : String.format(Locale.ROOT, "%d:", minutes);
        return prefix + (Math.floor(seconds) == seconds
            ? String.format(Locale.ROOT, "%02d", (int) seconds)
            : String.format(Locale.ROOT, "%05.2f", seconds));
    }

    // "theatre of blood 4 players" -> "TOB (4 players)".
    public static String boss(String bossKey)
    {
        String base = bossKey.toLowerCase(Locale.ROOT);
        String suffix = null;
        Matcher m = TEAM_SUFFIX.matcher(base);
        if (m.find())
        {
            suffix = m.group(1).equals("solo") ? "Solo" : m.group(1);
            base = base.substring(0, m.start());
        }
        StringBuilder sb = new StringBuilder();
        for (String[] abbr : RAID_ABBREVIATIONS)
        {
            if (base.equals(abbr[0]) || base.startsWith(abbr[0] + " "))
            {
                sb.append(abbr[1]);
                base = base.substring(abbr[0].length()).trim();
                break;
            }
        }
        for (String word : base.split(" "))
        {
            if (word.isEmpty()) continue;
            if (sb.length() > 0) sb.append(' ');
            sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
        }
        if (suffix != null) sb.append(" (").append(suffix).append(')');
        return sb.toString();
    }
}

package com.github.orgonag.fbclan.pbs;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Keeps the clan PB board in step with the PBs RuneLite's Chat Commands
 * plugin already records per account (the source of truth, raid team
 * sizes included); the clan database is only a copy of it for display.
 * The first sync of each login sends every PB, so that copy always
 * matches this client whatever happened in between (a rename, another
 * backend, a reset); every 30 minutes after that, only what changed.
 * A PB that is new since the last successful sync is sent as "live"
 * (the clan-bests list shows those); everything else as "seed".
 */
@Slf4j
@Singleton
public class PersonalBests
{
    private static final int MAX_BATCH = 250; // fb_submit_pbs rejects > 300
    // What was last synced, per RuneLite profile (kept outside the
    // plugin's settings group).
    private static final String GROUP = "finalbossui";
    private static final String KEY = "pbSynced";
    private static final Type TIMES = new TypeToken<Map<String, Double>>() {}.getType();

    @Value
    private static class Entry
    {
        String bossKey;
        double seconds;
        String source;
    }

    private final FinalBossConfig config;
    private final Clan clan;
    private final Supabase db;
    private final ConfigManager configManager;
    private final ScheduledExecutorService executor;
    private final Gson gson;
    private final AtomicBoolean syncing = new AtomicBoolean();
    // The login (session generation) whose PBs have all been sent.
    private volatile long fullSync = -1;

    @Inject
    public PersonalBests(FinalBossConfig config, Clan clan, Supabase db, ConfigManager configManager,
                         ScheduledExecutorService executor, Gson gson)
    {
        this.config = config;
        this.clan = clan;
        this.db = db;
        this.configManager = configManager;
        this.executor = executor;
        this.gson = gson;
    }

    // Client thread (the world-type check reads the client).
    public void sync()
    {
        Session session = clan.snapshot();
        if (!clan.canUpload() || !config.enablePbUpload() || !clan.onStandardWorld() || !syncing.compareAndSet(false, true)) return;
        boolean queued = false;
        try
        {
            if (!session.getProfile().equals(configManager.getRSProfileKey())) return;
            Map<String, Double> now = stored();
            Map<String, Double> before = lastSynced(session);
            boolean everything = fullSync != session.getGeneration();
            List<Entry> sending = new ArrayList<>();
            now.forEach((key, seconds) -> {
                boolean fresh = before == null || !seconds.equals(before.get(key));
                if (fresh || everything) sending.add(new Entry(key, seconds, fresh && before != null ? "live" : "seed"));
            });
            String snapshot = gson.toJson(now);
            if (sending.isEmpty())
            {
                // Nothing to send, but record the first sync so later PBs count as live.
                if (before == null) configManager.setConfiguration(GROUP, session.getProfile(), KEY, snapshot);
                return;
            }
            queued = true;
            executor.submit(() -> {
                try
                {
                    // Written to the profile it was read from, whichever account is logged in by now.
                    if (submit(session, sending))
                    {
                        configManager.setConfiguration(GROUP, session.getProfile(), KEY, snapshot);
                        fullSync = session.getGeneration();
                    }
                }
                finally
                {
                    syncing.set(false);
                }
            });
        }
        finally
        {
            if (!queued) syncing.set(false);
        }
    }

    // Every PB the Chat Commands plugin holds for the current profile.
    private Map<String, Double> stored()
    {
        Map<String, Double> out = new TreeMap<>();
        for (String key : configManager.getRSProfileConfigurationKeys("personalbest", configManager.getRSProfileKey(), ""))
        {
            try
            {
                Double seconds = configManager.getRSProfileConfiguration("personalbest", key, double.class);
                if (key != null && !key.isEmpty() && seconds != null && Double.isFinite(seconds) && seconds > 0 && seconds < 86400)
                {
                    out.put(key, seconds);
                }
            }
            catch (RuntimeException e)
            {
                log.debug("Ignoring invalid stored PB");
            }
        }
        return out;
    }

    // Null when this profile has never synced.
    private Map<String, Double> lastSynced(Session session)
    {
        String json = configManager.getConfiguration(GROUP, session.getProfile(), KEY);
        if (json == null || json.isEmpty()) return null;
        try
        {
            return gson.fromJson(json, TIMES);
        }
        catch (RuntimeException e)
        {
            return null;
        }
    }

    // Executor.
    private boolean submit(Session session, List<Entry> entries)
    {
        for (int start = 0; start < entries.size(); start += MAX_BATCH)
        {
            if (!clan.current(session) || !config.enablePbUpload()) return false;
            JsonArray batch = new JsonArray();
            for (Entry s : entries.subList(start, Math.min(start + MAX_BATCH, entries.size())))
            {
                JsonObject e = new JsonObject();
                e.addProperty("boss_key", s.getBossKey());
                e.addProperty("seconds", s.getSeconds());
                e.addProperty("source", s.getSource());
                batch.add(e);
            }
            JsonObject payload = new JsonObject();
            payload.addProperty("p_rsn", session.getRsn());
            payload.add("p_entries", batch);
            if (!db.rpc("fb_submit_pbs", payload)) return false;
        }
        return true;
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

/**
 * Prepends a combat-achievement slayer helmet (Tztok = Elite, Vampyric
 * = Master, Tzkal = Grandmaster) to clan members' names in chat. Tiers
 * come from the same read-only ca_leaderboard view the dashboard uses,
 * so only members who upload stats get a badge.
 */
@Singleton
public class CaBadges
{
    private static final Set<ChatMessageType> BADGED = EnumSet.of(
        ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.PRIVATECHAT,
        ChatMessageType.PRIVATECHATOUT, ChatMessageType.MODPRIVATECHAT, ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT);

    private final Supabase db;
    private final ChatIconManager icons;
    private final Map<String, Integer> iconByTier = new HashMap<>();
    private volatile Map<String, String> tierByRsn = Collections.emptyMap();

    @Inject
    public CaBadges(Supabase db, ChatIconManager icons)
    {
        this.db = db;
        this.icons = icons;
    }

    // Icons are registered on first use, not at injection time, so a
    // loaded-but-disabled plugin registers nothing.
    private synchronized void ensureIcons()
    {
        if (iconByTier.isEmpty())
        {
            iconByTier.put("Elite", register("ca_elite.png"));
            iconByTier.put("Master", register("ca_master.png"));
            iconByTier.put("Grandmaster", register("ca_grandmaster.png"));
        }
    }

    private int register(String resource)
    {
        BufferedImage image = ImageUtil.loadImageResource(CaBadges.class, "/com/github/orgonag/fbclan/" + resource);
        return icons.registerChatIcon(image);
    }

    // Executor. False when the fetch failed (the previous tiers are kept).
    public boolean refresh()
    {
        JsonArray rows = db.getOrNull("member_badges", "select=rsn,tier&order=rsn.asc");
        if (rows == null)
        {
            return false;
        }
        Map<String, String> tiers = new HashMap<>();
        for (JsonElement el : rows)
        {
            JsonObject row = el.getAsJsonObject();
            String rsn = Text.standardize(Supabase.str(row, "rsn"));
            String tier = Supabase.str(row, "tier");
            if (!rsn.isEmpty() && !tier.isEmpty())
            {
                tiers.put(rsn, tier);
            }
        }
        tierByRsn = Collections.unmodifiableMap(tiers);
        return true;
    }

    // Client thread. Chat names carry img tags and non-breaking spaces;
    // Text.standardize strips both, matching how the stored RSNs are keyed.
    public void onChatMessage(ChatMessage event)
    {
        if (!BADGED.contains(event.getType()) || event.getName() == null)
        {
            return;
        }
        ensureIcons();
        Integer icon = iconByTier.get(tierByRsn.get(Text.standardize(event.getName())));
        if (icon == null)
        {
            return;
        }
        int index = icons.chatIconIndex(icon);
        if (index < 0)
        {
            return; // mod icon sprites not loaded yet (pre-login)
        }
        MessageNode node = event.getMessageNode();
        node.setName("<img=" + index + ">" + node.getName());
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Read side of the clan dashboard: collection-log and combat-achievement
 * top-20s (member uploads), GP this week (logged drops), and the weekly
 * Wise Old Man podiums served from the wom_cache table (a sync script
 * fills it; the plugin never calls WOM for this). Every source
 * fails soft independently, keeping last-known data.
 */
@Singleton
public class Dashboard
{
    @Value
    public static class Named
    {
        String rsn;
        double value;
    }

    @Value
    public static class ClEntry
    {
        String rsn;
        int obtained;
        int total;
    }

    @Value
    public static class CaEntry
    {
        String rsn;
        int points;
        String tier;
    }

    @Value
    public static class GpWeek
    {
        long totalGp;
        int dropCount;
        List<Named> top;
    }

    private final Supabase db;

    private volatile List<ClEntry> clBoard = Collections.emptyList();
    private volatile List<CaEntry> caBoard = Collections.emptyList();
    private volatile GpWeek gpWeek = new GpWeek(0, 0, Collections.emptyList());
    private volatile List<Named> xpWeek;   // null until the WOM cache is read
    private volatile List<Named> ehbWeek;
    private volatile String womSyncedAt = "";

    @Inject
    public Dashboard(Supabase db)
    {
        this.db = db;
    }

    public List<ClEntry> clBoard()
    {
        return clBoard;
    }

    public List<CaEntry> caBoard()
    {
        return caBoard;
    }

    public GpWeek gpWeek()
    {
        return gpWeek;
    }

    public List<Named> xpWeek()
    {
        return xpWeek;
    }

    public List<Named> ehbWeek()
    {
        return ehbWeek;
    }

    public String womSyncedAt()
    {
        return womSyncedAt;
    }

    // Executor. Each source fails soft independently, keeping its
    // previous value; an empty result is real and clears it.
    public boolean refresh()
    {
        JsonArray cl = db.getOrNull("cl_leaderboard", "select=rsn,cl_obtained,cl_total&order=cl_obtained.desc,rsn.asc");
        if (cl != null)
        {
            List<ClEntry> out = new ArrayList<>();
            for (JsonElement el : cl)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "cl_obtained") && Supabase.has(r, "cl_total"))
                {
                    out.add(new ClEntry(Supabase.str(r, "rsn"), Supabase.intOr(r,"cl_obtained",0), Supabase.intOr(r,"cl_total",0)));
                }
            }
            clBoard = Collections.unmodifiableList(out);
        }
        JsonArray ca = db.getOrNull("ca_leaderboard", "select=rsn,ca_points,tier&order=ca_points.desc,rsn.asc");
        if (ca != null)
        {
            List<CaEntry> out = new ArrayList<>();
            for (JsonElement el : ca)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "ca_points"))
                {
                    out.add(new CaEntry(Supabase.str(r, "rsn"), Supabase.intOr(r,"ca_points",0), Supabase.str(r, "tier")));
                }
            }
            caBoard = Collections.unmodifiableList(out);
        }
        JsonArray total = db.getOrNull("gp_week_total", "select=total_gp,drop_count");
        JsonArray top = db.getOrNull("gp_week_top", "select=rsn,gp&order=gp.desc,rsn.asc");
        if (total != null && top != null)
        {
            JsonObject t = total.size() > 0 ? total.get(0).getAsJsonObject() : new JsonObject();
            List<Named> names = new ArrayList<>();
            for (JsonElement el : top)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "gp"))
                {
                    names.add(new Named(Supabase.str(r, "rsn"), Supabase.doubleOr(r,"gp",0)));
                }
            }
            gpWeek = new GpWeek(Supabase.longOr(t, "total_gp", 0), Supabase.intOr(t, "drop_count", 0),
                Collections.unmodifiableList(names));
        }
        JsonArray wom = db.getOrNull("wom_cache", "select=metric,payload,updated_at");
        if (wom != null)
        {
            applyWomCache(wom);
        }
        return cl != null && ca != null && total != null && top != null && wom != null;
    }

    // Each row's payload is the raw WOM response array for one metric.
    private void applyWomCache(JsonArray rows)
    {
        xpWeek = Collections.emptyList();
        ehbWeek = Collections.emptyList();
        womSyncedAt = "";
        String newest = "";
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            String metric = Supabase.str(row, "metric");
            if (metric.isEmpty() || !Supabase.has(row, "payload") || !row.get("payload").isJsonArray())
            {
                continue;
            }
            String updated = Supabase.str(row, "updated_at");
            if (updated.compareTo(newest) > 0)
            {
                newest = updated;
            }
            if ("gains_overall_week".equals(metric))
            {
                xpWeek = parseWom(row.getAsJsonArray("payload"), "gained");
            }
            else if ("gains_ehb_week".equals(metric))
            {
                ehbWeek = parseWom(row.getAsJsonArray("payload"), "gained");
            }
        }
        if (!newest.isEmpty())
        {
            womSyncedAt = newest;
        }
    }

    private static List<Named> parseWom(JsonArray rows, String valueKey)
    {
        List<Named> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            if (!Supabase.has(row, "player") || !Supabase.has(row, "data") || !row.get("player").isJsonObject() || !row.get("data").isJsonObject())
            {
                continue;
            }
            JsonObject player = row.getAsJsonObject("player");
            JsonObject data = row.getAsJsonObject("data");
            if (Supabase.has(player, "displayName") && Supabase.has(data, valueKey))
            {
                out.add(new Named(Supabase.str(player,"displayName"), Supabase.doubleOr(data,valueKey,0)));
            }
        }
        return Collections.unmodifiableList(out);
    }

    // ------------------------------------------------------------ formatting

    // 9_800_000 -> "9.8M", 14_200_000 -> "14M".
    public static String shortNumber(long n)
    {
        if (n >= 1_000_000_000L)
        {
            return unit(n, 1_000_000_000L) + "B";
        }
        if (n >= 1_000_000L)
        {
            return unit(n, 1_000_000L) + "M";
        }
        if (n >= 1_000L)
        {
            return unit(n, 1_000L) + "K";
        }
        return Long.toString(n);
    }

    public static String oneDecimal(double d)
    {
        return String.format(Locale.ROOT, "%.1f", d);
    }

    private static String unit(long n, long divisor)
    {
        double d = (double) n / divisor;
        if (d >= 10)
        {
            return Long.toString(n / divisor);
        }
        String s = String.format(Locale.ROOT, "%.1f", d);
        return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonObject;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Uploads the member's collection-log count and combat-achievement
 * points through the improve-only fb_submit_stats function. Varps/varbits
 * are read on the client thread (after verification, then every 30 min);
 * the submit runs on the executor. Sent once per login and again only
 * when a value changes; the server keeps the highest.
 */
@Singleton
public class MemberStats
{
    private final Client client;
    private final FinalBossConfig config;
    private final Clan clan;
    private final Supabase db;
    private final ScheduledExecutorService executor;

    private volatile String acknowledged;
    private final AtomicBoolean sending = new AtomicBoolean();

    @Inject
    public MemberStats(Client client, FinalBossConfig config, Clan clan, Supabase db, ScheduledExecutorService executor)
    {
        this.client = client;
        this.config = config;
        this.clan = clan;
        this.db = db;
        this.executor = executor;
    }

    // Client thread (varp reads assert it under -ea).
    public void maybeSubmit()
    {
        Session session = clan.snapshot();
        if (!clan.canUpload() || !config.enableStatsUpload() || !clan.onStandardWorld())
        {
            return;
        }
        int clObtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
        int clTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        int caPoints = client.getVarbitValue(VarbitID.CA_POINTS);
        if ((clObtained <= 0 && caPoints <= 0))
        {
            return;
        }
        String tier = tierFor(caPoints, thresholds());
        String signature = session.getGeneration() + ":" + clObtained + ":" + clTotal + ":" + caPoints + ":" + tier;
        if (signature.equals(acknowledged) || !sending.compareAndSet(false, true)) return;
        executor.submit(() -> {
            try
            {
                if (clan.current(session) && config.enableStatsUpload() && submit(session.getRsn(), clObtained, clTotal, caPoints, tier)
                    && clan.current(session)) acknowledged = signature;
            }
            finally { sending.set(false); }
        });
    }

    private boolean submit(String rsn, int clObtained, int clTotal, int caPoints, String tier)
    {
        // Fields the client can't read yet are omitted; the RPC treats an
        // absent field as "no update".
        JsonObject p = new JsonObject();
        p.addProperty("p_rsn", rsn);
        boolean hasCl = clObtained > 0 && clTotal >= clObtained;
        boolean hasCa = caPoints > 0;
        if (hasCl)
        {
            p.addProperty("p_cl_obtained", clObtained);
            p.addProperty("p_cl_total", clTotal);
        }
        if (hasCa)
        {
            p.addProperty("p_ca_points", caPoints);
            if (tier != null)
            {
                p.addProperty("p_ca_tier", tier);
            }
        }
        return (hasCl || hasCa) && db.rpc("fb_submit_stats", p);
    }

    // Tier cutoffs read live from the game (Dink pattern) so new tasks
    // re-scale without a plugin update. Null = below Easy.
    private static String tierFor(int points, TreeMap<Integer, String> thresholds)
    {
        Map.Entry<Integer, String> e = thresholds.floorEntry(points);
        return e == null ? null : e.getValue();
    }

    private TreeMap<Integer, String> thresholds()
    {
        TreeMap<Integer, String> t = new TreeMap<>();
        put(t, VarbitID.CA_THRESHOLD_EASY, "Easy");
        put(t, VarbitID.CA_THRESHOLD_MEDIUM, "Medium");
        put(t, VarbitID.CA_THRESHOLD_HARD, "Hard");
        put(t, VarbitID.CA_THRESHOLD_ELITE, "Elite");
        put(t, VarbitID.CA_THRESHOLD_MASTER, "Master");
        put(t, VarbitID.CA_THRESHOLD_GRANDMASTER, "Grandmaster");
        return t;
    }

    private void put(TreeMap<Integer, String> map, int varbit, String tier)
    {
        int value = client.getVarbitValue(varbit);
        if (value > 0)
        {
            map.put(value, tier);
        }
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.lfg.Party;
import com.github.orgonag.fbclan.lfg.PartyApi;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import com.github.orgonag.fbclan.lfg.Role;
import java.awt.event.ActionListener;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;

/**
 * The host's "add a member who isn't on LFG" row: seats a buddy so the
 * spot shows as taken to everyone. One row per hosted post, kept across
 * re-renders (the board refreshes every 30s) so a half-typed name
 * survives; only the role list is rebuilt when the open roles change.
 */
final class AddMemberForm
{
    private static final class Row
    {
        final JTextField name = Theme.field("", 12);
        String shape;
        JPanel panel;
    }

    private final PartyBoard board;
    private final PartyApi api;
    // Null = added; else the error to show.
    private final Consumer<String> onResult;
    private final Map<String, Row> rows = new HashMap<>();

    AddMemberForm(PartyBoard board, PartyApi api, Consumer<String> onResult)
    {
        this.board = board;
        this.api = api;
        this.onResult = onResult;
    }

    // EDT. Forget every row (logout).
    void reset()
    {
        rows.clear();
    }

    // EDT. Forget rows for posts that are gone.
    void keep(Set<String> partyIds)
    {
        rows.keySet().retainAll(partyIds);
    }

    // EDT.
    JPanel view(Party p)
    {
        Row row = rows.computeIfAbsent(p.getId(), id -> new Row());
        String shape = p.getActivity() + ":" + p.isHardMode() + ":" + p.openRoles();
        if (!shape.equals(row.shape))
        {
            row.shape = shape;
            row.panel = build(p, row.name);
        }
        return row.panel;
    }

    private JPanel build(Party p, JTextField name)
    {
        String partyId = p.getId();
        String host = p.getHostRsn();
        JPanel panel = Theme.stack(4);
        panel.add(Theme.bold("Add a member who isn't on LFG", Theme.ACCENT_HI));
        name.setToolTipText("Their RSN");
        panel.add(Theme.labeled("Name", name));
        JComboBox<Object> roleBox = null;
        if (p.getActivity().hasRoles())
        {
            List<Role> options = Role.applyOptions(p.getActivity(), p.isHardMode(), p.openRoles());
            if (options.isEmpty()) options = Role.playable(p.getActivity(), p.isHardMode());
            roleBox = LfgUi.combo(options.toArray());
            panel.add(Theme.labeled("Role", roleBox));
        }
        JComboBox<Object> roles = roleBox;
        Runnable submit = () -> {
            // Underscores are spaces in a name; fold them so nobody is seated twice.
            String rsn = name.getText().replace('_', ' ').trim().replaceAll("\\s+", " ");
            if (rsn.isEmpty())
            {
                onResult.accept("Type their name first.");
                return;
            }
            if (Names.same(rsn, host))
            {
                onResult.accept("That's you — you're already in.");
                return;
            }
            Role role = roles == null ? null : (Role) roles.getSelectedItem();
            board.run(() -> api.addMember(partyId, rsn, role),
                "Couldn't add member. Refresh and check the name and available role.", message -> SwingUtilities.invokeLater(() -> {
                    if (message == null) name.setText("");
                    onResult.accept(message);
                }));
        };
        // A rebuilt row reuses the field: drop the old row's Enter handler.
        for (ActionListener old : name.getActionListeners()) name.removeActionListener(old);
        name.addActionListener(e -> submit.run());
        panel.add(Theme.button("Add member", Btn.Kind.GHOST, submit));
        return panel;
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.clan.ClanContent.Announcement;
import com.github.orgonag.fbclan.clan.ClanContent;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JTextArea;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;

/** Clan announcements, full text, newest first. Plain text: nothing to inject. */
@Singleton
public class AnnouncementsTab extends Tab
{
    // Remembers, in the local RuneLite config, the newest post this player has opened.
    // Its own group, kept apart from the plugin's settings.
    private static final String GROUP = "finalbossui";
    private static final String SEEN_KEY = "announcementSeen";

    private final ClanContent content;
    private final ConfigManager configManager;
    private String newest = "";
    private Runnable unreadListener = () -> {};

    @Inject
    public AnnouncementsTab(ClanContent content, ConfigManager configManager, ScheduledExecutorService executor)
    {
        super("Announcements", executor);
        this.content = content;
        this.configManager = configManager;
        render(content.announcements());
    }

    // EDT. True while the newest post hasn't been opened.
    boolean unread()
    {
        return !newest.isEmpty() && !newest.equals(configManager.getConfiguration(GROUP, SEEN_KEY));
    }

    // EDT. The tab was opened.
    void markRead()
    {
        if (!unread()) return;
        configManager.setConfiguration(GROUP, SEEN_KEY, newest);
        unreadListener.run();
    }

    void setUnreadListener(Runnable listener)
    {
        unreadListener = listener;
    }

    @Override
    public void refresh()
    {
        load(() -> {
            if (!content.refreshAnnouncements()) throw new IllegalStateException("Refresh unavailable");
            return content.announcements();
        }, this::render);
    }

    private void render(List<Announcement> items)
    {
        newest = items.isEmpty() ? "" : Integer.toHexString((items.get(0).getDate() + "|" + items.get(0).getTitle() + "|" + items.get(0).getBody()).hashCode());
        if (isShowing()) markRead();
        unreadListener.run();
        fill(() -> {
            if (items.isEmpty())
            {
                list.add(Theme.centered("No announcements yet."));
            }
            for (int i = 0; i < items.size(); i++)
            {
                Announcement a = items.get(i);
                // The clan's top entry (its own ordering) is outlined.
                Card card = Theme.card(i == 0 ? Theme.ACCENT : null);
                if (!a.getDate().isEmpty())
                {
                    card.add(Theme.text(a.getDate(), Theme.SUB));
                }
                if (!a.getTitle().isEmpty())
                {
                    JTextArea title = Theme.wrap(a.getTitle(), Theme.ACCENT_HI);
                    title.setFont(FontManager.getRunescapeBoldFont());
                    card.add(title);
                }
                if (!a.getBody().isEmpty())
                {
                    JTextArea body = Theme.wrap(a.getBody(), Theme.SOFT);
                    body.setFont(FontManager.getRunescapeFont());
                    card.add(body);
                }
                list.add(card);
            }
        });
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.lfg.Killcounts;
import com.github.orgonag.fbclan.lfg.Party;
import com.github.orgonag.fbclan.lfg.PartyApi;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import com.github.orgonag.fbclan.lfg.Role;
import java.text.ParseException;
import java.util.function.Consumer;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.SwingUtilities;

/**
 * The inline form under a party's card when the player applies: role,
 * learner, and KC. Your KC comes from your own client's record first, else
 * a hiscore lookup, else blank to type; editing it marks it self-reported.
 * The host sees it; it never blocks applying. The panel is kept across
 * re-renders (the board refreshes every 30s), and when it has to be
 * rebuilt (open roles changed, a KC lookup came back) what the player
 * already picked or typed is carried over.
 */
final class ApplyForm
{
    private final Clan clan;
    private final FinalBossConfig config;
    private final Killcounts killcounts;
    private final PartyBoard board;
    private final PartyApi api;
    private final Runnable render;
    // Null = applied (close the form); else the error to show.
    private final Consumer<String> onResult;
    private final Runnable onCancel;
    private JPanel panel;
    private String shape;
    // The current form's inputs (null where the activity has none), and the KC it was prefilled with.
    private String partyId;
    private JComboBox<Object> roleBox;
    private JCheckBox learnerBox;
    private JSpinner kcBox;
    private Integer kcPrefill;

    ApplyForm(Clan clan, FinalBossConfig config, Killcounts killcounts, PartyBoard board, PartyApi api,
              Runnable render, Consumer<String> onResult, Runnable onCancel)
    {
        this.clan = clan;
        this.config = config;
        this.killcounts = killcounts;
        this.board = board;
        this.api = api;
        this.render = render;
        this.onResult = onResult;
        this.onCancel = onCancel;
    }

    // EDT. Forget the cached form (logout).
    void reset()
    {
        panel = null;
        shape = null;
        partyId = null;
    }

    // EDT.
    JPanel view(Party p)
    {
        String rsn = clan.rsn();
        Integer prefill = null;
        Party.KcSource source = null;
        if (p.getActivity().hasKillcount())
        {
            prefill = killcounts.local(p.getActivity(), p.isHard());
            if (prefill != null)
            {
                source = Party.KcSource.LOCAL;
            }
            else if (rsn != null && config.lfgKcLookups())
            {
                Killcounts.Hiscore h = killcounts.cached(rsn, p.getActivity());
                if (h == null)
                {
                    killcounts.lookup(rsn, p.getActivity(), () -> SwingUtilities.invokeLater(render));
                }
                else if (h.known(p.isHard()))
                {
                    prefill = h.kc(p.isHard());
                    source = Party.KcSource.HISCORES;
                }
            }
        }
        String now = p.getId() + ":" + p.getActivity() + ":" + p.isHardMode() + ":" + p.openRoles() + ":" + p.getMinKc() + ":" + prefill + ":" + source;
        if (now.equals(shape) && panel != null) return panel;
        shape = now;
        // Same party, rebuilt: keep the role and learner picks, and a KC the player typed.
        boolean same = panel != null && p.getId().equals(partyId);
        Object role = same && roleBox != null ? roleBox.getSelectedItem() : null;
        boolean learner = same && learnerBox != null && learnerBox.isSelected();
        Integer typed = same ? typedKc() : null;
        partyId = p.getId();
        kcPrefill = prefill;
        panel = build(p, rsn, prefill, source, role, learner, typed);
        return panel;
    }

    // The KC in the box if the player changed it (including text still being typed), else null.
    private Integer typedKc()
    {
        if (kcBox == null) return null;
        try
        {
            kcBox.commitEdit();
        }
        catch (ParseException e)
        {
            return null;
        }
        Integer value = (Integer) kcBox.getValue();
        return value.equals(kcPrefill == null ? 0 : kcPrefill) ? null : value;
    }

    private JPanel build(Party p, String rsn, Integer prefill, Party.KcSource source, Object picked, boolean learner, Integer typed)
    {
        JPanel row = Theme.stack(4);
        roleBox = null;
        if (p.getActivity().hasRoles())
        {
            roleBox = LfgUi.combo(Role.applyOptions(p.getActivity(), p.isHardMode(), p.openRoles()).toArray());
            if (picked != null) roleBox.setSelectedItem(picked); // ignored when that role is no longer open
            row.add(Theme.labeled("Role", roleBox));
        }
        learnerBox = null;
        if (p.getActivity().isRaid())
        {
            learnerBox = LfgUi.checkbox("I'm a learner");
            learnerBox.setSelected(learner);
            row.add(learnerBox);
        }
        kcBox = null;
        if (p.getActivity().hasKillcount())
        {
            kcBox = new JSpinner(new SpinnerNumberModel(typed != null ? (int) typed : prefill == null ? 0 : prefill, 0, 100_000, 1));
            row.add(Theme.labeled(source == Party.KcSource.LOCAL ? "Your KC (auto)"
                : source == Party.KcSource.HISCORES ? "Your KC (hiscores)" : "Your KC", kcBox));
            if (p.getMinKc() > 0)
            {
                boolean below = prefill != null && prefill < p.getMinKc();
                row.add(Theme.text("Host asks for " + p.getMinKc() + "+ KC" + (below ? " - you're below it" : ""), below ? Theme.ACCENT_HI : Theme.SUB));
            }
        }
        JComboBox<Object> roles = roleBox;
        JCheckBox learners = learnerBox;
        JSpinner kcs = kcBox;
        Btn confirm = Theme.button("Confirm", Btn.Kind.PRIMARY, () -> {
            if (rsn == null) return;
            Role role = roles == null ? null : (Role) roles.getSelectedItem();
            boolean isLearner = learners != null && learners.isSelected();
            Integer kc = null;
            Party.KcSource kcSource = null;
            if (kcs != null)
            {
                try
                {
                    kcs.commitEdit();
                }
                catch (ParseException ex)
                {
                    onResult.accept("Enter a valid kill count.");
                    return;
                }
                int entered = (Integer) kcs.getValue();
                // Unchanged keeps where it came from; anything else typed is self-reported.
                if (prefill != null && entered == prefill)
                {
                    kc = entered;
                    kcSource = source;
                }
                else if (entered > 0)
                {
                    kc = entered;
                    kcSource = Party.KcSource.MANUAL;
                }
            }
            Integer kcF = kc;
            Party.KcSource kcSourceF = kcSource;
            board.run(() -> api.apply(p.getId(), role, isLearner, kcF, kcSourceF), "Couldn't apply. Refresh and try again.",
                message -> SwingUtilities.invokeLater(() -> onResult.accept(message)));
        });
        row.add(LfgUi.pair(confirm, Theme.button("Cancel", Btn.Kind.GHOST, onCancel)));
        return row;
    }
}

package com.github.orgonag.fbclan.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.KeyStroke;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.FontManager;

/**
 * The full leaderboard pop-out: pick a board, (for clan bests) a boss,
 * find a player; your own row is highlighted. One window, reused; it
 * re-renders whenever the tab's data refreshes.
 */
class BoardWindow
{
    private static final String NEWEST = "Newest clan bests";

    private final LeaderboardsTab tab;
    private JDialog dialog;
    private Choice<Integer> boards;
    private JComboBox<String> bossBox;
    private JTextField find;
    private JLabel heading;
    private JLabel caption;
    private JPanel rows;

    BoardWindow(LeaderboardsTab tab)
    {
        this.tab = tab;
    }

    // EDT.
    void open(int index, Component anchor)
    {
        if (dialog == null) build(anchor);
        boards.set(index);
        render();
        dialog.setVisible(true);
        dialog.toFront();
    }

    // EDT. Logout / shutdown.
    void close()
    {
        if (dialog != null) dialog.dispose();
    }

    // EDT. Fresh data arrived.
    void refresh()
    {
        if (dialog != null && dialog.isVisible()) render();
    }

    private void build(Component anchor)
    {
        boards = new Choice<>(Arrays.asList(0, 1, 2, 3, 4, 5), i -> LeaderboardsTab.SHORT[i], 0, i -> render());
        bossBox = new JComboBox<>();
        // Boss names come from the database: never let one render as HTML.
        DefaultListCellRenderer plain = new DefaultListCellRenderer();
        plain.putClientProperty("html.disable", Boolean.TRUE);
        bossBox.setRenderer(plain);
        bossBox.setFont(FontManager.getRunescapeSmallFont());
        bossBox.addActionListener(e -> renderRows());
        find = Theme.field("", 12);
        find.setToolTipText("Filter by player name");
        Theme.onEdit(find, this::renderRows);
        heading = Theme.heading("");
        caption = Theme.text("", Theme.FAINT);
        rows = Theme.stack(0);

        JPanel top = Theme.stack(8);
        top.setBorder(BorderFactory.createEmptyBorder(12, 14, 8, 14));
        top.add(boards);
        top.add(Theme.row(null, heading, Theme.labeled("Find", find)));
        top.add(bossBox);
        JPanel holder = new JPanel(new BorderLayout());
        holder.setBackground(Theme.SURFACE);
        holder.setBorder(BorderFactory.createEmptyBorder(4, 10, 4, 10));
        holder.add(rows, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(holder);
        scroll.setBorder(BorderFactory.createEmptyBorder(0, 14, 0, 14));
        scroll.getViewport().setBackground(Theme.BG);
        Theme.slim(scroll);
        caption.setBorder(BorderFactory.createEmptyBorder(8, 14, 10, 14));

        JPanel root = new JPanel(new BorderLayout());
        root.setBackground(Theme.BG);
        root.add(top, BorderLayout.NORTH);
        root.add(scroll, BorderLayout.CENTER);
        root.add(caption, BorderLayout.SOUTH);

        dialog = new JDialog(SwingUtilities.getWindowAncestor(anchor), "Final Boss · Leaderboards");
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.getRootPane().registerKeyboardAction(e -> close(), KeyStroke.getKeyStroke("ESCAPE"), JComponent.WHEN_IN_FOCUSED_WINDOW);
        dialog.addWindowListener(new WindowAdapter()
        {
            @Override
            public void windowClosed(WindowEvent e)
            {
                dialog = null;
            }
        });
        dialog.setContentPane(root);
        dialog.setSize(new Dimension(520, 560));
        dialog.setLocationRelativeTo(dialog.getOwner());
    }

    // Board changed or data refreshed: heading, boss list, then the rows.
    private void render()
    {
        int index = boards.value();
        heading.setText(LeaderboardsTab.TITLES[index]);
        boolean pbs = index == 4;
        bossBox.setVisible(pbs);
        if (pbs)
        {
            Object picked = bossBox.getSelectedItem();
            List<String> names = new ArrayList<>();
            names.add(NEWEST);
            names.addAll(tab.bosses().keySet());
            bossBox.removeAllItems();
            names.forEach(bossBox::addItem);
            bossBox.setSelectedItem(picked != null && names.contains(picked) ? picked : NEWEST);
        }
        renderRows();
    }

    private void renderRows()
    {
        int index = boards.value();
        String bossName = index == 4 ? (String) bossBox.getSelectedItem() : null;
        Map<String, String> bosses = tab.bosses();
        LeaderboardsTab.Board board = tab.board(index, bossName == null || NEWEST.equals(bossName) ? null : bosses.get(bossName));
        LeaderboardsTab.Row mine = tab.mine(board);
        String query = find.getText().trim().toLowerCase(Locale.ROOT);
        rows.removeAll();
        if (board.rows.isEmpty()) rows.add(Theme.centered(board.empty));
        int shown = 0;
        for (LeaderboardsTab.Row r : board.rows)
        {
            if (!query.isEmpty() && !r.name.toLowerCase(Locale.ROOT).contains(query)) continue;
            shown++;
            rows.add(line(r, r == mine));
        }
        if (!board.rows.isEmpty() && shown == 0) rows.add(Theme.centered("No player matches \"" + find.getText().trim() + "\"."));
        caption.setText(board.caption + " · " + board.rows.size() + (board.rows.size() == 1 ? " entry" : " entries"));
        rows.revalidate();
        rows.repaint();
    }

    private static JPanel line(LeaderboardsTab.Row r, boolean mine)
    {
        // Rank 0 = an unranked list (newest clan bests).
        JLabel rank = Theme.bold(r.rank > 0 ? Integer.toString(r.rank) : "\u2022", LeaderboardsTab.placeColor(r.rank));
        rank.setPreferredSize(new Dimension(28, 22));
        JPanel east = Theme.row(r.tier == null || r.tier.isEmpty() ? null : LeaderboardsTab.tierBadge(r.tier), null, Theme.bold(r.value, Theme.GOLD));
        JPanel row = Theme.row(rank, mine ? Theme.bold(r.name + "  (you)", Theme.TEXT) : Theme.text(r.name, Theme.SOFT), east);
        if (!mine) return row;
        Card highlight = new Card(Theme.ACCENT_BG, Theme.ACCENT);
        highlight.setBorder(BorderFactory.createEmptyBorder(1, 4, 1, 4));
        highlight.add(row);
        return highlight;
    }
}

package com.github.orgonag.fbclan.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import net.runelite.client.ui.FontManager;

/** A flat, self-painted button; CHIP and TAB kinds can be switched on. */
final class Btn extends JButton
{
    enum Kind { PRIMARY, GHOST, DANGER, CHIP, TAB }

    private static final Color DANGER_EDGE = new Color(0x5A2A2A);

    private final Kind kind;
    private boolean on;

    Btn(String text, Kind kind, Runnable action)
    {
        super(text);
        this.kind = kind;
        setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        setContentAreaFilled(false);
        setBorderPainted(false);
        setFocusPainted(false);
        setOpaque(false);
        setRolloverEnabled(true);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setBorder(BorderFactory.createEmptyBorder(5, 9, 5, 9));
        addActionListener(e -> action.run());
        restyle();
    }

    void setOn(boolean on)
    {
        this.on = on;
        restyle();
        repaint();
    }

    private boolean filled()
    {
        return kind == Kind.PRIMARY || (kind == Kind.CHIP && on);
    }

    private void restyle()
    {
        setForeground(filled() ? Theme.INK : kind == Kind.DANGER ? Theme.RED : kind == Kind.TAB && on ? Theme.ACCENT_HI : Theme.SOFT);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = Theme.smooth(g);
        int w = getWidth() - 1;
        int h = getHeight() - 1;
        int arc = kind == Kind.CHIP ? h : 6;
        boolean hover = isEnabled() && getModel().isRollover();
        Color fill = !isEnabled() ? Theme.RAISED
            : filled() ? (hover ? Theme.ACCENT_HI : Theme.ACCENT)
            : kind == Kind.TAB && on ? Theme.ACCENT_BG
            : hover ? Theme.RAISED : null;
        Color edge = filled() || !isEnabled() ? null
            : kind == Kind.DANGER ? DANGER_EDGE
            : kind == Kind.TAB && on ? Theme.ACCENT : Theme.LINE;
        if (fill != null)
        {
            g2.setColor(fill);
            g2.fillRoundRect(0, 0, w, h, arc, arc);
        }
        if (edge != null)
        {
            g2.setColor(edge);
            g2.setStroke(new BasicStroke(1f));
            g2.drawRoundRect(0, 0, w, h, arc, arc);
        }
        g2.dispose();
        super.paintComponent(g);
    }
}

