/** The last 50 clan drops: a top-drop highlight, filter chips, and item rows that open {@link DropViewer}. */
@Singleton
public class DropLogTab extends Tab
{
    private enum Filter
    {
        ALL("All"), MINE("Mine"), RARE("Rare+"), PETS("Pets");

        final String label;

        Filter(String label)
        {
            this.label = label;
        }
    }

    private final DropLogger drops;
    private final DropViewer viewer;
    private final ItemManager items;
    private final Clan clan;
    private List<Drop> rows = Collections.emptyList();
    private Filter filter = Filter.ALL;

    @Inject
    public DropLogTab(DropLogger drops, DropViewer viewer, ItemManager items, Clan clan, ScheduledExecutorService executor)
    {
        super("Drop Log", executor);
        this.drops = drops;
        this.viewer = viewer;
        this.items = items;
        this.clan = clan;
        control(new Choice<>(Arrays.asList(Filter.values()), f -> f.label, filter, f -> {
            filter = f;
            render();
        }));
    }

    @Override
    public void refresh()
    {
        load(() -> parse(drops.recent(50)), parsed -> {
            rows = parsed;
            render();
        });
    }

    public void closeViewer()
    {
        viewer.close();
    }

    private void render()
    {
        List<Drop> shown = new ArrayList<>();
        for (Drop d : rows)
        {
            if (matches(d)) shown.add(d);
        }
        Drop top = null;
        long dayGp = 0;
        int dayCount = 0;
        for (Drop d : shown)
        {
            if (Duration.between(d.at, Instant.now()).toHours() >= 24) continue;
            dayCount++;
            dayGp += d.value;
            if (d.value > 0 && (top == null || d.value > top.value)) top = d;
        }
        note.setText(dayCount == 0 ? "" : dayCount + " in 24h · " + Dashboard.shortNumber(dayGp));
        Drop best = top;
        fill(() -> {
            if (best != null) list.add(topCard(best));
            if (shown.isEmpty())
            {
                list.add(Theme.centered(rows.isEmpty() ? "No drops logged yet." : "No drops match this filter."));
            }
            for (Drop d : shown)
            {
                list.add(row(d));
            }
        });
    }

    private boolean matches(Drop d)
    {
        switch (filter)
        {
            case MINE: return clan.rsn() != null && Names.same(d.rsn, clan.rsn());
            case RARE: return d.tier() != Theme.Tier.COMMON;
            case PETS: return d.tier() == Theme.Tier.PET;
            default: return true;
        }
    }

    private JPanel topCard(Drop d)
    {
        Card card = Theme.card(Theme.ACCENT);
        card.add(Theme.row(Theme.badge("TOP DROP · 24H"), null, Theme.text(Theme.timeAgo(d.at), Theme.SUB)));
        JPanel text = Theme.stack(1);
        text.add(Theme.bold(d.name, Theme.TEXT));
        text.add(Theme.text(d.rsn + " · " + d.npc, Theme.SUB));
        JLabel value = Theme.bold(Dashboard.shortNumber(d.value) + (d.rarity > 0 ? "  " + DropRules.formatRarity(d.rarity) : ""), Theme.GOLD);
        text.add(value);
        card.add(Theme.row(Theme.tile(items, d.itemId(), d.quantity, d.tier(), 40), text, null));
        card.add(Theme.text(d.hasScreenshot() ? "Click to view the screenshot" : "Click for drop details", Theme.ACCENT_HI));
        return clickable(card, d);
    }

    private JPanel row(Drop d)
    {
        Card card = Theme.card(null);
        JPanel text = Theme.stack(1);
        text.add(Theme.bold(d.name, Theme.TEXT));
        text.add(Theme.text(d.rsn + " · " + Theme.timeAgo(d.at), Theme.SUB));
        text.add(Theme.text(d.npc, Theme.FAINT));
        JPanel east = Theme.stack(1);
        east.add(Theme.right(Theme.bold(d.value > 0 ? Dashboard.shortNumber(d.value) : d.tier() == Theme.Tier.PET ? "Pet" : "", Theme.GOLD)));
        east.add(Theme.right(Theme.text(d.rarity > 0 ? DropRules.formatRarity(d.rarity) : "", d.tier().edge)));
        JLabel pic = Theme.right(Theme.text(d.hasScreenshot() ? "pic" : "", Theme.ACCENT_HI));
        pic.setIcon(d.hasScreenshot() ? CAMERA : null);
        east.add(pic);
        card.add(Theme.row(Theme.tile(items, d.itemId(), d.quantity, d.tier(), 32), text, east));
        return clickable(card, d);
    }

    // The whole card opens the viewer. The tooltip carries the full,
    // possibly truncated, line and starts with fixed text so a remote
    // item name can never be read as tooltip HTML.
    private JPanel clickable(Card card, Drop d)
    {
        card.setToolTipText("Drop: " + d.summary());
        return Theme.onClick(card, () -> viewer.show(card, d));
    }

    private static List<Drop> parse(JsonArray array)
    {
        List<Drop> out = new ArrayList<>();
        for (JsonElement el : array)
        {
            out.add(new Drop(el.getAsJsonObject()));
        }
        return out;
    }

    /** One drops row, as the tab and the viewer need it. */
    static final class Drop
    {
        final String name;
        final String rsn;
        final String npc;
        final int id;
        final int quantity;
        final long value;
        final double rarity;
        final Instant at;
        final String screenshot;

        Drop(JsonObject row)
        {
            name = Supabase.str(row, "item_name");
            rsn = Supabase.str(row, "rsn");
            npc = Supabase.str(row, "npc_name");
            id = Supabase.intOr(row, "item_id", 0);
            quantity = Supabase.intOr(row, "quantity", 1);
            value = Supabase.longOr(row, "ge_value", 0);
            rarity = Supabase.doubleOr(row, "rarity", 0);
            // When it dropped; rows from before that was recorded only have the upload time.
            at = Supabase.instant(row, "occurred_at", Supabase.instant(row, "created_at", Instant.now()));
            // Drop rows are client-reported, so a screenshot link is only
            // honoured when it points into the plugin's own public bucket.
            String url = Supabase.str(row, "screenshot_url");
            screenshot = DropLogger.isScreenshot(url) ? url : "";
        }

        // "Item (1,234,567 GP) [1/512]" — the old one-line form.
        String summary()
        {
            return name + (value > 0 ? " (" + DropRules.formatGp(value) + " GP)" : "")
                + (rarity > 0 ? " [" + DropRules.formatRarity(rarity) + "]" : "");
        }

        boolean hasScreenshot()
        {
            return !screenshot.isEmpty();
        }

        // Follower pets carry no item id; show a stand-in pet sprite.
        int itemId()
        {
            return id > 0 ? id : ItemID.SNAKEPET;
        }

        Theme.Tier tier()
        {
            if (value == 0 && name.startsWith("Pet")) return Theme.Tier.PET;
            if ((rarity > 0 && rarity <= 0.001) || value >= 100_000_000L) return Theme.Tier.MEGA;
            if ((rarity > 0 && rarity <= 0.01) || value >= 10_000_000L) return Theme.Tier.RARE;
            return Theme.Tier.COMMON;
        }
    }

    // A tiny camera, drawn so it needs no asset or font glyph.
    private static final Icon CAMERA = new Icon()
    {
        @Override
        public void paintIcon(Component c, Graphics g, int x, int y)
        {
            Graphics2D g2 = Theme.smooth(g);
            g2.setColor(Theme.ACCENT_HI);
            g2.fillRoundRect(x, y + 2, 11, 8, 3, 3);
            g2.fillRect(x + 3, y, 5, 3);
            g2.setColor(new Color(0x1A1A1A));
            g2.fillOval(x + 3, y + 3, 5, 5);
            g2.dispose();
        }

        @Override
        public int getIconWidth()
        {
            return 11;
        }

        @Override
        public int getIconHeight()
        {
            return 10;
        }
    };
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.drops.DropLogger;
import com.github.orgonag.fbclan.drops.DropRules;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Iterator;
import java.util.concurrent.ScheduledExecutorService;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import javax.imageio.stream.MemoryCacheImageInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.KeyStroke;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.LinkBrowser;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * A pop-out for one drop: its details and, when it has one, the
 * screenshot scaled to fit. One window, reused; the image is fetched,
 * size-checked, decoded and scaled off the EDT.
 */
@Singleton
public class DropViewer
{
    private static final int MAX_BYTES = 8 * 1024 * 1024;
    private static final int MAX_SIDE = 8192;
    private static final long MAX_PIXELS = 24_000_000; // a 6K frame; ~96 MB decoded
    private static final int FIT_W = 760;
    private static final int FIT_H = 460;

    private final OkHttpClient http;
    private final ScheduledExecutorService executor;
    private final ItemManager items;
    private JDialog dialog;
    private String showing;

    @Inject
    public DropViewer(OkHttpClient http, ScheduledExecutorService executor, ItemManager items)
    {
        this.http = http;
        this.executor = executor;
        this.items = items;
    }

    // EDT. `anchor` is what was clicked; its window owns the dialog.
    void show(Component anchor, DropLogTab.Drop d)
    {
        boolean fresh = dialog == null;
        if (fresh)
        {
            dialog = new JDialog(SwingUtilities.getWindowAncestor(anchor));
            dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
            dialog.getRootPane().registerKeyboardAction(e -> close(), KeyStroke.getKeyStroke("ESCAPE"), JComponent.WHEN_IN_FOCUSED_WINDOW);
            dialog.addWindowListener(new WindowAdapter()
            {
                @Override
                public void windowClosed(WindowEvent e)
                {
                    dialog = null;
                    showing = null;
                }
            });
        }
        dialog.setTitle("Final Boss · Drop");
        showing = d.screenshot;

        JPanel header = Theme.stack(1);
        header.add(Theme.bold(d.name + (d.quantity > 1 ? " x " + d.quantity : ""), Theme.TEXT));
        header.add(Theme.text(d.rsn + " · " + d.npc + " · " + Theme.timeAgo(d.at), Theme.SUB));
        JPanel value = Theme.stack(1);
        value.add(Theme.right(Theme.bold(d.value > 0 ? DropRules.formatGp(d.value) + " GP" : "", Theme.GOLD)));
        value.add(Theme.right(Theme.text(d.rarity > 0 ? DropRules.formatRarity(d.rarity) : "", d.tier().edge)));

        JLabel image = Theme.text(d.hasScreenshot() ? "Loading screenshot..." : "No screenshot for this drop.", Theme.SUB);
        image.setHorizontalAlignment(SwingConstants.CENTER);
        Card frame = new Card(Theme.SURFACE, Theme.LINE);
        frame.setLayout(new BorderLayout());
        frame.add(image, BorderLayout.CENTER);
        frame.setPreferredSize(new Dimension(FIT_W + 16, (d.hasScreenshot() ? FIT_H : 60) + 16));

        JPanel body = Theme.stack(10);
        body.setBorder(BorderFactory.createEmptyBorder(12, 12, 12, 12));
        body.add(Theme.row(Theme.tile(items, d.itemId(), d.quantity, d.tier(), 40), header, value));
        body.add(frame);
        if (d.hasScreenshot())
        {
            body.add(Theme.row(null, null, Theme.button("Open in browser", Btn.Kind.GHOST, () -> LinkBrowser.browse(d.screenshot))));
            load(d.screenshot, image);
        }
        JPanel root = new JPanel(new BorderLayout());
        root.setBackground(Theme.BG);
        root.add(body, BorderLayout.NORTH);
        dialog.setContentPane(root);
        dialog.pack();
        // Centre once; later drops keep wherever the user moved it.
        if (fresh) dialog.setLocationRelativeTo(dialog.getOwner());
        dialog.setVisible(true);
        dialog.toFront();
    }

    // EDT. Plugin shutdown / logout.
    void close()
    {
        if (dialog != null) dialog.dispose();
    }

    private void load(String url, JLabel target)
    {
        Theme.async(executor, () -> fetch(url), img -> {
            if (!url.equals(showing)) return;
            target.setText(img == null ? "Screenshot unavailable — try Open in browser." : null);
            target.setIcon(img == null ? null : new ImageIcon(img));
        }, message -> { if (message != null && url.equals(showing)) target.setText("Screenshot unavailable — try Open in browser."); });
    }

    // Executor. The URL is checked again here: only the plugin's own bucket.
    private BufferedImage fetch(String url)
    {
        if (!DropLogger.isScreenshot(url))
        {
            return null;
        }
        try (Response response = http.newCall(new Request.Builder().url(url).build()).execute())
        {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null || body.contentLength() > MAX_BYTES) return null;
            byte[] bytes = readCapped(body.byteStream());
            BufferedImage img = bytes == null ? null : decode(bytes);
            if (img == null) return null;
            double scale = Math.min(1.0, Math.min((double) FIT_W / img.getWidth(), (double) FIT_H / img.getHeight()));
            return scale >= 1.0 ? img : ImageUtil.resizeImage(img, (int) (img.getWidth() * scale), (int) (img.getHeight() * scale), true);
        }
        catch (IOException e)
        {
            return null;
        }
    }

    private static byte[] readCapped(InputStream in) throws IOException
    {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buf = new byte[16384];
        for (int n; (n = in.read(buf)) != -1; )
        {
            out.write(buf, 0, n);
            if (out.size() > MAX_BYTES) return null;
        }
        return out.toByteArray();
    }

    // Reads the header first so a small file can't claim a huge canvas.
    private static BufferedImage decode(byte[] bytes) throws IOException
    {
        // Memory-backed: ImageIO.createImageInputStream may spool to a temp file on disk.
        try (ImageInputStream in = new MemoryCacheImageInputStream(new ByteArrayInputStream(bytes)))
        {
            Iterator<ImageReader> readers = ImageIO.getImageReaders(in);
            if (!readers.hasNext()) return null;
            ImageReader reader = readers.next();
            try
            {
                reader.setInput(in);
                int w = reader.getWidth(0);
                int h = reader.getHeight(0);
                if (w > MAX_SIDE || h > MAX_SIDE || (long) w * h > MAX_PIXELS) return null;
                return reader.read(0);
            }
            finally
            {
                reader.dispose();
            }
        }
    }
}

