/**
 * Host (or edit) a party in three steps: activity, requirements,
 * details. Everything in step 2 depends on the activity, size and mode,
 * so steps are rebuilt on change; widget values survive the rebuild.
 */
class HostWizard
{
    private static final String[] STEPS = {"Activity", "Requirements", "Details"};
    private static final List<String> RUN_TYPES = Arrays.asList("Normal", "Learner", "Teacher");
    private final Killcounts killcounts;
    private final boolean editing;
    private final String editingId;
    private final WhenPicker when;
    private final Function<Party, JComponent> preview;
    private final Consumer<HostWizard> onSubmit;
    private final JDialog dialog;

    private final JComboBox<Object> activityBox = LfgUi.combo(Activity.values());
    private final JCheckBox hardModeBox = LfgUi.checkbox("Hard mode");
    private final JSpinner invocationSpinner = spinner(150, 0, Party.MAX_INVOCATION, 5);
    private final JSpinner sizeSpinner = spinner(5, Party.MIN_CAPACITY, Party.MAX_CAPACITY, 1);
    private final Choice<LootRule> loot = new Choice<>(Arrays.asList(LootRule.values()),
        r -> r == LootRule.UNSPECIFIED ? "Any" : r.getDisplayName(), LootRule.UNSPECIFIED, r -> {});
    private final JSpinner minKcSpinner = spinner(0, 0, 100_000, 10);
    private final Choice<String> runType = new Choice<>(RUN_TYPES, s -> s, "Normal", s -> {});
    private final JComboBox<Object> hostRoleBox = new JComboBox<>();
    private final Map<Role, JSpinner> coxCounts = new EnumMap<>(Role.class);
    private final JTextField descField = Theme.field("", Party.MAX_DESCRIPTION);
    private final JLabel descCount = Theme.right(Theme.text("", Theme.FAINT));
    private final JLabel worldLabel = Theme.text("", Theme.SOFT);

    private final JLabel heading = Theme.heading("");
    private final JPanel stepBody = Theme.stack(10);
    private final JTextArea error = Theme.wrap("", Theme.RED);
    private final Btn back = Theme.button("Back", Btn.Kind.GHOST, this::back);
    private final Btn details = Theme.button("Next (details)", Btn.Kind.GHOST, this::next);
    private final Btn quick = Theme.button("Post now", Btn.Kind.PRIMARY, this::submit);
    private final Btn next = Theme.button("Next", Btn.Kind.PRIMARY, this::next);
    private int step;
    private int world;
    private boolean busy;
    private boolean rebuilding;

    // `editing` = the party to edit, or null to host a new one.
    HostWizard(Window owner, Killcounts killcounts, Party editing, WhenPicker.Limits limits, Function<Party, JComponent> preview, Consumer<HostWizard> onSubmit)
    {
        this.killcounts = killcounts;
        this.editing = editing != null;
        this.editingId = editing == null ? null : editing.getId();
        this.preview = preview;
        this.onSubmit = onSubmit;
        this.when = new WhenPicker(editing, limits);

        // Only the activity changes what step 1 shows; later steps rebuild on
        // entry. A new post starts at the activity's usual party size.
        activityBox.addActionListener(e -> {
            if (editingId == null && !rebuilding) sizeSpinner.setValue(activity().defaultPartySize());
            rebuild();
        });
        if (editingId == null) sizeSpinner.setValue(activity().defaultPartySize());
        descField.setToolTipText("Optional description (max " + Party.MAX_DESCRIPTION + " chars)");
        Theme.onEdit(descField, this::described);
        if (editing != null) populate(editing);

        JPanel top = Theme.stack(8);
        top.setBorder(BorderFactory.createEmptyBorder(12, 14, 6, 14));
        top.add(heading);
        top.add(new Progress());
        stepBody.setBorder(BorderFactory.createEmptyBorder(4, 14, 8, 14));
        // Tracks the window width, so a long description can't widen the step.
        Theme.Viewport bodyHolder = new Theme.Viewport();
        bodyHolder.setBorder(null);
        bodyHolder.add(stepBody, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(bodyHolder);
        scroll.setBorder(null);
        Theme.slim(scroll);
        JPanel footer = Theme.stack(6);
        footer.setBorder(BorderFactory.createEmptyBorder(8, 14, 12, 14));
        error.setVisible(false);
        footer.add(error);
        JPanel forward = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        forward.setOpaque(false);
        forward.add(details);
        forward.add(quick);
        forward.add(next);
        footer.add(Theme.row(back, null, forward));

        JPanel root = new JPanel(new BorderLayout());
        root.setBackground(Theme.BG);
        root.add(top, BorderLayout.NORTH);
        root.add(scroll, BorderLayout.CENTER);
        root.add(footer, BorderLayout.SOUTH);

        dialog = new JDialog(owner, this.editing ? "Final Boss · Edit your party" : "Final Boss · Host a party");
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.getRootPane().registerKeyboardAction(e -> close(), KeyStroke.getKeyStroke("ESCAPE"), JComponent.WHEN_IN_FOCUSED_WINDOW);
        dialog.setContentPane(root);
        dialog.setSize(new Dimension(360, 500));
        dialog.setLocationRelativeTo(owner);
        show(0);
        dialog.setVisible(true);
    }

    // ------------------------------------------------------------ outside

    boolean isOpen()
    {
        return dialog.isDisplayable();
    }

    // The id of the post being edited, else null.
    String editingId()
    {
        return editingId;
    }

    void focus()
    {
        dialog.toFront();
    }

    void close()
    {
        dialog.dispose();
    }

    void showError(String message)
    {
        error.setText(message == null ? "" : message);
        error.setVisible(message != null);
        setBusy(busy);
        error.getParent().revalidate();
    }

    void setBusy(boolean busy)
    {
        this.busy = busy;
        next.setEnabled(!busy);
        quick.setEnabled(!busy);
    }

    void setWorld(int world)
    {
        this.world = world;
        worldLabel.setText(world > 0 ? "W" + world + " (your current world)" : "Unknown — log in to a world");
    }

    // The party the form describes; id/created_at are server-owned.
    Party build(String hostRsn, int world)
    {
        try
        {
            sizeSpinner.commitEdit();
            invocationSpinner.commitEdit();
            minKcSpinner.commitEdit();
            for (JSpinner s : coxCounts.values()) s.commitEdit();
        }
        catch (ParseException e)
        {
            throw new IllegalArgumentException("Enter valid numeric values.");
        }
        Activity activity = activity();
        boolean hard = activity.hasHardMode() && hardModeBox.isSelected();
        int capacity = (Integer) sizeSpinner.getValue();
        // A quick post skips step 2, so pick a valid default role here.
        if (activity.hasRoles()) syncRoles(activity, capacity, hard);
        Map<Role, Integer> counts = new EnumMap<>(Role.class);
        coxCounts.forEach((r, s) -> counts.put(r, (Integer) s.getValue()));
        Party party = Party.builder()
            .hostRsn(hostRsn)
            .activity(activity)
            .hardMode(hard)
            .invocation(activity.usesInvocation() ? (Integer) invocationSpinner.getValue() : 0)
            .capacity(capacity)
            .description(descField.getText())
            .world(world > 0 ? world : null)
            .minKc(activity.hasKillcount() ? (Integer) minKcSpinner.getValue() : 0)
            .lootRule(loot.value())
            .requiredRoles(Role.required(activity, hard, capacity, counts))
            .hostRole(activity.hasRoles() ? (Role) hostRoleBox.getSelectedItem() : null)
            .learner(activity.isRaid() && "Learner".equals(runType.value()))
            .teacher(activity.isRaid() && "Teacher".equals(runType.value()))
            .createdAt(Instant.now())
            .scheduledFor(when.start())
            .applicants(Collections.emptyList())
            .build();
        if (activity.hasRoles() && party.openRoles().isEmpty())
        {
            throw new IllegalArgumentException("Your role has no seat. Lower a role count or pick another role.");
        }
        return party;
    }

    // ------------------------------------------------------------ steps

    private void back()
    {
        show(step - 1);
    }

    // Post (or save) with whatever is set; untouched steps keep their defaults.
    private void submit()
    {
        onSubmit.accept(this);
    }

    private void next()
    {
        if (step == STEPS.length - 1)
        {
            submit();
            return;
        }
        if (step == 1)
        {
            // Validate before the preview needs a whole party.
            try
            {
                build("You", 0);
            }
            catch (IllegalArgumentException e)
            {
                showError(e.getMessage());
                return;
            }
        }
        show(step + 1);
    }

    private void show(int index)
    {
        step = index;
        showError(null);
        heading.setText(new String[]{"Pick an activity", "Set requirements", "Final details"}[step]);
        back.setVisible(step > 0);
        details.setVisible(step == 0);
        quick.setVisible(step == 0);
        quick.setText(editing ? "Save now" : "Post now");
        next.setVisible(step > 0);
        next.setText(step < STEPS.length - 1 ? "Next" : editing ? "Save changes" : "Post party");
        rebuild();
        dialog.repaint();
    }

    // Listeners on the widgets adjusted here call back in; the guard stops
    // the nested call from re-adding rows mid-rebuild.
    private void rebuild()
    {
        if (rebuilding) return;
        rebuilding = true;
        try
        {
            // Changing the activity rebuilds step 1 around its own combo; keep keyboard focus on it.
            boolean comboFocused = activityBox.isFocusOwner();
            stepBody.removeAll();
            Activity activity = activity();
            int size = clampSize(activity);
            if (step == 0) activityStep(activity);
            else if (step == 1) requirementsStep(activity, size);
            else detailsStep();
            stepBody.revalidate();
            stepBody.repaint();
            if (comboFocused) activityBox.requestFocusInWindow();
        }
        finally
        {
            rebuilding = false;
        }
    }

    private void activityStep(Activity activity)
    {
        stepBody.add(Theme.text("What are you running?", Theme.SUB));
        stepBody.add(activityBox);
        if (activity.hasHardMode())
        {
            hardModeBox.setText(activity == Activity.TOB ? "Hard mode (HMT)"
                : activity == Activity.COX ? "Challenge mode (CM)" : activity.getHardModeLabel());
            stepBody.add(hardModeBox);
        }
        else
        {
            hardModeBox.setSelected(false);
        }
        if (activity.usesInvocation()) stepBody.add(Theme.labeled("Invocation", invocationSpinner));
        stepBody.add(Theme.labeled("Party size", sizeSpinner));
        stepBody.add(when);
        when.summarize();
    }

    private void requirementsStep(Activity activity, int size)
    {
        stepBody.add(Theme.text("Loot", Theme.SUB));
        stepBody.add(loot);
        if (activity.hasKillcount())
        {
            stepBody.add(Theme.labeled("Min KC (0=any)", minKcSpinner));
            Integer mine = killcounts.local(activity, (activity.hasHardMode() && hardModeBox.isSelected())
                || (activity.usesInvocation() && (Integer) invocationSpinner.getValue() >= 300));
            if (mine != null) stepBody.add(Theme.text("Your KC: " + mine, Theme.SUB));
        }
        else
        {
            minKcSpinner.setValue(0);
        }
        if (activity.isRaid())
        {
            stepBody.add(Theme.text("Run type", Theme.SUB));
            stepBody.add(runType);
        }
        else
        {
            runType.set("Normal");
        }
        if (!activity.hasRoles())
        {
            hostRoleBox.removeAllItems();
            return;
        }
        boolean hard = hardModeBox.isSelected();
        syncRoles(activity, size, hard);
        stepBody.add(Theme.labeled("Your role", hostRoleBox));
        if (activity == Activity.TOB)
        {
            stepBody.add(Theme.wrap("Team: " + Role.summarize(Role.tobComposition(size, hard)), Theme.SUB));
        }
        else if (activity == Activity.COX)
        {
            stepBody.add(Theme.text("Roles wanted (rest = Fill):", Theme.SUB));
            Map<Role, Integer> keep = new EnumMap<>(Role.class);
            coxCounts.forEach((r, s) -> keep.put(r, (Integer) s.getValue()));
            coxCounts.clear();
            int max = (Integer) ((SpinnerNumberModel) sizeSpinner.getModel()).getMaximum();
            for (Role r : Role.playable(activity, hard))
            {
                if (r.isFill()) continue;
                JSpinner s = spinner(keep.getOrDefault(r, 0), 0, max, 1);
                coxCounts.put(r, s);
                stepBody.add(Theme.labeled("  " + r.getDisplayName(), s));
            }
        }
        else
        {
            stepBody.add(Theme.text("One of each role; a 5th may double up.", Theme.SUB));
        }
    }

    private void detailsStep()
    {
        stepBody.add(Theme.text("Description (optional)", Theme.SUB));
        stepBody.add(descField);
        stepBody.add(descCount);
        stepBody.add(Theme.labeled("World", worldLabel));
        stepBody.add(Theme.text("Preview", Theme.SUB));
        stepBody.add(previewCard());
        described();
    }

    // Live counter, and the preview follows the text.
    private void described()
    {
        descCount.setText(descField.getText().length() + " / " + Party.MAX_DESCRIPTION);
        if (step == 2 && stepBody.getComponentCount() > 0)
        {
            stepBody.remove(stepBody.getComponentCount() - 1);
            stepBody.add(previewCard());
            stepBody.revalidate();
            stepBody.repaint();
        }
    }

    private JComponent previewCard()
    {
        try
        {
            return preview.apply(build("You", world));
        }
        catch (IllegalArgumentException e)
        {
            return Theme.text(e.getMessage(), Theme.RED);
        }
    }

    // Fill from an existing party (Edit).
    private void populate(Party p)
    {
        activityBox.setSelectedItem(p.getActivity());
        hardModeBox.setSelected(p.isHardMode());
        invocationSpinner.setValue(p.getInvocation());
        clampSize(p.getActivity());
        SpinnerNumberModel m = (SpinnerNumberModel) sizeSpinner.getModel();
        sizeSpinner.setValue(Math.max((Integer) m.getMinimum(), Math.min((Integer) m.getMaximum(), p.getCapacity())));
        loot.set(p.getLootRule());
        minKcSpinner.setValue(p.getMinKc());
        runType.set(p.isLearner() ? "Learner" : p.isTeacher() ? "Teacher" : "Normal");
        descField.setText(p.getDescription() == null ? "" : p.getDescription());
        if (p.getHostRole() != null)
        {
            hostRoleBox.addItem(p.getHostRole());
            hostRoleBox.setSelectedItem(p.getHostRole());
        }
        if (p.getActivity() == Activity.COX)
        {
            for (Role r : p.getRequiredRoles())
            {
                JSpinner s = coxCounts.computeIfAbsent(r, k -> spinner(0, 0, Party.MAX_CAPACITY, 1));
                s.setValue((Integer) s.getValue() + 1);
            }
        }
    }

    // ------------------------------------------------------------ helpers

    // The host-role choices for this activity, size and mode. Keeps the
    // current pick while it is still valid; otherwise "any role" (the host
    // takes whatever seat is left), the same as a `!lfg` post.
    private void syncRoles(Activity activity, int size, boolean hard)
    {
        Object previous = hostRoleBox.getSelectedItem();
        hostRoleBox.removeAllItems();
        List<Role> roles = new ArrayList<>(activity == Activity.TOB ? distinct(Role.tobComposition(size, hard)) : Role.playable(activity, hard));
        Role any = Role.any(activity, hard);
        if (!roles.contains(any)) roles.add(any);
        roles.forEach(hostRoleBox::addItem);
        hostRoleBox.setSelectedItem(roles.contains(previous) ? previous : any);
    }

    private Activity activity()
    {
        return (Activity) activityBox.getSelectedItem();
    }

    // Party size limits follow the activity; returns the clamped size.
    private int clampSize(Activity activity)
    {
        int min = Math.max(Party.MIN_CAPACITY, activity.getMinPartySize());
        int max = Math.max(min, activity.getMaxPartySize());
        SpinnerNumberModel model = (SpinnerNumberModel) sizeSpinner.getModel();
        int size = Math.max(min, Math.min(max, (Integer) sizeSpinner.getValue()));
        model.setMinimum(min);
        model.setMaximum(max);
        if ((Integer) sizeSpinner.getValue() != size) sizeSpinner.setValue(size);
        return size;
    }

    private static JSpinner spinner(int value, int min, int max, int step)
    {
        return new JSpinner(new SpinnerNumberModel(Math.max(min, Math.min(max, value)), min, max, step));
    }

    private static List<Role> distinct(List<Role> roles)
    {
        List<Role> out = new ArrayList<>();
        for (Role r : roles)
        {
            if (!out.contains(r)) out.add(r);
        }
        return out;
    }

    // Three segments, filled up to the current step, with their names.
    private final class Progress extends JComponent
    {
        Progress()
        {
            setPreferredSize(new Dimension(10, 20));
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = Theme.smooth(g);
            int seg = (getWidth() - 8) / 3;
            g2.setFont(FontManager.getRunescapeSmallFont());
            for (int i = 0; i < STEPS.length; i++)
            {
                int x = i * (seg + 4);
                g2.setColor(i <= step ? Theme.ACCENT : Theme.LINE);
                g2.fillRoundRect(x, 0, seg, 4, 4, 4);
                g2.setColor(i == step ? Theme.ACCENT_HI : i < step ? Theme.SOFT : Theme.FAINT);
                g2.drawString(STEPS[i].toUpperCase(Locale.ROOT), x, 17);
            }
            g2.dispose();
        }
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.pbs.Leaderboards.Entry;
import com.github.orgonag.fbclan.pbs.Leaderboards;
import com.github.orgonag.fbclan.pbs.PbFormat;
import com.github.orgonag.fbclan.stats.Dashboard.Named;
import com.github.orgonag.fbclan.stats.Dashboard;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.DoubleFunction;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * The clan dashboard as six highlight cards (weekly XP and EHB from Wise
 * Old Man, collection log, combat achievements, clan bests, GP this
 * week): top three and your own rank. A card opens the full board in
 * {@link BoardWindow}.
 */
@Singleton
public class LeaderboardsTab extends Tab
{
    static final String[] TITLES = {
        "XP Gained This Week", "EHB This Week", "Collection Log", "Combat Achievements", "Clan Bests", "GP This Week",
    };
    static final String[] SHORT = {"XP week", "EHB week", "Col log", "Combat ach.", "PBs", "GP week"};
    static final Color[] PLACE = {new Color(0xFFD700), new Color(0xC8C8C8), new Color(0xCD7F32)};

    /** One ranked line. `tier` is the CA tier, else null. */
    static final class Row
    {
        final int rank;
        final String rsn;
        final String name;
        final String value;
        final String tier;

        Row(int rank, String rsn, String name, String value, String tier)
        {
            this.rank = rank;
            this.rsn = rsn;
            this.name = name;
            this.value = value;
            this.tier = tier;
        }
    }

    /** A whole board: its rows, the line shown when there are none, and a source caption. */
    static final class Board
    {
        final List<Row> rows;
        final String empty;
        final String caption;

        Board(List<Row> rows, String empty, String caption)
        {
            this.rows = rows;
            this.empty = empty;
            this.caption = caption;
        }
    }

    private final Leaderboards pbs;
    private final Dashboard dashboard;
    private final Clan clan;
    private final BoardWindow window;

    @Inject
    public LeaderboardsTab(Leaderboards pbs, Dashboard dashboard, Clan clan, ScheduledExecutorService executor)
    {
        super("Leaderboards", executor);
        this.pbs = pbs;
        this.dashboard = dashboard;
        this.clan = clan;
        this.window = new BoardWindow(this);
        render();
    }

    @Override
    public void refresh()
    {
        // Render whatever did update, even when one source failed.
        load(() -> pbs.refresh() & dashboard.refresh(), ok -> {
            render();
            if (!ok) showError("Refresh failed. Previous data may be out of date.");
        });
    }

    void closeWindow()
    {
        window.close();
    }

    private void render()
    {
        String at = dashboard.womSyncedAt();
        note.setText(at.isEmpty() ? "" : "synced " + Theme.timeAgo(at));
        fill(() -> {
            for (int i = 0; i < TITLES.length; i++)
            {
                list.add(card(i));
            }
        });
        window.refresh();
    }

    // Title, #1 large, #2 and #3 small, then your rank (or the clan total for GP).
    private JPanel card(int index)
    {
        Board b = board(index, null);
        Card card = Theme.card(null);
        card.add(Theme.row(null, Theme.caps(TITLES[index]), Theme.text("›", Theme.FAINT)));
        if (b.rows.isEmpty())
        {
            card.add(Theme.text(b.empty, Theme.SUB));
        }
        else
        {
            Row first = b.rows.get(0);
            JLabel name = Theme.bold(first.name, Theme.TEXT);
            name.setFont(FontManager.getRunescapeBoldFont());
            JLabel value = Theme.bold(first.value, Theme.GOLD);
            value.setFont(FontManager.getRunescapeBoldFont());
            // Clan bests are newest-first, not a ranking: no place numbers there.
            boolean ranked = index != 4;
            card.add(Theme.row(place(ranked, first.rank), name, value));
            JPanel runners = Theme.stack(1);
            for (int i = 1; i < Math.min(3, b.rows.size()); i++)
            {
                Row r = b.rows.get(i);
                runners.add(Theme.row(place(ranked, r.rank),
                    Theme.text(r.name, Theme.SOFT), Theme.text(r.value, Theme.GOLD)));
            }
            card.add(runners);
        }
        String foot = footer(index, b);
        if (foot != null) card.add(Theme.text(foot, Theme.ACCENT_HI));
        card.setToolTipText("Open the full " + TITLES[index] + " board");
        return Theme.onClick(card, () -> window.open(index, card));
    }

    // "You: #24 · 4.7M", the clan GP total, or the newest best's age.
    private String footer(int index, Board b)
    {
        if (index == 5)
        {
            Dashboard.GpWeek gp = dashboard.gpWeek();
            return "Clan: " + Dashboard.shortNumber(gp.getTotalGp()) + " GP · " + gp.getDropCount() + " drops";
        }
        if (index == 4)
        {
            return pbs.recent().isEmpty() ? null : "Newest " + Theme.timeAgo(pbs.recent().get(0).getAchievedAt());
        }
        Row mine = mine(b);
        return mine == null ? null : "You: #" + mine.rank + " · " + mine.value;
    }

    Row mine(Board b)
    {
        String rsn = clan.rsn();
        for (Row r : b.rows)
        {
            if (rsn != null && r.rsn != null && Names.same(r.rsn, rsn)) return r;
        }
        return null;
    }

    // ------------------------------------------------------------ data

    // `boss` only matters for clan bests: null = the newest bests across bosses.
    Board board(int index, String boss)
    {
        String synced = dashboard.womSyncedAt().isEmpty() ? "" : " · synced " + Theme.timeAgo(dashboard.womSyncedAt());
        switch (index)
        {
            case 0:
                return named(dashboard.xpWeek(), v -> Dashboard.shortNumber((long) v), "via Wise Old Man" + synced);
            case 1:
                return named(dashboard.ehbWeek(), Dashboard::oneDecimal, "efficient hours bossed" + synced);
            case 2:
            {
                List<Row> rows = new ArrayList<>();
                Ranker rank = new Ranker();
                for (Dashboard.ClEntry e : dashboard.clBoard())
                {
                    rows.add(new Row(rank.of(e.getObtained()), e.getRsn(), e.getRsn(), String.format("%,d/%,d", e.getObtained(), e.getTotal()), null));
                }
                return new Board(rows, "No collection logs uploaded yet.", "uploaded by members' clients");
            }
            case 3:
            {
                List<Row> rows = new ArrayList<>();
                Ranker rank = new Ranker();
                for (Dashboard.CaEntry e : dashboard.caBoard())
                {
                    rows.add(new Row(rank.of(e.getPoints()), e.getRsn(), e.getRsn(), String.format("%,d", e.getPoints()), e.getTier()));
                }
                return new Board(rows, "No combat achievements uploaded yet.", "uploaded by members' clients");
            }
            case 4:
            {
                List<Row> rows = new ArrayList<>();
                if (boss == null)
                {
                    for (Entry e : pbs.recent())
                    {
                        rows.add(new Row(0, e.getRsn(), PbFormat.boss(e.getBossKey()) + " · " + e.getRsn(),
                            PbFormat.seconds(e.getSeconds()), null));
                    }
                    return new Board(rows, "No new clan bests yet.", "newest first");
                }
                Ranker rank = new Ranker();
                for (Entry e : pbs.board())
                {
                    if (e.getBossKey().equals(boss))
                    {
                        rows.add(new Row(rank.of(e.getSeconds()), e.getRsn(), e.getRsn(), PbFormat.seconds(e.getSeconds()), null));
                    }
                }
                return new Board(rows, "No personal bests recorded yet.", "all-time");
            }
            default:
            {
                Dashboard.GpWeek gp = dashboard.gpWeek();
                Board b = named(gp.getTop(), v -> Dashboard.shortNumber((long) v), "logged drops (1M+/notables) · last 7 days");
                return new Board(b.rows, "No logged drops in the last 7 days.", b.caption);
            }
        }
    }

    // All-time PB bosses, display name -> key, sorted by name.
    Map<String, String> bosses()
    {
        Map<String, String> out = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        for (Entry e : pbs.board())
        {
            out.put(PbFormat.boss(e.getBossKey()), e.getBossKey());
        }
        return out;
    }

    private static Board named(List<Named> entries, DoubleFunction<String> fmt, String caption)
    {
        if (entries == null) return new Board(Collections.emptyList(), "waiting for WOM sync", caption);
        List<Row> rows = new ArrayList<>();
        Ranker rank = new Ranker();
        for (Named e : entries)
        {
            rows.add(new Row(rank.of(e.getValue()), e.getRsn(), e.getRsn(), fmt.apply(e.getValue()), null));
        }
        return new Board(rows, "No data this week.", caption);
    }

    // Gold, silver, bronze for places 1-3; grey after.
    static Color placeColor(int rank)
    {
        return rank >= 1 && rank <= 3 ? PLACE[rank - 1] : Theme.FAINT;
    }

    // A card's place label; clan bests are newest-first, not ranked, so they get a bullet.
    private static JLabel place(boolean ranked, int rank)
    {
        return ranked ? Theme.bold(Integer.toString(rank), placeColor(rank)) : Theme.bold("•", Theme.FAINT);
    }

    // Dense ranking: equal values share a place and the next value takes the
    // next place (1, 1, 1, 2, 2, ...). Rows arrive best first.
    private static final class Ranker
    {
        private Object last;
        private int rank;

        int of(Object value)
        {
            if (rank == 0 || !value.equals(last))
            {
                rank++;
                last = value;
            }
            return rank;
        }
    }

    // GM cyan, Master red, Elite gold, others grey.
    static JLabel tierBadge(String tier)
    {
        switch (tier)
        {
            case "Grandmaster": return Theme.bold("GM", new Color(0x7DF9FF));
            case "Master": return Theme.bold("MASTER", new Color(0xFF6B6B));
            case "Elite": return Theme.bold("ELITE", Theme.GOLD);
            default: return Theme.bold(tier.toUpperCase(Locale.ROOT), Theme.FAINT);
        }
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.lfg.Activity;
import com.github.orgonag.fbclan.lfg.Party;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import java.awt.Component;
import java.awt.GridLayout;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import javax.swing.BorderFactory;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/** Small LFG display pieces shared by the tab, the host window and the apply form. */
final class LfgUi
{
    private static final DateTimeFormatter HOUR_MINUTE = DateTimeFormatter.ofPattern("HH:mm");

    private LfgUi()
    {
    }

    // A scheduled post's time line: "Starts Today 20:00 · in 3h",
    // "Started 40m ago" during the grace period, then "Was Sat 20:00".
    // Null for ASAP posts.
    static JLabel start(Party p)
    {
        if (!p.isScheduled()) return null;
        Instant now = Instant.now();
        Instant at = p.getScheduledFor();
        if (now.isBefore(at))
        {
            return Theme.bold((p.isFull() ? "Full · starts " : "Starts ") + day(at) + " · in " + span(Duration.between(now, at)), Theme.ACCENT_HI);
        }
        if (now.isBefore(at.plus(Party.GRACE)))
        {
            return Theme.bold("Started " + Theme.timeAgo(at), Theme.GREEN);
        }
        return Theme.bold("Was " + day(at), Theme.ACCENT);
    }

    // "Today 20:00", "Tomorrow 09:30", else "Sat 20:00", in the player's zone.
    static String day(Instant at)
    {
        ZoneId zone = ZoneId.systemDefault();
        LocalDate date = at.atZone(zone).toLocalDate();
        LocalDate today = LocalDate.now(zone);
        String time = HOUR_MINUTE.withZone(zone).format(at);
        if (date.equals(today)) return "Today " + time;
        if (date.equals(today.plusDays(1))) return "Tomorrow " + time;
        return PartyBoard.when(at);
    }

    // "45m", "3h", "2d 4h".
    static String span(Duration d)
    {
        long minutes = Math.max(1, d.toMinutes());
        if (minutes < 60) return minutes + "m";
        long hours = minutes / 60;
        if (hours < 24) return hours + "h";
        return (hours / 24) + "d" + (hours % 24 == 0 ? "" : " " + (hours % 24) + "h");
    }

    // Tile colour per activity group.
    static Theme.Tier tier(Activity a)
    {
        switch (a.getCategory())
        {
            case RAIDS: return Theme.Tier.MEGA;
            case GOD_WARS: return Theme.Tier.RARE;
            case BOSSES: return Theme.Tier.PET;
            default: return Theme.Tier.COMMON;
        }
    }

    // A disabled button that says why ("Full", "No open roles").
    static void disable(Btn b, String reason)
    {
        b.setText(reason);
        b.setEnabled(false);
    }

    static Btn small(Btn b)
    {
        b.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 6));
        return b;
    }

    static JPanel pair(Component a, Component b)
    {
        JPanel p = new JPanel(new GridLayout(1, 2, 5, 0));
        p.setOpaque(false);
        p.add(a);
        p.add(b);
        return p;
    }

    static JCheckBox checkbox(String text)
    {
        JCheckBox box = new JCheckBox(text);
        box.setOpaque(false);
        box.setForeground(Theme.TEXT);
        box.setFont(FontManager.getRunescapeSmallFont());
        return box;
    }

    // Activities read "Category: Name"; categories read "All <category>".
    static JComboBox<Object> combo(Object[] values)
    {
        JComboBox<Object> box = new JComboBox<>(values);
        box.setFont(FontManager.getRunescapeSmallFont());
        box.setRenderer(new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus)
            {
                Object shown = value;
                if (value instanceof Activity)
                {
                    Activity a = (Activity) value;
                    shown = a.getCategory() == Activity.Category.GENERAL ? a.getDisplayName() : a.getCategory().getDisplayName() + ": " + a.getDisplayName();
                }
                else if (value instanceof Activity.Category)
                {
                    shown = "All " + ((Activity.Category) value).getDisplayName();
                }
                return super.getListCellRendererComponent(list, shown, index, selected, focus);
            }
        });
        return box;
    }
}

package com.github.orgonag.fbclan.ui;

