/**
 * The sidebar panel: a locked card until verification passes, then the
 * icon tab bar and the four tabs. One panel for the plugin's lifetime
 * (RuneLite fixes a navigation button's panel at build time), so
 * verification just flips the visible card.
 */
@Singleton
public class Sidebar extends PluginPanel
{
    private static final String LOCKED = "LOCKED";
    private static final String MAIN = "MAIN";

    private final CardLayout cards = new CardLayout();
    private final JPanel root = new JPanel(cards);
    private final JTextArea status = Theme.wrap("", Theme.SOFT);
    private final Btn retry;
    private final CardLayout tabCards = new CardLayout();
    private final JPanel tabs = new JPanel(tabCards);
    private final Map<String, Btn> tabButtons = new LinkedHashMap<>();
    private final Map<String, Tab> tabPanels = new LinkedHashMap<>();
    private final AnnouncementsTab announcements;
    private final DropLogTab dropLog;
    private final PartiesTab parties;
    private final LeaderboardsTab leaderboards;
    private String activeTab = "Drop Log";

    @Inject
    public Sidebar(Clan clan, AnnouncementsTab announcements, DropLogTab dropLog,
                   PartiesTab parties, LeaderboardsTab leaderboards)
    {
        super(false);
        this.announcements = announcements;
        this.dropLog = dropLog;
        this.parties = parties;
        this.leaderboards = leaderboards;
        setLayout(new BorderLayout());
        setBackground(Theme.BG);

        // ---- locked card ----
        JPanel locked = Theme.stack(12);
        locked.setBorder(BorderFactory.createEmptyBorder(24, 16, 16, 16));
        JLabel logo = new JLabel(new ImageIcon(ImageUtil.loadImageResource(FinalBossPlugin.class, "icon.png")));
        logo.setHorizontalAlignment(SwingConstants.CENTER);
        JLabel title = Theme.heading("Final Boss");
        title.setHorizontalAlignment(SwingConstants.CENTER);
        retry = Theme.button("Retry", Btn.Kind.PRIMARY, clan::verify);
        locked.add(logo);
        locked.add(title);
        locked.add(status);
        locked.add(retry);
        JPanel lockedHolder = new JPanel(new BorderLayout());
        lockedHolder.setBackground(Theme.BG);
        lockedHolder.add(locked, BorderLayout.NORTH);

        // ---- main card: bell + word tabs over the tabs ----
        Btn bell = tab("Announcements", "", announcements);
        bell.setIcon(new Bell(announcements));
        bell.setPreferredSize(new Dimension(40, 32));
        announcements.setUnreadListener(bell::repaint);
        JPanel words = new JPanel(new GridLayout(1, 3, 4, 0));
        words.setOpaque(false);
        words.add(tab("Drop Log", "Drops", dropLog));
        words.add(tab("Looking for Group", "LFG", parties));
        words.add(tab("Leaderboards", "PBs", leaderboards));
        JPanel bar = new JPanel(new BorderLayout(4, 0));
        bar.setBackground(Theme.SURFACE);
        bar.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
        bar.add(bell, BorderLayout.WEST);
        bar.add(words, BorderLayout.CENTER);
        tabs.setBackground(Theme.BG);
        JPanel main = new JPanel(new BorderLayout());
        main.setBackground(Theme.BG);
        main.add(bar, BorderLayout.NORTH);
        main.add(tabs, BorderLayout.CENTER);

        root.add(lockedHolder, LOCKED);
        root.add(main, MAIN);
        add(root, BorderLayout.CENTER);
        showLoggedOut();
        select(activeTab);
    }

    private Btn tab(String name, String label, Tab panel)
    {
        Btn b = Theme.button(label, Btn.Kind.TAB, () -> {
            select(name);
            panel.refresh();
        });
        b.setFont(FontManager.getRunescapeBoldFont());
        b.setToolTipText(name);
        b.setPreferredSize(new Dimension(10, 32));
        tabButtons.put(name, b);
        tabPanels.put(name, panel);
        tabs.add(panel, name);
        return b;
    }

    private void select(String name)
    {
        activeTab = name;
        tabCards.show(tabs, name);
        tabButtons.forEach((n, b) -> b.setOn(n.equals(name)));
        if (name.equals("Announcements")) announcements.markRead();
    }

    public void refreshActiveTab()
    {
        tabPanels.get(activeTab).refresh();
    }

    // EDT. Logout, profile change, shutdown: close the pop-out windows.
    public void closeWindows()
    {
        dropLog.closeViewer();
        parties.closeWizard();
        leaderboards.closeWindow();
    }

    // A bell, drawn so it needs no asset, with a red dot while there's news you haven't opened.
    private static final class Bell implements Icon
    {
        private final AnnouncementsTab announcements;

        Bell(AnnouncementsTab announcements)
        {
            this.announcements = announcements;
        }

        @Override
        public void paintIcon(Component c, Graphics g, int x, int y)
        {
            Graphics2D g2 = Theme.smooth(g);
            g2.setColor(c.getForeground());
            g2.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Path2D body = new Path2D.Float();
            body.moveTo(x + 3, y + 11);
            body.lineTo(x + 3, y + 7);
            body.curveTo(x + 3, y + 1.5f, x + 13, y + 1.5f, x + 13, y + 7);
            body.lineTo(x + 13, y + 11);
            body.lineTo(x + 14.5f, y + 12.5f);
            body.lineTo(x + 1.5f, y + 12.5f);
            body.closePath();
            g2.draw(body);
            g2.drawLine(x + 6, y + 15, x + 10, y + 15);
            if (announcements.unread())
            {
                g2.setColor(Theme.RED);
                g2.fillOval(x + 11, y - 1, 6, 6);
            }
            g2.dispose();
        }

        @Override
        public int getIconWidth()
        {
            return 16;
        }

        @Override
        public int getIconHeight()
        {
            return 16;
        }
    }

    // EDT. Nobody is logged in: locked, with nothing to wait for.
    public void showLoggedOut()
    {
        status.setText("Log in on your clan character to open the clan panel.");
        retry.setVisible(false);
        cards.show(root, LOCKED);
    }

    // EDT.
    public void show(Clan.Status s)
    {
        switch (s)
        {
            case MEMBER:
                cards.show(root, MAIN);
                return;
            case NOT_MEMBER:
                status.setText("You're not a member of Final Boss.\n\nVisit wiseoldman.net/groups/" + Clan.WOM_GROUP_ID + " for more info.\n\nJust joined? Retry checks again.");
                retry.setVisible(true);
                break;
            case ERROR:
                status.setText("Couldn't verify membership — click to retry.");
                retry.setVisible(true);
                break;
            default:
                status.setText("Verifying clan membership...");
                retry.setVisible(false);
                break;
        }
        cards.show(root, LOCKED);
    }
}

package com.github.orgonag.fbclan.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;

/**
 * Children top to bottom at full width and preferred height, `gap` apart.
 * Nothing stretches or drifts sideways the way it can under BoxLayout.
 */
final class Stack implements LayoutManager
{
    private final int gap;

    Stack(int gap)
    {
        this.gap = gap;
    }

    @Override
    public Dimension preferredLayoutSize(Container parent)
    {
        Insets in = parent.getInsets();
        int width = parent.getWidth() - in.left - in.right;
        int height = 0;
        int widest = 0;
        int shown = 0;
        for (Component c : parent.getComponents())
        {
            if (!c.isVisible()) continue;
            if (width > 0) measureAt(c, width);
            Dimension d = c.getPreferredSize();
            height += d.height + (shown++ > 0 ? gap : 0);
            widest = Math.max(widest, d.width);
        }
        return new Dimension(widest + in.left + in.right, height + in.top + in.bottom);
    }

    @Override
    public Dimension minimumLayoutSize(Container parent)
    {
        return preferredLayoutSize(parent);
    }

    @Override
    public void layoutContainer(Container parent)
    {
        Insets in = parent.getInsets();
        int width = parent.getWidth() - in.left - in.right;
        int y = in.top;
        for (Component c : parent.getComponents())
        {
            if (!c.isVisible()) continue;
            measureAt(c, width);
            int h = c.getPreferredSize().height;
            c.setBounds(in.left, y, width, h);
            y += h + gap;
        }
    }

    @Override
    public void addLayoutComponent(String name, Component comp)
    {
    }

    @Override
    public void removeLayoutComponent(Component comp)
    {
    }

    // Sizing to the real width first lets wrapped text report its true
    // wrapped height. A text area ignores the width while its height is 0
    // (fresh components), so give it room to measure in.
    private static void measureAt(Component c, int width)
    {
        c.setSize(width, c.getHeight() > 0 ? c.getHeight() : Short.MAX_VALUE);
    }
}

package com.github.orgonag.fbclan.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Container;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;

/**
 * One sidebar tab: a heading with a right-hand note, an optional control
 * strip, an error line, and a scrolling list. Refreshes are single-flight.
 */
abstract class Tab extends JPanel
{
    protected final ScheduledExecutorService executor;
    private final JPanel controls = Theme.stack(6);
    protected final JPanel list;
    protected final JLabel note = Theme.text("", Theme.SUB);
    private final JPanel top = Theme.stack(6);
    private final JTextArea error = Theme.wrap("", Theme.RED);
    private final AtomicBoolean refreshing = new AtomicBoolean();

    Tab(String title, ScheduledExecutorService executor)
    {
        super(new BorderLayout());
        this.executor = executor;
        setBackground(Theme.BG);
        top.setBorder(BorderFactory.createEmptyBorder(8, 8, 6, 8));
        top.add(Theme.row(Theme.heading(title), null, note));
        top.add(controls);
        top.add(error);
        controls.setVisible(false);
        error.setVisible(false);
        add(top, BorderLayout.NORTH);
        list = Theme.scroll(this);
    }

    // A control strip line under the heading.
    protected void control(Component c)
    {
        controls.add(c);
        controls.setVisible(true);
    }

    public abstract void refresh();

    // Fetch off the EDT, then render; a second call while one is in flight is dropped.
    protected <T> void load(Supplier<T> fetch, Consumer<T> render)
    {
        if (!refreshing.compareAndSet(false, true)) return;
        Supplier<T> once = () -> {
            try
            {
                return fetch.get();
            }
            finally
            {
                refreshing.set(false);
            }
        };
        Theme.async(executor, once, render, this::showError);
    }

    // EDT. Null clears.
    protected void showError(String message)
    {
        error.setText(message == null ? "" : message);
        error.setVisible(message != null);
        top.revalidate();
    }

    // EDT. Replace the list's contents. A form that is put back (the LFG
    // tab keeps its input rows across refreshes) keeps the keyboard focus.
    protected void fill(Runnable build)
    {
        Component focused = focused(list);
        // Mid-pick in a dropdown: leave it open; the next refresh catches up.
        if (focused instanceof JComboBox && ((JComboBox<?>) focused).isPopupVisible()) return;
        list.removeAll();
        build.run();
        list.revalidate();
        list.repaint();
        if (focused != null && SwingUtilities.isDescendingFrom(focused, list)) focused.requestFocusInWindow();
    }

    // The component inside `root` that has the keyboard focus, else null.
    private static Component focused(Container root)
    {
        for (Component c : root.getComponents())
        {
            if (c.isFocusOwner()) return c;
            Component inner = c instanceof Container ? focused((Container) c) : null;
            if (inner != null) return inner;
        }
        return null;
    }
}

package com.github.orgonag.fbclan.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Graphics;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.Locale;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.plaf.basic.BasicScrollBarUI;
import javax.swing.text.AbstractDocument;
import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.DocumentFilter;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/**
 * The "Loot Feed" look: colour tokens, fonts, and the handful of
 * components every tab is built from. Containers use {@link Stack}, which
 * lays children out top to bottom at full width and preferred height, so
 * nothing stretches or drifts sideways the way BoxLayout does.
 */
final class Theme
{
    static final Color BG = new Color(0x232323);
    static final Color SURFACE = new Color(0x1A1A1A);
    static final Color RAISED = new Color(0x2B2B2B);
    static final Color LINE = new Color(0x3A3A3A);
    static final Color TEXT = Color.WHITE;
    static final Color SOFT = new Color(0xC8C8C8);
    static final Color SUB = new Color(0xA5A5A5);
    static final Color FAINT = new Color(0x7A7A7A);
    static final Color ACCENT = new Color(0xDC8A00);
    static final Color ACCENT_HI = new Color(0xFFB13B);
    static final Color ACCENT_BG = new Color(0x3A2A10);
    static final Color INK = new Color(0x161616);
    static final Color GOLD = new Color(0xFFD700);
    static final Color GREEN = new Color(0x3FBF3F);
    static final Color RED = new Color(0xE07070);

    /** Item tile colouring: how special a drop (or anything else) is. */
    enum Tier
    {
        COMMON(0x6A6A6A, 0x262626), RARE(0x4AA3FF, 0x1D2A38), MEGA(0xB07CFF, 0x2B2236), PET(0xFFB13B, 0x3A2A10);

        final Color edge;
        final Color fill;

        Tier(int edge, int fill)
        {
            this.edge = new Color(edge);
            this.fill = new Color(fill);
        }
    }

    private Theme()
    {
    }

    // ------------------------------------------------------------ threads

    // Fetch on the executor, apply on the EDT. Never block the EDT on network.
    static <T> void async(ScheduledExecutorService executor, Supplier<T> fetch, Consumer<T> apply, Consumer<String> error)
    {
        executor.submit(() -> {
            try
            {
                T result = fetch.get();
                SwingUtilities.invokeLater(() -> { error.accept(null); apply.accept(result); });
            }
            catch (RuntimeException e)
            {
                SwingUtilities.invokeLater(() -> error.accept("Refresh failed. Previous data may be out of date."));
            }
        });
    }

    // ------------------------------------------------------------ containers

    static JPanel stack(int gap)
    {
        JPanel p = new JPanel(new Stack(gap));
        p.setOpaque(false);
        return p;
    }

    // West / centre / east in one line; any part may be null.
    static JPanel row(Component west, Component center, Component east)
    {
        JPanel p = new JPanel(new BorderLayout(7, 0));
        p.setOpaque(false);
        if (west != null) p.add(west, BorderLayout.WEST);
        if (center != null) p.add(center, BorderLayout.CENTER);
        if (east != null) p.add(east, BorderLayout.EAST);
        return p;
    }

    static Card card(Color edge)
    {
        return new Card(SURFACE, edge);
    }

    // A scrolling list filling `host`'s centre; returns the list to fill.
    static JPanel scroll(JPanel host)
    {
        JPanel list = stack(5);
        Viewport view = new Viewport();
        view.add(list, BorderLayout.NORTH);
        JScrollPane pane = new JScrollPane(view);
        pane.setBorder(null);
        pane.getViewport().setBackground(BG);
        slim(pane);
        host.add(pane, BorderLayout.CENTER);
        return list;
    }

    // A thin rounded thumb with no arrows or track, in place of the chunky default.
    static void slim(JScrollPane pane)
    {
        pane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        JScrollBar bar = pane.getVerticalScrollBar();
        bar.setUnitIncrement(16);
        bar.setOpaque(false);
        bar.setPreferredSize(new Dimension(8, 0));
        bar.setUI(new BasicScrollBarUI()
        {
            @Override
            protected void paintTrack(Graphics g, JComponent c, Rectangle r)
            {
            }

            @Override
            protected void paintThumb(Graphics g, JComponent c, Rectangle r)
            {
                if (r.isEmpty()) return;
                Graphics2D g2 = smooth(g);
                g2.setColor(isThumbRollover() || isDragging ? FAINT : LINE);
                g2.fillRoundRect(r.x + 2, r.y + 2, r.width - 4, r.height - 4, 4, 4);
                g2.dispose();
            }

            @Override
            protected JButton createDecreaseButton(int orientation)
            {
                return none();
            }

            @Override
            protected JButton createIncreaseButton(int orientation)
            {
                return none();
            }

            private JButton none()
            {
                JButton b = new JButton();
                b.setPreferredSize(new Dimension(0, 0));
                return b;
            }
        });
    }

    // ------------------------------------------------------------ text

    static JLabel text(String s, Color color)
    {
        JLabel l = new JLabel(s);
        l.putClientProperty("html.disable", Boolean.TRUE);
        l.setForeground(color);
        l.setFont(FontManager.getRunescapeSmallFont());
        return l;
    }

    static JLabel bold(String s, Color color)
    {
        JLabel l = text(s, color);
        l.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        return l;
    }

    static JLabel heading(String s)
    {
        JLabel l = text(s, ACCENT_HI);
        l.setFont(FontManager.getRunescapeBoldFont());
        return l;
    }

    static JLabel caps(String s)
    {
        JLabel l = bold(s.toUpperCase(Locale.ROOT), SUB);
        l.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        return l;
    }

    static JLabel right(JLabel l)
    {
        l.setHorizontalAlignment(SwingConstants.RIGHT);
        return l;
    }

    static JLabel centered(String s)
    {
        JLabel l = text(s, SUB);
        l.setHorizontalAlignment(SwingConstants.CENTER);
        l.setBorder(BorderFactory.createEmptyBorder(14, 0, 14, 0));
        return l;
    }

    // Small filled tag ("TOP DROP", "LATEST").
    static JLabel badge(String s)
    {
        JLabel l = new JLabel(s)
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = smooth(g);
                g2.setColor(ACCENT_HI);
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 5, 5);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        l.setForeground(INK);
        l.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        l.setBorder(BorderFactory.createEmptyBorder(1, 4, 1, 4));
        return l;
    }

    // Multi-line text wrapped to the parent width. A JTextArea, not HTML:
    // Swing's HTML layout under-measures the RuneScape font and clips lines.
    static JTextArea wrap(String s, Color color)
    {
        JTextArea t = new JTextArea(s);
        t.setLineWrap(true);
        t.setWrapStyleWord(true);
        t.setEditable(false);
        t.setFocusable(false);
        t.setHighlighter(null);
        t.setOpaque(false);
        t.setForeground(color);
        t.setFont(FontManager.getRunescapeSmallFont());
        t.setBorder(null);
        return t;
    }

    static String timeAgo(Instant then)
    {
        long minutes = Duration.between(then, Instant.now()).toMinutes();
        if (minutes < 1) return "just now";
        if (minutes < 60) return minutes + "m ago";
        if (minutes < 60 * 24) return (minutes / 60) + "h ago";
        return (minutes / (60 * 24)) + "d ago";
    }

    static String timeAgo(String iso)
    {
        try
        {
            return timeAgo(OffsetDateTime.parse(iso).toInstant());
        }
        catch (RuntimeException e)
        {
            return "";
        }
    }

    // ------------------------------------------------------------ controls

    static Btn button(String s, Btn.Kind kind, Runnable action)
    {
        return new Btn(s, kind, action);
    }

    // Left click anywhere on `c` (children without their own listeners included).
    static <T extends JComponent> T onClick(T c, Runnable action)
    {
        c.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        c.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseReleased(MouseEvent e)
            {
                if (SwingUtilities.isLeftMouseButton(e) && c.contains(e.getPoint())) action.run();
            }
        });
        return c;
    }

    static JTextField field(String value, int max)
    {
        JTextField f = new JTextField(value);
        f.setFont(FontManager.getRunescapeSmallFont());
        ((AbstractDocument) f.getDocument()).setDocumentFilter(new DocumentFilter()
        {
            @Override
            public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs) throws BadLocationException
            {
                if (fb.getDocument().getLength() - length + (text == null ? 0 : text.length()) <= max)
                {
                    super.replace(fb, offset, length, text, attrs);
                }
            }

            @Override
            public void insertString(FilterBypass fb, int offset, String text, AttributeSet attr) throws BadLocationException
            {
                replace(fb, offset, 0, text, attr);
            }
        });
        return f;
    }

    // Runs `action` whenever the field's text changes.
    static void onEdit(JTextField f, Runnable action)
    {
        f.getDocument().addDocumentListener(new DocumentListener()
        {
            public void insertUpdate(DocumentEvent e) { action.run(); }
            public void removeUpdate(DocumentEvent e) { action.run(); }
            public void changedUpdate(DocumentEvent e) { action.run(); }
        });
    }

    // Label on the left, control on the right.
    static JPanel labeled(String label, Component control)
    {
        JLabel l = text(label, SOFT);
        l.setPreferredSize(new Dimension(84, 22));
        return row(l, control, null);
    }

    // An item sprite on a rounded tile coloured by tier.
    static JLabel tile(ItemManager items, int itemId, int quantity, Tier tier, int size)
    {
        JLabel l = new JLabel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = smooth(g);
                g2.setColor(tier.fill);
                g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 6, 6);
                g2.setColor(tier.edge);
                g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 6, 6);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        l.setHorizontalAlignment(SwingConstants.CENTER);
        l.setPreferredSize(new Dimension(size, size));
        items.getImage(itemId, Math.max(1, quantity), quantity > 1).addTo(l);
        return l;
    }

    // Party slots: one segment per seat (a bar past 12 seats).
    static JComponent seats(int filled, int capacity)
    {
        JComponent c = new JComponent()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = smooth(g);
                int w = getWidth();
                if (capacity > 12)
                {
                    g2.setColor(RAISED);
                    g2.fillRoundRect(0, 0, w, 6, 6, 6);
                    g2.setColor(GREEN);
                    g2.fillRoundRect(0, 0, Math.max(6, w * Math.min(filled, capacity) / capacity), 6, 6, 6);
                }
                else
                {
                    int gap = 3;
                    int seat = (w - gap * (capacity - 1)) / capacity;
                    for (int i = 0; i < capacity; i++)
                    {
                        int x = i * (seat + gap);
                        if (i < filled)
                        {
                            g2.setColor(GREEN);
                            g2.fillRoundRect(x, 0, seat, 6, 4, 4);
                        }
                        else
                        {
                            g2.setColor(LINE);
                            g2.drawRoundRect(x, 0, seat - 1, 5, 4, 4);
                        }
                    }
                }
                g2.dispose();
            }
        };
        c.setPreferredSize(new Dimension(10, 6));
        return c;
    }

    static Graphics2D smooth(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        return g2;
    }

    // Tracks the viewport width so wrapped rows wrap to the real panel width.
    static final class Viewport extends JPanel implements Scrollable
    {
        Viewport()
        {
            super(new BorderLayout());
            setBackground(BG);
            setBorder(BorderFactory.createEmptyBorder(0, 8, 8, 8));
        }

        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle r, int o, int d)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle r, int o, int d)
        {
            return 64;
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.lfg.Party;
import java.awt.Component;
import java.awt.GridLayout;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Arrays;
import java.util.Locale;
import java.util.function.Function;
import javax.swing.DefaultComboBoxModel;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.ListCellRenderer;

/**
 * When a post starts: ASAP, or Later with a day and a time (local zone,
 * 15-minute steps) no more than 7 days after the post was created.
 */
final class WhenPicker extends JPanel
{
    private static final String ASAP = "ASAP";
    private static final String LATER = "Later";
    private static final DateTimeFormatter DAY = DateTimeFormatter.ofPattern("EEE d MMM", Locale.ENGLISH);
    private static final DateTimeFormatter SUMMARY = DateTimeFormatter.ofPattern("EEE d MMM, HH:mm", Locale.ENGLISH);

    /** Which start-time choices the host still has (the post being edited excluded). */
    static final class Limits
    {
        final boolean asapTaken;
        final boolean laterFull;

        Limits(boolean asapTaken, boolean laterFull)
        {
            this.asapTaken = asapTaken;
            this.laterFull = laterFull;
        }
    }

    private final ZoneId zone = ZoneId.systemDefault();
    private final Instant windowEnd;
    // The edited post's start time, else null.
    private final Instant original;
    private final Choice<String> choice;
    private final JComboBox<LocalDate> dayBox = new JComboBox<>();
    private final JComboBox<Integer> hourBox = new JComboBox<>();
    private final JComboBox<Integer> minuteBox = new JComboBox<>(new Integer[]{0, 15, 30, 45});
    private final JLabel summary = Theme.text("", Theme.SOFT);
    private final JPanel later = Theme.stack(10);

    // `editing` = the post being edited, else null.
    WhenPicker(Party editing, Limits limits)
    {
        super(new Stack(10));
        setOpaque(false);
        windowEnd = (editing == null ? Instant.now() : editing.getCreatedAt()).plus(Party.LIFETIME);
        original = editing != null && editing.isScheduled() ? editing.getScheduledFor() : null;

        LocalDate end = windowEnd.atZone(zone).toLocalDate();
        for (LocalDate d = LocalDate.now(zone); !d.isAfter(end); d = d.plusDays(1)) dayBox.addItem(d);
        for (int h = 0; h < 24; h++) hourBox.addItem(h);
        dayBox.setRenderer(render(v -> {
            LocalDate today = LocalDate.now(zone);
            LocalDate d = (LocalDate) v;
            return d.equals(today) ? "Today" : d.equals(today.plusDays(1)) ? "Tomorrow" : DAY.format(d);
        }));
        hourBox.setRenderer(render(v -> String.format("%02d", v)));
        minuteBox.setRenderer(render(v -> String.format("%02d", v)));

        // An edited post keeps its own time selectable (even if it has passed
        // or isn't on a 15-minute mark); a new one defaults to the next whole
        // hour at least 30 minutes away.
        ZonedDateTime start = original != null ? original.atZone(zone)
            : ZonedDateTime.now(zone).plusMinutes(30).plusHours(1).withMinute(0).withSecond(0).withNano(0);
        if (original != null)
        {
            if (((DefaultComboBoxModel<LocalDate>) dayBox.getModel()).getIndexOf(start.toLocalDate()) < 0) dayBox.insertItemAt(start.toLocalDate(), 0);
            if (((DefaultComboBoxModel<Integer>) minuteBox.getModel()).getIndexOf(start.getMinute()) < 0) minuteBox.addItem(start.getMinute());
        }
        dayBox.setSelectedItem(start.toLocalDate());
        hourBox.setSelectedItem(start.getHour());
        minuteBox.setSelectedItem(original != null ? start.getMinute() : start.getMinute() - start.getMinute() % 15);
        dayBox.addActionListener(e -> summarize());
        hourBox.addActionListener(e -> summarize());
        minuteBox.addActionListener(e -> summarize());

        choice = new Choice<>(Arrays.asList(ASAP, LATER), s -> s, ASAP, s -> showLater());
        choice.enable(ASAP, !limits.asapTaken, "You already have an ASAP party");
        choice.enable(LATER, !limits.laterFull, "You already have 7 scheduled parties");
        choice.set(editing != null ? (original != null ? LATER : ASAP) : (limits.asapTaken ? LATER : ASAP));

        JPanel time = new JPanel(new GridLayout(1, 2, 6, 0));
        time.setOpaque(false);
        time.add(hourBox);
        time.add(minuteBox);
        later.add(Theme.labeled("Day", dayBox));
        later.add(Theme.labeled("Time", time));
        later.add(summary);
        add(Theme.text("When", Theme.SUB));
        add(choice);
        add(later);
        showLater();
    }

    // The chosen start, or null for ASAP. Throws with a readable reason when unusable.
    Instant start()
    {
        if (!LATER.equals(choice.value())) return null;
        LocalDate day = (LocalDate) dayBox.getSelectedItem();
        if (day == null) throw new IllegalArgumentException("Pick a day.");
        Instant at = ZonedDateTime.of(day, LocalTime.of((Integer) hourBox.getSelectedItem(), (Integer) minuteBox.getSelectedItem()), zone).toInstant();
        // An unchanged time is fine even if it has passed (the server only checks a changed one).
        if (original != null && at.getEpochSecond() / 60 == original.getEpochSecond() / 60) return original;
        if (!at.isAfter(Instant.now().plusSeconds(60))) throw new IllegalArgumentException("Pick a start time in the future.");
        if (at.isAfter(windowEnd)) throw new IllegalArgumentException("Start time must be within 7 days of posting.");
        return at;
    }

    private void showLater()
    {
        later.setVisible(LATER.equals(choice.value()));
        summarize();
        revalidate();
        repaint();
    }

    // "Sat 5 Oct, 20:00 · in 2d 4h (your time)", or the reason it can't be used.
    // Also called when the host window redraws, so the countdown never goes stale.
    void summarize()
    {
        try
        {
            Instant at = start();
            if (at == null) return;
            summary.setForeground(Theme.SOFT);
            Duration until = Duration.between(Instant.now(), at);
            summary.setText(SUMMARY.withZone(zone).format(at) + (until.isNegative() ? " · already passed" : " · in " + LfgUi.span(until)) + " (your time)");
        }
        catch (IllegalArgumentException e)
        {
            summary.setForeground(Theme.RED);
            summary.setText(e.getMessage());
        }
    }

    private static ListCellRenderer<Object> render(Function<Object, String> text)
    {
        return new DefaultListCellRenderer()
        {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus)
            {
                return super.getListCellRendererComponent(list, value == null ? null : text.apply(value), index, selected, focus);
            }
        };
    }
}

